_CONVERTER_TEMP_DIRS: List[Path] = []


def _cleanup_converter_temp_dirs() -> None:
    for temp_dir in reversed(_CONVERTER_TEMP_DIRS):
        shutil.rmtree(temp_dir, ignore_errors=True)


atexit.register(_cleanup_converter_temp_dirs)


