@dataclass
class Offset:
    x: float = 0.0
    y: float = 0.0
    z: float = 0.0
    r: float = 0.0

    def is_default(self) -> bool:
        return self.x == 0 and self.y == 0 and self.z == 0 and self.r == 0

    def to_json(self) -> Dict[str, float]:
        data: Dict[str, float] = {}
        if self.x:
            data["x"] = self.x
        if self.y:
            data["y"] = self.y
        if self.z:
            data["z"] = self.z
        if self.r:
            data["r"] = self.r
        return data


@dataclass
class Speed:
    animation: str
    playback_speed: Optional[float] = None
    display_speed: Optional[float] = None
    sexlab_sound: str = ""
    source_animation: str = ""

    def to_json(self) -> Dict[str, Any]:
        data: Dict[str, Any] = {"animation": self.animation}
        if self.playback_speed is not None:
            data["playbackSpeed"] = self.playback_speed
        if self.display_speed is not None:
            data["displaySpeed"] = self.display_speed
        return data


@dataclass
class Actor:
    type: str = "npc"
    intended_sex: str = ""
    sos_bend: int = 0
    scale: float = 1.0
    scale_height: float = DEFAULT_SCALE_HEIGHT
    animation_index: Optional[int] = None
    underlying_expression: str = ""
    expression_action: Optional[int] = None
    expression_override: str = ""
    look_up: Optional[int] = None
    look_left: Optional[int] = None
    no_strip: bool = False
    feet_on_ground: Optional[bool] = None
    offset: Offset = field(default_factory=Offset)
    requirements: List[str] = field(default_factory=list)
    tags: List[str] = field(default_factory=list)
    auto_transitions: Dict[str, str] = field(default_factory=dict)
    creature_race: str = ""
    sexlab_sex_flags: Dict[str, bool] = field(default_factory=dict, repr=False)

    def to_json(self, index: int) -> Dict[str, Any]:
        data: Dict[str, Any] = {}
        if self.type and self.type != "npc":
            data["type"] = self.type
        if self.intended_sex:
            data["intendedSex"] = self.intended_sex
        if self.sos_bend:
            data["sosBend"] = self.sos_bend
        if self.scale != 1.0:
            data["scale"] = self.scale
        if self.scale_height != DEFAULT_SCALE_HEIGHT:
            data["scaleHeight"] = self.scale_height
        if self.animation_index is not None and self.animation_index != index:
            data["animationIndex"] = self.animation_index
        if self.underlying_expression:
            data["underlyingExpression"] = self.underlying_expression
        if self.expression_action is not None:
            data["expressionAction"] = self.expression_action
        if self.expression_override:
            data["expressionOverride"] = self.expression_override
        if self.look_up is not None:
            if self.look_up >= 0:
                data["lookUp"] = self.look_up
            else:
                data["lookDown"] = abs(self.look_up)
        if self.look_left is not None:
            if self.look_left >= 0:
                data["lookLeft"] = self.look_left
            else:
                data["lookRight"] = abs(self.look_left)
        if self.no_strip:
            data["noStrip"] = True
        if self.feet_on_ground is not None:
            data["feetOnGround"] = self.feet_on_ground
        if not self.offset.is_default():
            data["offset"] = self.offset.to_json()
        if self.requirements:
            data["requirements"] = self.requirements
        if self.tags:
            data["tags"] = sorted(set(self.tags), key=self.tags.index)
        if self.auto_transitions:
            data["autoTransitions"] = self.auto_transitions
        if self.creature_race:
            data["creatureRace"] = self.creature_race
        return data


@dataclass
class Action:
    type: str
    actor: int
    target: Optional[int] = None
    performer: Optional[int] = None
    muted: bool = False
    do_peaks: Optional[bool] = None
    peaks_annotated: Optional[bool] = None

    def max_actor_index(self) -> int:
        return max(self.actor, self.target if self.target is not None else self.actor, self.performer if self.performer is not None else self.actor)

    def to_json(self) -> Dict[str, Any]:
        data: Dict[str, Any] = {"type": self.type, "actor": self.actor}
        if self.target is not None and self.target != self.actor:
            data["target"] = self.target
        if self.performer is not None and self.performer != self.actor:
            data["performer"] = self.performer
        if self.muted:
            data["muted"] = True
        if self.do_peaks is not None:
            data["doPeaks"] = self.do_peaks
        if self.peaks_annotated is not None:
            data["peaksAnnotated"] = self.peaks_annotated
        return data


@dataclass
class Navigation:
    destination: Optional[str] = None
    origin: Optional[str] = None
    priority: Optional[int] = None
    description: str = ""
    icon: str = ""
    border: str = ""
    no_warnings: bool = False

    def remap(self, id_map: Dict[str, str], fallback_prefix: str, current_raw_id: str = "") -> None:
        if self.destination:
            self.destination = map_scene_ref(self.destination, id_map, fallback_prefix, current_raw_id)
        if self.origin:
            self.origin = map_scene_ref(self.origin, id_map, fallback_prefix, current_raw_id)

    def to_json(self) -> Dict[str, Any]:
        data: Dict[str, Any] = {}
        if self.destination:
            data["destination"] = self.destination
        if self.origin:
            data["origin"] = self.origin
        if self.priority is not None:
            data["priority"] = self.priority
        if self.description:
            data["description"] = self.description
        if self.icon:
            data["icon"] = self.icon
        if self.border:
            data["border"] = self.border
        if self.no_warnings:
            data["noWarnings"] = True
        return data


@dataclass
class Scene:
    raw_id: str
    scene_id: str = ""
    name: str = ""
    modpack: str = ""
    length: float = DEFAULT_LENGTH
    speeds: List[Speed] = field(default_factory=list)
    default_speed: int = 0
    destination: Optional[str] = None
    origin: Optional[str] = None
    priority: Optional[int] = None
    description: str = ""
    icon: str = ""
    border: str = ""
    no_warnings: bool = False
    no_random_selection: bool = False
    fade_on_entry: bool = False
    furniture: str = "none"
    offset: Offset = field(default_factory=Offset)
    scale_offset_with_furniture: bool = False
    tags: List[str] = field(default_factory=list)
    actors: List[Actor] = field(default_factory=list)
    actions: List[Action] = field(default_factory=list)
    navigations: List[Navigation] = field(default_factory=list)
    sexlab_sound: str = ""
    source_framework: str = ""
    source_animation_id: str = ""
    source_lifecycle_key: str = ""
    source_json: str = ""

    def ensure_actor_count(self, count: int) -> None:
        while len(self.actors) < count:
            self.actors.append(Actor(animation_index=len(self.actors)))

    def finalize_actor_count(self) -> None:
        count = len(self.actors)
        for action in self.actions:
            count = max(count, action.max_actor_index() + 1)
        self.ensure_actor_count(count)
        for i, actor in enumerate(self.actors):
            if actor.animation_index is None:
                actor.animation_index = i

    def remap_ids(self, id_map: Dict[str, str], fallback_prefix: str) -> None:
        if self.destination:
            self.destination = map_scene_ref(self.destination, id_map, fallback_prefix, self.raw_id)
        if self.origin:
            self.origin = map_scene_ref(self.origin, id_map, fallback_prefix, self.raw_id)
        for nav in self.navigations:
            nav.remap(id_map, fallback_prefix, self.raw_id)
        for actor in self.actors:
            actor.auto_transitions = {
                key: map_scene_ref(value, id_map, fallback_prefix, self.raw_id)
                for key, value in actor.auto_transitions.items()
            }

    def to_json(self, pack_display_name: str) -> Dict[str, Any]:
        self.finalize_actor_count()
        data: Dict[str, Any] = {
            "name": self.name or self.raw_id or self.scene_id,
            "modpack": pack_display_name,
            "length": self.length,
            "speeds": [speed.to_json() for speed in self.speeds],
            "actors": [actor.to_json(i) for i, actor in enumerate(self.actors)],
        }
        if self.destination or self.origin:
            if self.destination:
                data["destination"] = self.destination
            if self.origin:
                data["origin"] = self.origin
            if self.priority is not None:
                data["priority"] = self.priority
            if self.description:
                data["description"] = self.description
            if self.icon:
                data["icon"] = self.icon
            if self.border:
                data["border"] = self.border
            if self.no_warnings:
                data["noWarnings"] = True
        elif self.navigations:
            data["navigations"] = [nav.to_json() for nav in self.navigations]
        if self.default_speed:
            data["defaultSpeed"] = self.default_speed
        if self.no_random_selection:
            data["noRandomSelection"] = True
        if self.fade_on_entry:
            data["fadeOnEntry"] = True
        if self.furniture and self.furniture != "none":
            data["furniture"] = self.furniture
        if not self.offset.is_default():
            data["offset"] = self.offset.to_json()
        if self.scale_offset_with_furniture:
            data["scaleOffsetWithFurniture"] = True
        if self.tags:
            data["tags"] = sorted(set(self.tags), key=self.tags.index)
        if self.actions:
            data["actions"] = [action.to_json() for action in self.actions]
        return data


