def norm_slashes(value: str) -> str:
    return re.sub(r"[\\/]+", "/", value)


def resource_path(relative: Path | str) -> Path:
    base = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parent))
    return base / relative


def app_base_dir() -> Path:
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path(__file__).resolve().parent


def app_settings_dir() -> Path:
    if os.name == "nt":
        base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA")
        if base:
            return Path(base) / APP_NAME
    safe_name = re.sub(r"[^a-z0-9]+", "", APP_NAME.lower()) or "adultanimationconverter"
    try:
        return Path.home() / f".{safe_name}"
    except RuntimeError:
        return Path(tempfile.gettempdir()) / safe_name


def app_settings_path() -> Path:
    return app_settings_dir() / APP_SETTINGS_FILE


def load_app_settings() -> Dict[str, Any]:
    path = app_settings_path()
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def save_app_settings(settings: Dict[str, Any]) -> None:
    safe_keys = {
        "lastOutputFolder",
        "sfxFallbackAction",
        "addOStimMenuEntry",
        "ostimMenuIcon",
        "humanOnlyOStimOutput",
        "sexLabPlusExport",
        "sexLabDiscoveryTags",
        "sevenZipPath",
        "legacyHkxConverterPath",
        "slsbRepoPath",
        "nemesisSafeOutput",
        "debugMode",
        "uiMode",
        "advancedOptionsExpanded",
        "openOutputAfterBuild",
        "lastHumanReport",
        "lastJsonReport",
        "lastOStimToolsProjectOutputFolder",
        "lastOStimToolsTemplatePath",
        "ostimToolsIncludeActions",
        "ostimToolsIncludeAlignment",
        "ostimToolsAlignmentTemplate",
        "ostimToolsIncludeSourceMetadata",
        "ostimToolsMenuScaffold",
        "ostimToolsSceneJsonFolderMode",
    }
    filtered = {key: value for key, value in settings.items() if key in safe_keys}
    try:
        path = app_settings_path()
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(filtered, indent=2, ensure_ascii=False), encoding="utf-8")
    except OSError:
        pass


def app_debug_mode(default: bool = False) -> bool:
    env = os.environ.get("AAC_DEBUG")
    if env is not None:
        return env.strip().lower() in {"1", "true", "yes", "y", "on"}
    settings = load_app_settings()
    value = settings.get("debugMode")
    return bool(value) if isinstance(value, bool) else default


def public_path_text(path: Optional[Path | str], debug_mode: bool = False) -> str:
    if not path:
        return "not written"
    try:
        resolved = Path(path)
    except TypeError:
        return str(path)
    return str(resolved) if debug_mode else resolved.name


def local_path_leaf_text(value: str) -> str:
    normalized = norm_slashes(value.strip())
    if not normalized:
        return "<local path>"
    suffix = ""
    while normalized and normalized[-1] in ".,;":
        suffix = normalized[-1] + suffix
        normalized = normalized[:-1]
    leaf = PurePosixPath(normalized).name or "<local path>"
    return leaf + suffix


WINDOWS_LOCAL_PATH_RE = re.compile(r"(?<![A-Za-z0-9_])(?:[A-Za-z]:[\\/][^\r\n\"<>|]*)")
UNC_LOCAL_PATH_RE = re.compile(r"(?<![A-Za-z0-9_])(?:\\\\[^\\/\s]+[\\/][^\\/\s]+[\\/][^\r\n\"<>|]*)")
UNIX_LOCAL_PATH_RE = re.compile(r"(?<![A-Za-z0-9_])(?:/(?:Users|home|tmp|var/folders|private/var)[^\r\n\"<>|]*)")


def public_safe_text(value: str, debug_mode: bool = False) -> str:
    if debug_mode:
        return value
    text = WINDOWS_LOCAL_PATH_RE.sub(lambda match: local_path_leaf_text(match.group(0)), value)
    text = UNC_LOCAL_PATH_RE.sub(lambda match: local_path_leaf_text(match.group(0)), text)
    text = UNIX_LOCAL_PATH_RE.sub(lambda match: local_path_leaf_text(match.group(0)), text)
    return text


def error_log_dir() -> Path:
    return app_settings_dir() / "error_logs"


def error_log_path() -> Path:
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    return error_log_dir() / f"aac_error_{stamp}.txt"


def format_internal_error_summary(
    exc: BaseException,
    *,
    operation: str = "not recorded",
    source_archive: Optional[Path | str] = None,
    debug_mode: bool = False,
    log_path: Optional[Path] = None,
) -> str:
    archive_name = "not selected"
    if source_archive:
        try:
            archive_name = Path(source_archive).name if not debug_mode else str(Path(source_archive))
        except (TypeError, ValueError):
            archive_name = str(source_archive)
    lines = [
        f"{APP_NAME} {CONVERTER_VERSION}",
        f"Error type: {type(exc).__name__}",
        f"Error message: {public_safe_text(str(exc), debug_mode=debug_mode)}",
        f"Operation: {operation or 'not recorded'}",
        f"Selected source archive: {archive_name}",
        f"Debug mode: {public_bool(debug_mode)}",
    ]
    if log_path is not None:
        lines.append(f"Error log: {log_path}")
    return "\n".join(lines)


def write_internal_error_log(
    exc: BaseException,
    traceback_text: str,
    *,
    operation: str = "not recorded",
    source_archive: Optional[Path | str] = None,
    debug_mode: bool = False,
) -> Tuple[Optional[Path], str]:
    path: Optional[Path] = None
    try:
        error_log_dir().mkdir(parents=True, exist_ok=True)
        path = error_log_path()
        summary = format_internal_error_summary(
            exc,
            operation=operation,
            source_archive=source_archive,
            debug_mode=debug_mode,
            log_path=path,
        )
        body = "\n".join(
            [
                summary,
                "",
                "Traceback:",
                traceback_text.rstrip() or "".join(traceback.format_exception(exc)).rstrip(),
                "",
            ]
        )
        path.write_text(body, encoding="utf-8")
        return path, summary
    except OSError as log_exc:
        summary = format_internal_error_summary(
            exc,
            operation=operation,
            source_archive=source_archive,
            debug_mode=debug_mode,
            log_path=None,
        )
        return None, f"{summary}\nError log could not be written: {log_exc}"


def can_open_path(path: Optional[Path | str]) -> bool:
    if not path:
        return False
    try:
        return Path(path).exists()
    except (TypeError, ValueError, OSError):
        return False


def public_bool(value: Any) -> str:
    if value is True:
        return "yes"
    if value is False:
        return "no"
    return "unknown"


def compatibility_database_paths(extra_paths: Sequence[Path | str] = ()) -> List[Path]:
    candidates: List[Path] = []

    def add(value: Optional[Path | str]) -> None:
        if value is None:
            return
        try:
            path = Path(value).expanduser()
        except (TypeError, ValueError):
            return
        if path not in candidates:
            candidates.append(path)

    add(os.environ.get("AAC_COMPATIBILITY_DB"))
    for extra in extra_paths:
        add(extra)
    add(app_settings_dir() / COMPATIBILITY_DB_FILE)
    add(app_base_dir() / COMPATIBILITY_DB_FILE)
    add(Path.cwd() / COMPATIBILITY_DB_FILE)
    return candidates


def compatibility_database_folder() -> Path:
    return app_settings_dir()


def normalize_string_list(value: Any) -> List[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, Sequence) and not isinstance(value, (bytes, bytearray, str)):
        return [str(item) for item in value if item is not None]
    return []


def json_type_name(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, dict):
        return "object"
    if isinstance(value, list):
        return "array"
    if isinstance(value, str):
        return "string"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return type(value).__name__


def as_dict(value: Any, default: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    return value if isinstance(value, dict) else dict(default or {})


def dict_or_empty(value: Any) -> Dict[str, Any]:
    return as_dict(value)


def as_list(value: Any, default: Optional[List[Any]] = None) -> List[Any]:
    return value if isinstance(value, list) else list(default or [])


def as_str(value: Any, default: str = "") -> str:
    if isinstance(value, str):
        return value
    if value is None:
        return default
    return str(value)


def report_example_items(value: Any) -> List[Any]:
    """Return examples from either a raw list or a public-safe report wrapper."""
    if isinstance(value, dict):
        return as_list(value.get("examples"))
    return as_list(value)


def report_item_label(value: Any, *keys: str) -> str:
    if isinstance(value, dict):
        for key in keys:
            label = as_str(value.get(key)).strip()
            if label:
                return label
        return ""
    return as_str(value).strip()


def safe_get(value: Any, key: str, default: Any = None) -> Any:
    return value.get(key, default) if isinstance(value, dict) else default


def normalize_dict_list(value: Any) -> List[Dict[str, Any]]:
    if isinstance(value, dict):
        iterable = value.values()
    elif isinstance(value, list):
        iterable = value
    else:
        return []
    return [item for item in iterable if isinstance(item, dict)]


def require_dict(value: Any, context: str) -> Dict[str, Any]:
    if not isinstance(value, dict):
        raise TypeError(f"{context}: expected object, got {json_type_name(value)}.")
    return value


def require_list(value: Any, context: str) -> List[Any]:
    if not isinstance(value, list):
        raise TypeError(f"{context}: expected array, got {json_type_name(value)}.")
    return value


def unexpected_field_type_message(context: str, expected: str, value: Any) -> str:
    return f"Unexpected {context} type: expected {expected}, got {json_type_name(value)}."


def first_string(entry: Dict[str, Any], *keys: str) -> Optional[str]:
    entry = dict_or_empty(entry)
    for key in keys:
        value = entry.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


def first_bool(entry: Dict[str, Any], *keys: str) -> Optional[bool]:
    entry = dict_or_empty(entry)
    for key in keys:
        if key not in entry:
            continue
        value = entry.get(key)
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            lowered = value.strip().lower()
            if lowered in {"1", "true", "yes", "y", "on"}:
                return True
            if lowered in {"0", "false", "no", "n", "off"}:
                return False
    return None


def validate_compatibility_entry(raw: Any, index: int) -> Tuple[Optional[Dict[str, Any]], List[str]]:
    warnings: List[str] = []
    if not isinstance(raw, dict):
        return None, [f"Entry {index} is not an object and was ignored."]
    display_name = first_string(raw, "packDisplayName", "name", "displayName")
    if not display_name:
        return None, [f"Entry {index} has no packDisplayName/name and was ignored."]
    entry = dict(raw)
    entry["packDisplayName"] = display_name
    if not first_string(entry, "id"):
        entry["id"] = sanitize_name(display_name, f"profile{index}")
    for key in (
        "id",
        "packDisplayName",
        "name",
        "displayName",
        "status",
        "safePackName",
        "sourceFramework",
        "recommendedOutputType",
        "recommendedOutput",
        "recommendedBehaviorTool",
        "recommendedOStimToolsMode",
        "minimumConverterVersionRecommended",
        "minimumConverterVersion",
    ):
        if key in entry and entry.get(key) is not None and not isinstance(entry.get(key), str):
            warnings.append(unexpected_field_type_message(f"entry {index}.{key}", "string", entry.get(key)))
            entry.pop(key, None)
    for key in (
        "defaultHumanOnlyOStim",
        "creatureOutputRecommended",
        "creatureRuntimeRequired",
        "ostimToolsSupported",
    ):
        if key in entry and entry.get(key) is not None and not isinstance(entry.get(key), bool):
            coerced = first_bool(entry, key)
            if coerced is None:
                warnings.append(unexpected_field_type_message(f"entry {index}.{key}", "boolean", entry.get(key)))
                entry.pop(key, None)
            else:
                entry[key] = coerced
    for key in (
        "archiveFingerprints",
        "filePatterns",
        "folderPatterns",
        "namePatterns",
        "archiveNamePatterns",
        "supportedOutputTypes",
        "knownWarnings",
        "knownIssues",
        "notes",
        "limitations",
        "runtimeRequirements",
        "sourceTypeCodes",
        "creatureNotes",
        "ostimToolsNotes",
        "fallbackSourceParsers",
        "sourceBranchPatterns",
        "ignoredBranchPatterns",
        "expectedMixedSourceTypes",
    ):
        if key in entry:
            original = entry.get(key)
            if not isinstance(original, (str, list, tuple)):
                warnings.append(unexpected_field_type_message(f"entry {index}.{key}", "string or array", original))
            entry[key] = normalize_string_list(entry.get(key))
    for key in ("knownPackMatch", "compatibilityMatch", "database"):
        if key in entry and entry.get(key) is not None and not isinstance(entry.get(key), dict):
            warnings.append(unexpected_field_type_message(f"entry {index}.{key}", "object", entry.get(key)))
            entry.pop(key, None)
    return entry, warnings


def load_compatibility_database(extra_paths: Sequence[Path | str] = ()) -> Dict[str, Any]:
    entries: List[Dict[str, Any]] = []
    warnings: List[str] = []
    versions: List[str] = []
    loaded_files: List[str] = []
    seen_paths: set[str] = set()
    for path in compatibility_database_paths(extra_paths):
        path_key = str(path.resolve()) if path.exists() else str(path)
        if path_key in seen_paths:
            continue
        seen_paths.add(path_key)
        if not path.exists():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception as exc:
            warnings.append(f"{path.name}: could not load compatibility database: {exc}")
            continue
        if not isinstance(data, dict):
            warnings.append(f"{path.name}: compatibility database root must be an object.")
            continue
        version = data.get("version")
        if version:
            versions.append(str(version))
        raw_entries = data.get("entries")
        if not isinstance(raw_entries, list):
            warnings.append(f"{path.name}: compatibility database has no entries list.")
            continue
        loaded_files.append(path.name)
        for index, raw_entry in enumerate(raw_entries, start=1):
            entry, entry_warnings = validate_compatibility_entry(raw_entry, index)
            warnings.extend(f"{path.name}: {warning}" for warning in entry_warnings)
            if entry is not None:
                entry["_databaseFile"] = path.name
                entries.append(entry)
    return {
        "loaded": bool(entries or loaded_files),
        "version": ", ".join(sorted(set(versions), key=str.lower)) if versions else None,
        "entries": entries,
        "warnings": warnings,
        "files": loaded_files,
    }


def source_type_matches_profile(entry: Dict[str, Any], source_detection: Optional[Dict[str, Any]]) -> bool:
    source_detection = dict_or_empty(source_detection)
    if not source_detection:
        return False
    selected = str(source_detection.get("selectedSourceType") or "").lower()
    labels = [str(item).lower() for item in source_detection.get("detectedSourceTypes") or []]
    profile_values = [value.lower() for value in normalize_string_list(entry.get("sourceTypeCodes"))]
    source_framework = first_string(entry, "sourceFramework")
    if source_framework:
        profile_values.append(source_framework.lower())
    if not profile_values:
        return False
    return any(value == selected or value in labels for value in profile_values)


def archive_fingerprint_matches(entry: Dict[str, Any], fingerprint: Dict[str, Any]) -> bool:
    fingerprint = dict_or_empty(fingerprint)
    known = {value.lower() for value in normalize_string_list(entry.get("archiveFingerprints"))}
    if not known:
        return False
    candidates = {
        str(fingerprint.get("sha256") or "").lower(),
        str(fingerprint.get("partialSha256") or "").lower(),
    }
    return bool(known & {candidate for candidate in candidates if candidate})


def pattern_matches_any(patterns: Sequence[str], values: Sequence[str]) -> int:
    matches = 0
    lowered_values = [value.lower() for value in values]
    for raw_pattern in patterns:
        pattern = norm_slashes(str(raw_pattern)).lower().strip()
        if not pattern:
            continue
        wildcard = any(token in pattern for token in "*?[]")
        patterns = [pattern]
        if pattern.startswith("*/"):
            patterns.append(pattern[2:])
        if any(
            fnmatch.fnmatch(value, candidate) if wildcard else candidate in value
            for candidate in patterns
            for value in lowered_values
        ):
            matches += 1
    return matches


def extracted_relative_paths(extracted_root: Optional[Path]) -> Tuple[List[str], List[str]]:
    if not extracted_root or not extracted_root.exists():
        return [], []
    files: List[str] = []
    folders: set[str] = set()
    for path in extracted_root.rglob("*"):
        try:
            rel = norm_slashes(PurePosixPath(*path.relative_to(extracted_root).parts).as_posix())
        except ValueError:
            continue
        if path.is_file():
            files.append(rel)
        elif path.is_dir():
            folders.add(rel)
    return files, sorted(folders, key=str.lower)


def known_pack_none_match(database: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    db = database or load_compatibility_database()
    return {
        "matchResult": "None",
        "matchedPack": None,
        "profileId": None,
        "confidence": "Low",
        "status": None,
        "supportedOutputs": [],
        "recommendedOutput": None,
        "recommendedBehaviorTool": None,
        "knownLimitations": [],
        "knownWarnings": [],
        "knownIssues": [],
        "minimumRecommendedConverterVersion": None,
        "defaultHumanOnlyOStim": None,
        "creatureOutputRecommended": None,
        "creatureRuntimeRequired": None,
        "creatureNotes": [],
        "ostimToolsSupported": None,
        "recommendedOStimToolsMode": None,
        "ostimToolsNotes": [],
        "templateRecommended": None,
        "sourceMetadataRecommended": None,
        "alignmentRecommended": None,
        "preferredSourceParser": None,
        "fallbackSourceParsers": [],
        "sourceBranchPatterns": [],
        "ignoredBranchPatterns": [],
        "expectedMixedSourceTypes": [],
        "expectedDuplicateHkxHighCount": None,
        "recommendedNormalUserWorkflow": None,
        "recommendedCreatureUserWorkflow": None,
        "recommendedPPlusWorkflow": None,
        "recommendedOstimToolsWorkflow": None,
        "duplicateHkxPolicy": None,
        "customFurniturePolicy": None,
        "notes": ["No known compatibility profile matched this archive."],
        "database": {
            "loaded": bool(db.get("loaded")),
            "version": db.get("version"),
            "files": db.get("files") or [],
            "warningCount": len(db.get("warnings") or []),
            "warnings": db.get("warnings") or [],
        },
    }


def match_compatibility_profile(
    archive: Optional[Path],
    extracted_root: Optional[Path] = None,
    source_detection: Optional[Dict[str, Any]] = None,
    fingerprint: Optional[Dict[str, Any]] = None,
    database: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    db = dict_or_empty(database) or load_compatibility_database()
    entries = db.get("entries") or []
    if not entries:
        return known_pack_none_match(db)

    archive_name = archive.name if archive else ""
    fingerprint = dict_or_empty(fingerprint) or source_archive_fingerprint(archive)
    files, folders = extracted_relative_paths(extracted_root)
    best: Optional[Tuple[int, str, Dict[str, Any], List[str]]] = None

    for entry in entries:
        score = 0
        reasons: List[str] = []
        if archive_fingerprint_matches(entry, fingerprint):
            score += 100
            reasons.append("archive fingerprint")
        name_patterns = [
            *normalize_string_list(entry.get("namePatterns")),
            *normalize_string_list(entry.get("archiveNamePatterns")),
        ]
        display_name = first_string(entry, "packDisplayName")
        if display_name:
            name_patterns.append(display_name)
        name_matches = pattern_matches_any(name_patterns, [archive_name])
        if name_matches:
            score += 30 + min(name_matches, 3) * 5
            reasons.append("archive name")
        file_matches = pattern_matches_any(normalize_string_list(entry.get("filePatterns")), files)
        if file_matches:
            score += min(file_matches, 6) * 10
            reasons.append("file pattern")
        folder_matches = pattern_matches_any(normalize_string_list(entry.get("folderPatterns")), folders)
        if folder_matches:
            score += min(folder_matches, 6) * 8
            reasons.append("folder pattern")
        if source_type_matches_profile(entry, source_detection):
            score += 15
            reasons.append("source type")
        if name_patterns and not name_matches and not archive_fingerprint_matches(entry, fingerprint) and not folder_matches:
            continue
        if score <= 0:
            continue
        match_result = "Exact" if score >= 100 else "Partial"
        if best is None or score > best[0]:
            best = (score, match_result, entry, reasons)

    if best is None:
        return known_pack_none_match(db)

    score, match_result, entry, reasons = best
    confidence = "High" if score >= 85 else ("Medium" if score >= 45 else "Low")
    return {
        "matchResult": match_result,
        "matchedPack": first_string(entry, "packDisplayName"),
        "profileId": first_string(entry, "id"),
        "confidence": confidence,
        "status": first_string(entry, "status"),
        "safePackName": first_string(entry, "detectedSafePackName", "safePackName"),
        "sourceFramework": first_string(entry, "sourceFramework"),
        "supportedOutputs": normalize_string_list(entry.get("supportedOutputTypes")),
        "recommendedOutput": first_string(entry, "recommendedOutputType", "recommendedOutput"),
        "recommendedBehaviorTool": first_string(entry, "recommendedBehaviorTool"),
        "knownLimitations": normalize_string_list(entry.get("limitations")),
        "knownWarnings": normalize_string_list(entry.get("knownWarnings")),
        "knownIssues": normalize_string_list(entry.get("knownIssues")),
        "minimumRecommendedConverterVersion": first_string(entry, "minimumConverterVersionRecommended", "minimumConverterVersion"),
        "defaultHumanOnlyOStim": first_bool(entry, "defaultHumanOnlyOStim", "humanOnlyOStimDefault"),
        "creatureOutputRecommended": first_bool(entry, "creatureOutputRecommended"),
        "creatureRuntimeRequired": first_bool(entry, "creatureRuntimeRequired"),
        "creatureNotes": normalize_string_list(entry.get("creatureNotes")),
        "ostimToolsSupported": first_bool(entry, "ostimToolsSupported"),
        "recommendedOStimToolsMode": first_string(entry, "recommendedOStimToolsMode"),
        "ostimToolsNotes": normalize_string_list(entry.get("ostimToolsNotes")),
        "templateRecommended": first_bool(entry, "templateRecommended"),
        "sourceMetadataRecommended": first_bool(entry, "sourceMetadataRecommended"),
        "alignmentRecommended": first_bool(entry, "alignmentRecommended"),
        "preferredSourceParser": first_string(entry, "preferredSourceParser"),
        "fallbackSourceParsers": normalize_string_list(entry.get("fallbackSourceParsers")),
        "sourceBranchPatterns": normalize_string_list(entry.get("sourceBranchPatterns")),
        "ignoredBranchPatterns": normalize_string_list(entry.get("ignoredBranchPatterns")),
        "expectedMixedSourceTypes": normalize_string_list(entry.get("expectedMixedSourceTypes")),
        "expectedDuplicateHkxHighCount": first_bool(entry, "expectedDuplicateHkxHighCount"),
        "recommendedNormalUserWorkflow": first_string(entry, "recommendedNormalUserWorkflow"),
        "recommendedCreatureUserWorkflow": first_string(entry, "recommendedCreatureUserWorkflow"),
        "recommendedPPlusWorkflow": first_string(entry, "recommendedPPlusWorkflow"),
        "recommendedOstimToolsWorkflow": first_string(entry, "recommendedOstimToolsWorkflow"),
        "duplicateHkxPolicy": first_string(entry, "duplicateHkxPolicy"),
        "customFurniturePolicy": first_string(entry, "customFurniturePolicy"),
        "notes": normalize_string_list(entry.get("notes")),
        "matchedBy": reasons,
        "score": score,
        "database": {
            "loaded": bool(db.get("loaded")),
            "version": db.get("version"),
            "files": db.get("files") or [],
            "warningCount": len(db.get("warnings") or []),
            "warnings": db.get("warnings") or [],
        },
    }


def add_compatibility_match_to_source_detection(
    source_detection: Optional[Dict[str, Any]],
    archive: Optional[Path],
    extracted_root: Optional[Path],
) -> Dict[str, Any]:
    augmented = dict(dict_or_empty(source_detection))
    augmented["compatibilityMatch"] = match_compatibility_profile(
        archive,
        extracted_root=extracted_root,
        source_detection=source_detection,
        fingerprint=source_archive_fingerprint(archive),
    )
    return augmented


def compatibility_known_pack_line(match: Any) -> str:
    if not isinstance(match, dict):
        text = str(match or "").strip()
        if text and text.lower() != "none":
            return text
        return "No known compatibility profile matched this archive."
    if not match or match.get("matchResult") == "None":
        return "No known compatibility profile matched this archive."
    pieces = [
        f"Known pack detected: {match.get('matchedPack') or match.get('profileId')}",
    ]
    if match.get("status"):
        pieces.append(f"status {match.get('status')}")
    if match.get("recommendedOutput"):
        pieces.append(f"recommended output {match.get('recommendedOutput')}")
    if match.get("recommendedBehaviorTool"):
        pieces.append(f"behavior tool {match.get('recommendedBehaviorTool')}")
    return ". ".join(pieces) + "."


def issue_summary_text(issue: Any) -> str:
    if isinstance(issue, dict):
        return str(issue.get("detected") or issue.get("message") or issue.get("issue") or "").strip()
    return str(issue or "").strip()


def issue_severity_text(issue: Any, default: str = "medium") -> str:
    if isinstance(issue, dict):
        value = str(issue.get("severity") or default).strip()
        return value or default
    return default


def issue_why_text(issue: Any) -> str:
    if isinstance(issue, dict):
        return str(issue.get("whyItMatters") or issue.get("why") or "").strip()
    return ""


def issue_recommended_action_text(issue: Any) -> str:
    if isinstance(issue, dict):
        return str(issue.get("recommendedUserAction") or issue.get("recommendedAction") or "").strip()
    return ""


def copyable_diagnosis_summary(report: Optional[Dict[str, Any]] = None) -> str:
    report = report if isinstance(report, dict) else {}
    match = report.get("compatibilityMatch") if isinstance(report.get("compatibilityMatch"), dict) else {}
    match_text = str(match.get("matchResult") or "None")
    if match.get("matchedPack"):
        match_text = f"{match_text} - {match.get('matchedPack')}"
    auto_fail = report.get("compatibilityAutoFailCandidate") if isinstance(report.get("compatibilityAutoFailCandidate"), dict) else {}
    auto_fail_entry = auto_fail.get("compatibilityDbEntryTemplate") if isinstance(auto_fail.get("compatibilityDbEntryTemplate"), dict) else {}
    auto_fail_text = (
        f"{auto_fail.get('sourceArchiveHash') or 'hash not recorded'} ({auto_fail_entry.get('id') or 'profile id not recorded'})"
        if auto_fail
        else "none"
    )
    warnings = report.get("warnings") or []
    issues = report.get("knownIssues") or []
    warning_summary = summarize_values(
        [
            *[str(warning) for warning in warnings[:3]],
            *[issue_summary_text(issue) for issue in issues[:3]],
        ],
        limit=6,
    )
    return "\n".join(
        [
            "Diagnosis summary:",
            f"Converter version: {report.get('converterVersion') or CONVERTER_VERSION}",
            f"Source archive: {report.get('sourceArchiveName') or 'not provided'}",
            f"Detected type: {report.get('detectedSourceType') or 'not run yet'}",
            f"Known pack match: {match_text}",
            f"Confidence: {report.get('detectionConfidence') or 'not recorded'}",
            f"Recommended output: {report.get('recommendedOutput') or 'not recorded'}",
            f"Recommended behavior tool: {report.get('recommendedBehaviorTool') or 'not recorded'}",
            f"OStim Tools JSON project: {report.get('ostimToolsProjectStatus') or 'not recorded'}",
            f"Recommended OStim Tools mode: {report.get('recommendedOStimToolsMode') or 'not recorded'}",
            f"Recommended Human-only OStim output: {public_bool(report.get('recommendedHumanOnlyOStimOutput')) if report.get('recommendedHumanOnlyOStimOutput') is not None else 'not recorded'}",
            f"Scenes/animations found: {report.get('sceneOrAnimationRecordsFound') or 'not recorded'}",
            f"HKX files found: {report.get('hkxFilesFound') or 'not recorded'}",
            f"Missing HKX references: {report.get('missingReferencedHkxCount') or 0}",
            f"Creature scenes: {report.get('creatureScenesDetected') if report.get('creatureScenesDetected') is not None else 'not recorded'}",
            f"Furniture scenes: {report.get('furnitureScenesDetected') if report.get('furnitureScenesDetected') is not None else 'not recorded'}",
            f"Compatibility auto-fail candidate: {auto_fail_text}",
            f"Verification prediction: {report.get('verificationPrediction') or report.get('status') or 'not run yet'}",
            f"Warnings: {warning_summary or 'none recorded'}",
            f"Recommended action: {report.get('recommendedActionOneLine') or report.get('recommendedUserAction') or ''}",
            "",
        ]
    )


def nexus_bug_report_text(
    report: Optional[Dict[str, Any]] = None,
    verification_report: Optional[Dict[str, Any]] = None,
    source_name: Optional[str] = None,
    report_attached: bool = False,
) -> str:
    report = report if isinstance(report, dict) else {}
    verification_report = verification_report if isinstance(verification_report, dict) else {}
    match = report.get("compatibilityMatch") if isinstance(report.get("compatibilityMatch"), dict) else {}
    match_text = str(match.get("matchResult") or "None")
    if match.get("matchedPack"):
        match_text = f"{match_text} - {match.get('matchedPack')}"
    auto_fail = report.get("compatibilityAutoFailCandidate") if isinstance(report.get("compatibilityAutoFailCandidate"), dict) else {}
    auto_fail_entry = auto_fail.get("compatibilityDbEntryTemplate") if isinstance(auto_fail.get("compatibilityDbEntryTemplate"), dict) else {}
    auto_fail_text = (
        f"{auto_fail.get('sourceArchiveHash') or 'hash not recorded'} ({auto_fail_entry.get('id') or 'profile id not recorded'})"
        if auto_fail
        else "none"
    )
    fingerprint = report.get("sourceArchiveFingerprint") if isinstance(report.get("sourceArchiveFingerprint"), dict) else {}
    resolved_source_name = (
        source_name
        or report.get("sourceArchiveName")
        or report.get("sourceArchive")
        or fingerprint.get("fileName")
        or "not provided"
    )
    if isinstance(resolved_source_name, str) and any(sep in resolved_source_name for sep in ("\\", "/")):
        resolved_source_name = Path(resolved_source_name).name
    behavior = report.get("behaviorGeneration") if isinstance(report.get("behaviorGeneration"), dict) else {}
    menu_generation = report.get("menuHubCategoryGeneration") if isinstance(report.get("menuHubCategoryGeneration"), dict) else {}
    menu_coverage = (
        f"{menu_generation.get('hubLinkedSceneCount', 0)}/{menu_generation.get('hubLinkableSceneCount', 0)}"
        if menu_generation
        else "not recorded"
    )
    return "\n".join(
        [
            f"Source pack: {resolved_source_name}",
            f"Converter version: {report.get('converterVersion') or CONVERTER_VERSION}",
            f"Output type: {report.get('outputType') or report.get('target') or 'not run yet'}",
            "Behavior tool used: ",
            "Mod manager: ",
            f"Verification result: {verification_report.get('status') or report.get('status') or 'not run yet'}",
            f"Detected source type: {report.get('selectedSourceTypeLabel') or report.get('detectedSourceType') or 'not recorded'}",
            f"Known pack match: {match_text}",
            f"Compatibility auto-fail candidate: {auto_fail_text}",
            f"Scenes written: {report_count(report, 'sceneCount', 'animationCount', 'sceneJsonFileCount', default='not recorded')}",
            f"HKX packaged: {report_count(report, 'hkxCount', default='not recorded')}",
            f"Behavior events generated: {report_count(report, 'registeredAnimationEventCount', 'behaviorEventCount', default='not recorded')}",
            f"Scene events missing behavior registration: {verification_report.get('missingAnimationEventCount') or report_count(report, 'missingAnimationEventCount', 'sceneEventsMissingFromBehaviorCount', default=0)}",
            f"Behavior events missing HKX: {verification_report.get('behaviorEventsPointingToMissingHkxCount') or verification_report.get('fnisMissingHkxFileCount') or 0}",
            f"OStim menu hub generated: {public_bool(bool(report.get('ostimMenuHubSceneCount')) or bool(behavior.get('ostimMenuHubGenerated')))}",
            f"OStim menu graph coverage: {menu_coverage}",
            f"Pandora-compatible behavior patch enabled: {public_bool(report.get('nemesisSafeOutput'))}",
            f"Human-only OStim output: {public_bool(report.get('humanOnlyOStimOutput') if report.get('humanOnlyOStimOutput') is not None else report.get('recommendedHumanOnlyOStimOutput'))}",
            f"Creature scenes skipped by human-only output: {report.get('creatureScenesSkipped', 0)}",
            "What happened in game: ",
            f"Report attached: {'yes' if report_attached else 'no'}",
            "",
        ]
    )


def is_sexlab_scene_builder_repo(path: Path | str) -> bool:
    try:
        repo = Path(path).expanduser()
    except (TypeError, ValueError):
        return False
    return repo.is_dir() and all((repo / marker).is_file() for marker in SLSB_REPO_MARKER_FILES)


def sexlab_scene_builder_repo_candidates(extra_candidates: Sequence[Path | str] = ()) -> List[Path]:
    candidates: List[Path] = []

    def add_candidate(value: Optional[Path | str]) -> None:
        if value is None:
            return
        try:
            candidate = Path(value).expanduser()
        except (TypeError, ValueError):
            return
        if candidate not in candidates:
            candidates.append(candidate)

    for env_var in SLSB_REPO_ENV_VARS:
        add_candidate(os.environ.get(env_var))

    for candidate in extra_candidates:
        add_candidate(candidate)

    roots: List[Path] = []
    for base in (app_base_dir(), Path.cwd()):
        for root in (base, *base.parents):
            if root not in roots:
                roots.append(root)

    for root in roots:
        for dirname in SLSB_REPO_DIR_NAMES:
            add_candidate(root / dirname)
        for sibling_root in (root.parent if root.parent != root else None,):
            if sibling_root is not None:
                for dirname in SLSB_REPO_DIR_NAMES:
                    add_candidate(sibling_root / dirname)

    return candidates


def detect_sexlab_scene_builder_repo(extra_candidates: Sequence[Path | str] = ()) -> Optional[Path]:
    for candidate in sexlab_scene_builder_repo_candidates(extra_candidates):
        if is_sexlab_scene_builder_repo(candidate):
            return candidate.resolve()
    return None


def sexlab_scene_builder_repo_status_text(repo_path: Optional[Path]) -> str:
    if repo_path is not None:
        return "SLSB repo detected: configured"
    return (
        "SLSB repo not detected. SexLab P+ export is disabled. "
        f"Set {SLSB_REPO_ENV_VARS[0]} or place SexLab-Scene-Builder beside this app."
    )


def game_path(path: PurePosixPath | Path | str) -> str:
    return str(path).replace("/", "\\")


def lname(elem: ET.Element) -> str:
    return elem.tag.split("}")[-1].lower()


def local_name(elem: ET.Element) -> str:
    return elem.tag.split("}")[-1]


def attr(elem: ET.Element, name: str, default: Optional[str] = None) -> Optional[str]:
    return elem.attrib.get(name, default)


def parse_float(value: Optional[str], default: float = 0.0) -> float:
    if value is None or value == "":
        return default
    try:
        return float(value)
    except ValueError:
        return default


def parse_int(value: Optional[str], default: int = 0) -> int:
    if value is None or value == "":
        return default
    try:
        return int(float(value))
    except ValueError:
        return default


def parse_bool(value: Optional[str], default: bool = False) -> bool:
    if value is None:
        return default
    return value.strip().lower() in {"1", "true", "yes", "y", "on"}


def split_tags(value: Optional[str]) -> List[str]:
    if not value:
        return []
    return [tag.strip().lower() for tag in re.split(r"[,;|\s]+", value) if tag.strip()]


def first_attr(elem: ET.Element, names: Sequence[str]) -> Optional[str]:
    for name in names:
        if name in elem.attrib:
            return elem.attrib[name]
    wanted = {name.lower() for name in names}
    for key, value in elem.attrib.items():
        if key.lower() in wanted:
            return value
    return None


def sanitize_name(value: str, fallback: str = "scene") -> str:
    cleaned = value.strip()
    cleaned = "".join("_" if ch in INVALID_FILENAME_CHARS or ord(ch) < 32 else ch for ch in cleaned)
    cleaned = re.sub(r"\s+", "_", cleaned)
    cleaned = re.sub(r"_+", "_", cleaned).strip(" ._")
    return cleaned or fallback


def short_stable_hash(value: str, length: int = 8) -> str:
    return hashlib.sha1(value.encode("utf-8", errors="ignore")).hexdigest()[:length]


def sanitize_animation_event(value: str, fallback: str = "Anim", max_length: int = 120) -> str:
    safe = sanitize_name(value, fallback)
    safe = re.sub(r"[^A-Za-z0-9_\-]+", "_", safe)
    safe = re.sub(r"_+", "_", safe).strip("_")
    safe = safe or fallback
    if len(safe) > max_length:
        digest = short_stable_hash(safe)
        safe = f"{safe[: max_length - len(digest) - 1].rstrip('_')}_{digest}"
    return safe


def unique_animation_event_name(base: str, source_key: str, used: Dict[str, str], max_length: int = 120) -> Tuple[str, bool]:
    candidate = sanitize_animation_event(base, "Anim", max_length=max_length)
    key = candidate.lower()
    existing_source = used.get(key)
    if existing_source is None or existing_source == source_key:
        used[key] = source_key
        return candidate, False

    digest = short_stable_hash(source_key or base)
    suffix = f"_{digest}"
    trimmed = candidate[: max_length - len(suffix)].rstrip("_") or "Anim"
    candidate = f"{trimmed}{suffix}"
    key = candidate.lower()
    index = 2
    while key in used and used[key] != source_key:
        numeric_suffix = f"_{digest}_{index}"
        trimmed = sanitize_animation_event(base, "Anim", max_length=max_length)[: max_length - len(numeric_suffix)].rstrip("_") or "Anim"
        candidate = f"{trimmed}{numeric_suffix}"
        key = candidate.lower()
        index += 1
    used[key] = source_key
    return candidate, True


def compact_path_part(part: str) -> str:
    return re.sub(r"[\s_\-]+", "", part).lower()


def scene_dir_index(path: Path) -> Optional[int]:
    for index, part in enumerate(path.parts[:-1]):
        if compact_path_part(part) in SCENE_DIR_MARKERS:
            return index
    return None


def path_prefix(path: Path, end_index: int) -> Path:
    parts = path.parts[: end_index + 1]
    if not parts:
        return path
    result = Path(parts[0])
    for part in parts[1:]:
        result /= part
    return result


def common_path(paths: Sequence[Path]) -> Path:
    return Path(os.path.commonpath([str(path) for path in paths]))


def is_likely_osa_scene_xml(xml_path: Path) -> bool:
    compact_parts = [compact_path_part(part) for part in xml_path.parts[:-1]]
    if any(part in INSTALLER_XML_DIR_MARKERS for part in compact_parts):
        return False
    if scene_dir_index(xml_path) is None:
        return False
    return any(part in OSA_PATH_MARKERS for part in compact_parts)


def is_scene_named_xml(xml_path: Path) -> bool:
    compact_parts = [compact_path_part(part) for part in xml_path.parts[:-1]]
    return scene_dir_index(xml_path) is not None and not any(part in INSTALLER_XML_DIR_MARKERS for part in compact_parts)


def select_scene_xml_files(xml_files: Sequence[Path]) -> List[Path]:
    likely = [xml for xml in xml_files if is_likely_osa_scene_xml(xml)]
    if likely:
        return likely
    scene_named = [xml for xml in xml_files if is_scene_named_xml(xml)]
    return scene_named or list(xml_files)


def scene_collection_root(xml_path: Path) -> Optional[Path]:
    index = scene_dir_index(xml_path)
    if index is None:
        return None
    return path_prefix(xml_path, index)


def safe_pack_folder(pack: str) -> str:
    safe = sanitize_name(pack, "ConvertedPack")
    if safe.lower().startswith("ostim"):
        safe = "Converted_" + safe
    return safe


def safe_behavior_mod_code(pack: str) -> str:
    safe = safe_pack_folder(pack)
    safe = re.sub(r"[^A-Za-z0-9_]+", "_", safe)
    safe = re.sub(r"_+", "_", safe).strip("_")
    return safe[:64] or "ConvertedPack"


def safe_nemesis_patch_code(pack: str) -> str:
    stem = re.sub(r"[^A-Za-z0-9]+", "", pack).lower() or "aac"
    if not stem[0].isalpha():
        stem = "aac" + stem
    digest = hashlib.sha1(pack.encode("utf-8", errors="ignore")).hexdigest()[:6]
    return f"{stem[:18]}{digest}"[:24] or f"aac{digest}"


def safe_nemesis_patch_object_name(pack: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9]+", "", pack) or "AdultAnimationConverter"
    if not cleaned[0].isalpha():
        cleaned = "AAC" + cleaned
    return cleaned[:64]


def xml_text(value: Any) -> str:
    text = str(value)
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


def xml_unescape_text(value: str) -> str:
    return (
        value.replace("&quot;", '"')
        .replace("&gt;", ">")
        .replace("&lt;", "<")
        .replace("&amp;", "&")
    )


def pack_name_from_archive(archive: Path) -> str:
    return safe_pack_folder(archive.stem)


def unique_path(path: Path) -> Path:
    if not path.exists():
        return path
    for index in range(2, 1000):
        candidate = path.with_name(f"{path.stem} ({index}){path.suffix}")
        if not candidate.exists():
            return candidate
    raise RuntimeError(f"Could not find an unused output path near {path}")


def default_zip_path_for_archive(archive: Path) -> Path:
    return unique_path(archive.with_name(f"{archive.stem}_OStimSA.zip"))


def default_sexlab_zip_path_for_archive(archive: Path) -> Path:
    return unique_path(archive.with_name(f"{archive.stem}_SexLab.zip"))


def default_sexlab_plus_zip_path_for_archive(archive: Path) -> Path:
    return unique_path(archive.with_name(f"{archive.stem}_SexLabPPlus.zip"))


def converter_temp_parent(near_path: Optional[Path]) -> Optional[Path]:
    if near_path is None:
        return None
    try:
        near = Path(near_path).expanduser()
        parent = near if near.exists() and near.is_dir() else near.parent
        parent.mkdir(parents=True, exist_ok=True)
        scratch = parent / ".aac_tmp"
        scratch.mkdir(parents=True, exist_ok=True)
        return scratch
    except OSError:
        return None


def make_converter_temp_dir(prefix: str, near_path: Optional[Path] = None) -> Path:
    parent = converter_temp_parent(near_path)
    try:
        temp_dir = Path(tempfile.mkdtemp(prefix=prefix, dir=parent)) if parent else Path(tempfile.mkdtemp(prefix=prefix))
    except OSError:
        temp_dir = Path(tempfile.mkdtemp(prefix=prefix))
    _CONVERTER_TEMP_DIRS.append(temp_dir)
    return temp_dir


def cleanup_converter_temp_dir(temp_dir: Optional[Path]) -> None:
    if temp_dir is None:
        return
    try:
        shutil.rmtree(temp_dir, ignore_errors=True)
    finally:
        try:
            _CONVERTER_TEMP_DIRS.remove(temp_dir)
        except ValueError:
            pass


def unsafe_archive_member_reason(member_name: str) -> Optional[str]:
    normalized = norm_slashes(str(member_name)).strip()
    if not normalized:
        return "empty archive path"
    if "\x00" in normalized:
        return "contains a NUL character"
    if normalized.startswith(("/", "\\")) or normalized.startswith("//"):
        return "absolute paths are not allowed"
    if re.match(r"^[A-Za-z]:", normalized):
        return "drive-qualified paths are not allowed"

    parts = PurePosixPath(normalized).parts
    if any(part in {"", ".", ".."} for part in parts):
        return "relative traversal components are not allowed"
    if parts and re.match(r"^[A-Za-z]:", parts[0]):
        return "drive-qualified paths are not allowed"
    return None


def validate_archive_member_name(member_name: str) -> None:
    reason = unsafe_archive_member_reason(member_name)
    if reason:
        display = str(member_name).replace("\x00", "\\0")
        raise RuntimeError(f"Archive contains unsafe path '{display}': {reason}.")


def ensure_path_inside_directory(path: Path, directory: Path) -> None:
    try:
        path.resolve().relative_to(directory.resolve())
    except ValueError as exc:
        raise RuntimeError(f"Archive extraction tried to write outside the temporary folder: {path}") from exc


def safe_extract_zip(archive: Path, destination: Path) -> None:
    destination.mkdir(parents=True, exist_ok=True)
    with ZipFile(archive, "r") as zf:
        for info in zf.infolist():
            validate_archive_member_name(info.filename)
            mode = (info.external_attr >> 16) & 0o170000
            if mode == stat.S_IFLNK:
                raise RuntimeError(f"Archive contains unsupported symlink entry: {info.filename}")

            rel = PurePosixPath(norm_slashes(info.filename))
            target = destination.joinpath(*rel.parts)
            ensure_path_inside_directory(target, destination)
            if info.is_dir():
                target.mkdir(parents=True, exist_ok=True)
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            with zf.open(info, "r") as source, target.open("wb") as out:
                shutil.copyfileobj(source, out)


def seven_zip_slt_member_paths(listing: str) -> List[str]:
    before_separator: List[str] = []
    after_separator: List[str] = []
    saw_separator = False
    for line in listing.splitlines():
        if line.strip().startswith("----------"):
            saw_separator = True
            continue
        if not line.startswith("Path = "):
            continue
        member = line.split("=", 1)[1].strip()
        if not member:
            continue
        if saw_separator:
            after_separator.append(member)
        else:
            before_separator.append(member)
    if after_separator:
        return after_separator
    return before_separator[1:]


def validate_7z_archive_members(archive: Path, executable: str) -> None:
    try:
        listing = subprocess.check_output(
            [executable, "l", "-slt", str(archive)],
            text=True,
            encoding="utf-8",
            errors="replace",
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Could not list archive before extraction: {exc}") from exc

    archive_resolved = archive.resolve()
    for member in seven_zip_slt_member_paths(listing):
        try:
            if Path(member).expanduser().resolve() == archive_resolved:
                continue
        except OSError:
            pass
        validate_archive_member_name(member)


def validate_extracted_tree(root: Path) -> None:
    root_resolved = root.resolve()
    for path in root.rglob("*"):
        ensure_path_inside_directory(path, root_resolved)
        if path.is_symlink():
            raise RuntimeError(f"Archive extraction created an unsupported symlink: {path}")


def make_scene_id(raw_id: str, pack_prefix: str, used: Dict[str, int]) -> str:
    base = sanitize_name(raw_id, "scene")
    if not base.lower().startswith(pack_prefix.lower() + "_"):
        base = f"{pack_prefix}_{base}"
    base = base[:180]
    count = used.get(base, 0)
    used[base] = count + 1
    return base if count == 0 else f"{base}_{count + 1}"


def scene_ref_base(raw_id: str) -> str:
    if "|" in raw_id:
        head, tail = raw_id.rsplit("|", 1)
        return f"{head}|{tail.split('+', 1)[0]}"
    return raw_id.split("+", 1)[0]


def resolve_legacy_scene_ref(raw_ref: str, current_raw_id: str = "") -> str:
    ref = raw_ref.strip()
    if not ref or not current_raw_id:
        return ref
    if ref.startswith("^"):
        return scene_ref_base(current_raw_id) + ref[1:]
    if ref.startswith("+"):
        return scene_ref_base(current_raw_id) + ref
    return ref


def map_scene_ref(raw_ref: str, id_map: Dict[str, str], fallback_prefix: str, current_raw_id: str = "") -> str:
    resolved = resolve_legacy_scene_ref(raw_ref, current_raw_id)
    if resolved in OSTIM_EXTERNAL_MENU_ORIGINS:
        return resolved
    return id_map.get(resolved) or id_map.get(raw_ref) or f"{fallback_prefix}_{sanitize_name(resolved, 'scene')}"


def assign_scene_ids(scenes: List[Scene], pack: str) -> Dict[str, str]:
    prefix = safe_pack_folder(pack)
    used: Dict[str, int] = {}
    id_map: Dict[str, str] = {}
    for scene in scenes:
        raw = scene.raw_id or scene.scene_id
        scene.scene_id = make_scene_id(raw, prefix, used)
        id_map.setdefault(raw, scene.scene_id)
    for scene in scenes:
        scene.remap_ids(id_map, prefix)
    return id_map


def normalize_ostim_menu_icon(value: Optional[str]) -> str:
    raw = norm_slashes(value or "").strip()
    if not raw:
        return DEFAULT_OSTIM_MENU_ICON
    lowered = raw.lower()
    prefixes = (
        "data/interface/ostim/icons/",
        "interface/ostim/icons/",
    )
    for prefix in prefixes:
        if lowered.startswith(prefix):
            raw = raw[len(prefix):]
            lowered = raw.lower()
            break
    if lowered.endswith(".dds"):
        raw = raw[:-4]
    raw = raw.strip("/\\")
    parts = PurePosixPath(raw).parts
    if not raw or any(part in {"", ".", ".."} for part in parts):
        return DEFAULT_OSTIM_MENU_ICON
    return PurePosixPath(*parts).as_posix()


def is_allowed_external_ostim_menu_origin(origin: Optional[str], no_warnings: bool) -> bool:
    return bool(no_warnings and origin and origin in OSTIM_EXTERNAL_MENU_ORIGINS)


def ostim_menu_signature_for_origin(origin: Optional[str]) -> str:
    if not origin:
        return ""
    for signature, origins in OSTIM_MENU_EXTERNAL_ORIGINS_BY_SIGNATURE.items():
        if origin in origins:
            return signature
    return ""


def actor_menu_sex_token(actor: Actor) -> str:
    intended = (actor.intended_sex or "").strip().lower()
    if intended.startswith("f"):
        return "f"
    if intended.startswith("m"):
        return "m"
    actor_type = (actor.type or "").strip().lower()
    if actor_type.startswith("creaturefemale"):
        return "f"
    if actor_type.startswith("creaturemale"):
        return "m"
    if actor_type.startswith("f"):
        return "f"
    if actor_type.startswith("m"):
        return "m"
    tags = {tag.strip().lower() for tag in actor.tags if tag.strip()}
    if tags & {"female", "woman", "women", "fem", "vagina", "creaturefemale"}:
        return "f"
    if actor.sos_bend or tags & {"male", "man", "men", "masc", "penis", "sos", "creaturemale"}:
        return "m"
    return ""


def ostim_menu_signature_candidates_for_scene(scene: Scene) -> List[str]:
    actor_count = len(scene.actors)
    signatures = OSTIM_MENU_SIGNATURE_ORDER_BY_COUNT.get(actor_count) or []
    if not signatures:
        return []
    tokens = [actor_menu_sex_token(actor) for actor in scene.actors]
    known_males = tokens.count("m")
    known_females = tokens.count("f")
    if known_males + known_females == actor_count:
        signature = "m" * known_males + "f" * known_females
        return [signature] if signature in OSTIM_MENU_EXTERNAL_ORIGINS_BY_SIGNATURE else []
    return [
        signature
        for signature in signatures
        if signature.count("m") >= known_males and signature.count("f") >= known_females
    ]


def scene_actor_signature(scene: Scene) -> str:
    tokens = [actor_menu_sex_token(actor) for actor in scene.actors]
    if not tokens or any(not token for token in tokens):
        return ""
    return "".join(tokens)


def apply_menu_signature_to_actors(actors: Sequence[Actor], signature: str) -> None:
    for actor, token in zip(actors, signature, strict=False):
        if token == "f":
            actor.intended_sex = "female"
            actor.type = "Female"
            actor.sos_bend = 0
            actor.tags = [tag for tag in actor.tags if tag.strip().lower() not in {"male", "man", "men", "masc", "penis", "sos"}]
            if "female" not in actor.tags:
                actor.tags.append("female")
        elif token == "m":
            actor.intended_sex = "male"
            actor.type = "Male"
            if "male" not in actor.tags:
                actor.tags.append("male")


def ostim_menu_idle_origin_for_signature(signature: str) -> Optional[str]:
    origins = OSTIM_MENU_EXTERNAL_ORIGINS_BY_SIGNATURE.get(signature) or []
    return origins[0] if origins else None


def ostim_menu_idle_actors(signature: str) -> List[Actor]:
    actors: List[Actor] = []
    for index, token in enumerate(signature):
        actor = Actor(animation_index=index, tags=["standing"], feet_on_ground=True)
        if token == "m":
            actor.intended_sex = "male"
            actor.sos_bend = 7
        elif token == "f":
            actor.intended_sex = "female"
        actors.append(actor)
    return actors


def canonical_human_actor_order(scene: Scene) -> List[int]:
    if scene_has_creature(scene):
        return list(range(len(scene.actors)))
    signature = scene_actor_signature(scene)
    if not signature or len(signature) > 5:
        return list(range(len(scene.actors)))
    return [index for index, token in enumerate(signature) if token == "m"] + [
        index for index, token in enumerate(signature) if token == "f"
    ]


def remap_action_actor_indexes(action: Action, old_to_new_actor: Dict[int, int]) -> None:
    action.actor = old_to_new_actor.get(action.actor, action.actor)
    if action.target is not None:
        action.target = old_to_new_actor.get(action.target, action.target)
    if action.performer is not None:
        action.performer = old_to_new_actor.get(action.performer, action.performer)


def normalize_human_actor_order_for_ostim(
    scenes: Sequence[Scene],
    hkx_assets: Sequence[HkxAsset],
) -> Tuple[List[HkxAsset], List[str]]:
    event_map: Dict[str, str] = {}
    changed_scene_ids: List[str] = []
    warnings: List[str] = []

    for scene in scenes:
        if not scene.actors:
            continue
        order = canonical_human_actor_order(scene)
        if order == list(range(len(scene.actors))):
            continue

        old_animation_indexes = [
            actor.animation_index if actor.animation_index is not None else index
            for index, actor in enumerate(scene.actors)
        ]
        old_to_new_actor = {old_index: new_index for new_index, old_index in enumerate(order)}
        scene.actors = [scene.actors[old_index] for old_index in order]
        for new_index, actor in enumerate(scene.actors):
            actor.animation_index = new_index
        for action in scene.actions:
            remap_action_actor_indexes(action, old_to_new_actor)

        for speed in scene.speeds:
            for old_actor_index, old_animation_index in enumerate(old_animation_indexes):
                new_actor_index = old_to_new_actor.get(old_actor_index, old_actor_index)
                old_event = f"{speed.animation}_{old_animation_index}"
                new_event = f"{speed.animation}_{new_actor_index}"
                existing = event_map.get(old_event)
                if existing and existing != new_event:
                    warnings.append(
                        f"{scene.raw_id}: could not remap shared HKX event '{old_event}' to '{new_event}' "
                        f"because it was already remapped to '{existing}'."
                    )
                    continue
                event_map[old_event] = new_event
        changed_scene_ids.append(scene.raw_id or scene.scene_id or scene.name)

    if not event_map:
        return list(hkx_assets), warnings

    remapped_assets: List[HkxAsset] = []
    for asset in hkx_assets:
        new_event = event_map.get(asset.event_name)
        if not new_event or new_event == asset.event_name:
            remapped_assets.append(asset)
            continue
        remapped_assets.append(
            HkxAsset(
                source=asset.source,
                data_path=asset.data_path,
                packaged_path=asset.packaged_path.with_name(f"{new_event}.hkx"),
                event_name=new_event,
            )
        )

    if changed_scene_ids:
        warnings.append(
            f"Normalized {len(changed_scene_ids)} human scene actor order(s) to OStim's menu slot order "
            f"(male actors before female actors): {summarize_values(changed_scene_ids)}."
        )
    return remapped_assets, warnings


def is_ostim_menu_hub_scene(scene: Scene) -> bool:
    return OSTIM_MENU_HUB_TAG in scene.tags


def is_ocreatures_menu_hub_scene(scene: Scene) -> bool:
    return OCREATURES_MENU_TAG in scene.tags


def is_ocreatures_menu_root_scene(scene: Scene) -> bool:
    return is_ocreatures_menu_hub_scene(scene) and OCREATURES_MENU_ROOT_TAG in scene.tags


def ostim_menu_source_scene_eligible(scene: Scene) -> bool:
    return (
        is_deployable_scene(scene)
        and not is_ostim_menu_hub_scene(scene)
    )


def scene_menu_description(scene: Scene) -> str:
    description = (scene.name or scene.raw_id or scene.scene_id or "Scene").strip()
    return description[:80] if len(description) > 80 else description


def unique_ostim_menu_node_id(
    pack: str,
    parts: Sequence[str],
    used_ids: set[str],
    collision_rows: Optional[List[Dict[str, str]]] = None,
) -> str:
    safe_pack = safe_pack_folder(pack)
    suffix = "_".join(sanitize_name(part, "Menu") for part in parts if str(part).strip())
    base = sanitize_name(f"{safe_pack}_Menu_{suffix}", "Menu")[:170]
    candidate = base
    index = 2
    while candidate in used_ids:
        suffix = f"_{index}"
        candidate = f"{base[:180 - len(suffix)]}{suffix}"
        index += 1
    if candidate != base and collision_rows is not None:
        collision_rows.append({"base": base, "resolved": candidate})
    used_ids.add(candidate)
    return candidate


def unique_ostim_menu_hub_id(pack: str, signature: str, used_ids: set[str]) -> str:
    return unique_ostim_menu_node_id(pack, [signature.upper()], used_ids)


def add_unique_scene_tags(scene: Scene, tags: Sequence[str]) -> None:
    for tag in tags:
        normalized = tag.strip().lower()
        if normalized and normalized not in scene.tags:
            scene.tags.append(normalized)


def ostim_menu_node_scene(
    pack: str,
    scene_id: str,
    raw_id: str,
    name: str,
    signature: str,
    idle_origin: str,
    extra_tags: Sequence[str],
) -> Scene:
    node = Scene(
        raw_id=raw_id,
        scene_id=scene_id,
        name=name,
        modpack=pack,
        length=2.0,
        speeds=[Speed(animation=idle_origin)],
        default_speed=0,
        no_random_selection=True,
        fade_on_entry=False,
        actors=ostim_menu_idle_actors(signature),
        actions=[],
    )
    node.tags = ["idle", "intro"]
    add_unique_scene_tags(node, (OSTIM_MENU_HUB_TAG, "converted", "menu", *extra_tags))
    return node


def ostim_menu_action_tokens(scene: Scene) -> set[str]:
    values = [scene.name, scene.raw_id, *scene.tags, *(action.type for action in scene.actions)]
    tokens: set[str] = set()
    for value in values:
        for tag in split_tags(str(value or "")):
            compact = compact_path_part(tag)
            if compact:
                tokens.add(compact)
        compact = compact_path_part(str(value or ""))
        if compact:
            tokens.add(compact)
    return tokens


def ostim_menu_primary_category_keys_for_scene(scene: Scene) -> List[str]:
    if scene_has_creature(scene):
        return ["creature"]
    if scene_has_furniture(scene):
        return ["furniture"]

    categories: List[str] = []
    action_types = {normalized_ostim_action_type(action.type) for action in scene.actions if action.type}
    tokens = ostim_menu_action_tokens(scene)

    def add(category: str) -> None:
        if category not in categories:
            categories.append(category)

    if len(scene.actors) >= 3:
        add("group")
    if action_types & {"blowjob", "deepthroat", "cunnilingus", "anilingus", "rimjob"} or tokens & {
        "oral",
        "blowjob",
        "deepthroat",
        "cunnilingus",
        "anilingus",
        "rimjob",
        "lickingvagina",
        "lickingpenis",
    }:
        add("oral")
    if action_types & {"vaginalsex", "vaginalfingering", "vaginalfisting", "vaginaltoying"} or tokens & {
        "vaginal",
        "vaginalsex",
        "missionary",
        "cowgirl",
    }:
        add("vaginal")
    if action_types & {"analsex", "analfingering", "analfisting", "analtoying"} or tokens & {"anal", "analsex"}:
        add("anal")
    if not categories and tokens & {
        "sex",
        "mf",
        "fm",
        "ff",
        "mm",
        "handjob",
        "footjob",
        "boobjob",
        "foreplay",
        "kissing",
        "cuddling",
    }:
        add("sex")
    if not categories:
        add("other")
    return categories


def ostim_menu_category_map_for_group(group: Sequence[Scene]) -> Dict[str, List[Scene]]:
    categories: Dict[str, List[Scene]] = {"all": list(group)}
    for scene in group:
        for category in ostim_menu_primary_category_keys_for_scene(scene):
            categories.setdefault(category, []).append(scene)
    ordered: Dict[str, List[Scene]] = {}
    for category in OSTIM_MENU_CATEGORY_ORDER:
        values = categories.get(category) or []
        if values:
            ordered[category] = sorted(
                {scene.scene_id: scene for scene in values if scene.scene_id}.values(),
                key=lambda scene: (scene.name.lower(), scene.scene_id.lower()),
            )
    return ordered


def ostim_menu_category_label(category: str, count: Optional[int] = None) -> str:
    label = OSTIM_MENU_CATEGORY_LABELS.get(category, category.title())
    return f"{label} ({count})" if count is not None else label


def ostim_menu_category_key(scene: Scene) -> str:
    for tag in scene.tags:
        if tag.startswith(OSTIM_MENU_CATEGORY_TAG_PREFIX):
            return tag.split(":", 1)[1]
    return ""


def ostim_menu_page_key(scene: Scene) -> str:
    for tag in scene.tags:
        if tag.startswith(OSTIM_MENU_PAGE_TAG_PREFIX):
            return tag.split(":", 1)[1]
    return ""


def ocreatures_menu_folder_key(scene: Scene) -> str:
    for tag in scene.tags:
        if tag.startswith(OCREATURES_MENU_FOLDER_TAG_PREFIX):
            return canonical_ocreatures_menu_folder(tag.split(":", 1)[1])
    return ""


def ocreatures_menu_category_key(scene: Scene) -> str:
    for tag in scene.tags:
        if tag.startswith(OCREATURES_MENU_CATEGORY_TAG_PREFIX):
            return tag.split(":", 1)[1]
    return ""


def ocreatures_menu_page_key(scene: Scene) -> str:
    for tag in scene.tags:
        if tag.startswith(OCREATURES_MENU_PAGE_TAG_PREFIX):
            return tag.split(":", 1)[1]
    return ""


def ocreatures_actor_root_label(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return "Unknown"
    label = PurePosixPath(norm_slashes(raw)).name or raw
    safe = sanitize_name(label, "Creature")
    safe = re.sub(r"[^A-Za-z0-9_]+", "_", safe)
    safe = re.sub(r"_+", "_", safe).strip("_")
    if not safe:
        return "Unknown"
    return "".join(part[:1].upper() + part[1:] for part in safe.split("_") if part)


def canonical_ocreatures_menu_folder(value: str) -> str:
    raw = sanitize_name(str(value or "").strip(), "OCrUnknown")
    raw = re.sub(r"[^A-Za-z0-9_]+", "_", raw)
    raw = re.sub(r"_+", "_", raw).strip("_") or "OCrUnknown"
    if raw.lower().startswith("ocr") and len(raw) > 3:
        suffix = raw[3:]
    else:
        suffix = raw
    return "OCr" + (suffix[:1].upper() + suffix[1:] if suffix else "Unknown")


def ocreatures_menu_folder_for_actor_root(actor_root: str) -> str:
    return canonical_ocreatures_menu_folder(f"OCr{ocreatures_actor_root_label(actor_root)}")


def ocreatures_scene_actor_roots(scene: Scene) -> List[str]:
    roots = {
        expected_actor_root_for_scene_actor(actor)
        for actor in scene.actors
        if actor_is_creature(actor)
    }
    roots = {root for root in roots if root and root.lower() != "character"}
    if roots:
        return sorted(roots, key=str.lower)
    fallback_roots = []
    for actor in scene.actors:
        if not actor_is_creature(actor):
            continue
        for value in [actor.creature_race, actor.type, *actor.tags]:
            text = str(value or "").strip()
            if text.startswith("creature:"):
                text = text.split(":", 1)[1]
            root = actor_root_from_creature_hint(text)
            if root and root.lower() != "character":
                fallback_roots.append(root)
    return sorted(set(fallback_roots), key=str.lower)


def ocreatures_primary_actor_root(scene: Scene) -> str:
    roots = ocreatures_scene_actor_roots(scene)
    return roots[0] if roots else "unknown"


def ocreatures_primary_menu_folder_for_scene(scene: Scene) -> str:
    return ocreatures_menu_folder_for_actor_root(ocreatures_primary_actor_root(scene))


def ocreatures_menu_template_source(scenes: Sequence[Scene]) -> Scene:
    return max(
        scenes,
        key=lambda scene: (
            len(scene.actors),
            len(scene.speeds),
            scene_actor_signature(scene),
            scene.name.lower(),
            scene.scene_id.lower(),
        ),
    )


def ocreatures_menu_idle_actors(source: Scene) -> List[Actor]:
    actors = copy.deepcopy(source.actors)
    if actors:
        return actors
    return [
        Actor(animation_index=0, intended_sex="female", type="Female", tags=["female"]),
        Actor(animation_index=1, intended_sex="male", type="CreatureMale", tags=["creature"]),
    ]


def ocreatures_menu_idle_speed(source: Scene) -> str:
    for speed in source.speeds:
        if speed.animation:
            return speed.animation
    return "OCreaturesMenuIdle"


def ocreatures_menu_node_scene(
    pack: str,
    scene_id: str,
    raw_id: str,
    name: str,
    source: Scene,
    folder: str,
    extra_tags: Sequence[str],
) -> Scene:
    node = Scene(
        raw_id=raw_id,
        scene_id=scene_id,
        name=name,
        modpack=pack,
        length=2.0,
        speeds=[Speed(animation=ocreatures_menu_idle_speed(source))],
        default_speed=0,
        no_random_selection=True,
        fade_on_entry=False,
        actors=ocreatures_menu_idle_actors(source),
        actions=[],
    )
    node.tags = ["idle", "intro", "converted", "menu", "creature"]
    add_unique_scene_tags(
        node,
        (
            OSTIM_MENU_HUB_TAG,
            OCREATURES_MENU_TAG,
            f"{OCREATURES_MENU_FOLDER_TAG_PREFIX}{folder}",
            *extra_tags,
        ),
    )
    return node


def add_ocreatures_menu_hubs(
    scenes: List[Scene],
    pack: str,
    enabled: bool = True,
    icon: Optional[str] = None,
) -> Tuple[List[Scene], List[str]]:
    if not enabled:
        return scenes, []

    creature_scenes = [
        scene
        for scene in scenes
        if is_deployable_scene(scene)
        and scene_has_creature(scene)
        and not is_ostim_menu_hub_scene(scene)
    ]
    if not creature_scenes:
        return scenes, []

    icon_path = normalize_ostim_menu_icon(icon)
    used_ids = {scene.scene_id for scene in scenes if scene.scene_id}
    collision_rows: List[Dict[str, str]] = []
    menu_hubs: List[Scene] = []
    groups: Dict[str, List[Scene]] = {}
    for scene in creature_scenes:
        groups.setdefault(ocreatures_primary_menu_folder_for_scene(scene), []).append(scene)

    for folder in sorted(groups, key=str.lower):
        group = sorted(groups[folder], key=lambda scene: (scene.name.lower(), scene.scene_id.lower()))
        source = ocreatures_menu_template_source(group)
        root_label = folder[3:] if folder.lower().startswith("ocr") else folder
        root = ocreatures_menu_node_scene(
            pack,
            unique_ostim_menu_node_id(pack, [folder, "OCreatures"], used_ids, collision_rows),
            f"{pack}|ocreatures_menu|{folder}",
            f"{pack} - {root_label}",
            source,
            folder,
            (OCREATURES_MENU_ROOT_TAG, f"creatureroot:{ocreatures_primary_actor_root(source)}"),
        )
        category_map: Dict[str, List[Scene]] = {"all": list(group)}
        for scene in group:
            for category in ostim_menu_primary_category_keys_for_scene(scene):
                category_map.setdefault(category, []).append(scene)
        ordered_categories = [
            category
            for category in OSTIM_MENU_CATEGORY_ORDER
            if category in category_map and category_map[category]
        ]
        if "creature" not in ordered_categories:
            ordered_categories.append("creature")
            category_map["creature"] = list(group)

        for category_index, category in enumerate(ordered_categories):
            destinations = sorted(
                {scene.scene_id: scene for scene in category_map.get(category, []) if scene.scene_id}.values(),
                key=lambda scene: (scene.name.lower(), scene.scene_id.lower()),
            )
            if not destinations:
                continue
            category_source = ocreatures_menu_template_source(destinations)
            category_label = ostim_menu_category_label(category, len(destinations))
            category_node = ocreatures_menu_node_scene(
                pack,
                unique_ostim_menu_node_id(pack, [folder, category], used_ids, collision_rows),
                f"{pack}|ocreatures_menu|{folder}|{category}",
                category_label,
                category_source,
                folder,
                (f"{OCREATURES_MENU_CATEGORY_TAG_PREFIX}{category}", f"creatureroot:{ocreatures_primary_actor_root(source)}"),
            )
            category_node.navigations.append(
                Navigation(
                    destination=root.scene_id,
                    priority=OCREATURES_MENU_ENTRY_PRIORITY + 5,
                    description=OSTIM_MENU_RETURN_DESCRIPTION,
                    icon="OStim/symbols/return",
                )
            )
            root.navigations.append(
                Navigation(
                    destination=category_node.scene_id,
                    priority=OCREATURES_MENU_ENTRY_PRIORITY + 10 + category_index,
                    description=category_label,
                    icon=icon_path,
                )
            )

            if len(destinations) <= OSTIM_MENU_PAGE_SIZE:
                for destination in destinations:
                    category_node.navigations.append(
                        Navigation(
                            destination=destination.scene_id,
                            priority=OCREATURES_MENU_ENTRY_PRIORITY + 20,
                            description=scene_menu_description(destination),
                            icon=icon_path,
                        )
                    )
                menu_hubs.append(category_node)
                continue

            page_nodes: List[Scene] = []
            for page_index in range(0, len(destinations), OSTIM_MENU_PAGE_SIZE):
                page_number = len(page_nodes) + 1
                page_destinations = destinations[page_index : page_index + OSTIM_MENU_PAGE_SIZE]
                first_number = page_index + 1
                last_number = page_index + len(page_destinations)
                page_label = f"{OSTIM_MENU_CATEGORY_LABELS.get(category, category.title())} {first_number}-{last_number}"
                page_node = ocreatures_menu_node_scene(
                    pack,
                    unique_ostim_menu_node_id(pack, [folder, category, f"Page_{page_number}"], used_ids, collision_rows),
                    f"{pack}|ocreatures_menu|{folder}|{category}|page_{page_number}",
                    page_label,
                    ocreatures_menu_template_source(page_destinations),
                    folder,
                    (
                        f"{OCREATURES_MENU_CATEGORY_TAG_PREFIX}{category}",
                        f"{OCREATURES_MENU_PAGE_TAG_PREFIX}{category}",
                        f"creatureroot:{ocreatures_primary_actor_root(source)}",
                    ),
                )
                page_node.navigations.append(
                    Navigation(
                        destination=category_node.scene_id,
                        priority=OCREATURES_MENU_ENTRY_PRIORITY + 5,
                        description=OSTIM_MENU_RETURN_DESCRIPTION,
                        icon="OStim/symbols/return",
                    )
                )
                for destination in page_destinations:
                    page_node.navigations.append(
                        Navigation(
                            destination=destination.scene_id,
                            priority=OCREATURES_MENU_ENTRY_PRIORITY + 20,
                            description=scene_menu_description(destination),
                            icon=icon_path,
                        )
                    )
                page_nodes.append(page_node)

            for page_index, page_node in enumerate(page_nodes):
                category_node.navigations.append(
                    Navigation(
                        destination=page_node.scene_id,
                        priority=OCREATURES_MENU_ENTRY_PRIORITY + 20 + page_index,
                        description=page_node.name,
                        icon=icon_path,
                    )
                )
                if len(page_nodes) > 1:
                    previous_node = page_nodes[page_index - 1]
                    next_node = page_nodes[(page_index + 1) % len(page_nodes)]
                    if len(page_nodes) > 2:
                        page_node.navigations.append(
                            Navigation(
                                destination=previous_node.scene_id,
                                priority=OCREATURES_MENU_ENTRY_PRIORITY + 30,
                                description=OSTIM_MENU_PREVIOUS_DESCRIPTION,
                                icon=icon_path,
                            )
                        )
                    page_node.navigations.append(
                        Navigation(
                            destination=next_node.scene_id,
                            priority=OCREATURES_MENU_ENTRY_PRIORITY + 31,
                            description=OSTIM_MENU_NEXT_DESCRIPTION,
                            icon=icon_path,
                        )
                    )
            menu_hubs.append(category_node)
            menu_hubs.extend(page_nodes)
        menu_hubs.append(root)

    scenes.extend(menu_hubs)
    warnings = [OCREATURES_MENU_ADAPTER_NOTE]
    if collision_rows:
        warnings.append(
            f"Resolved {len(collision_rows)} generated OCreatures menu node ID collision(s): "
            f"{summarize_values([row['resolved'] for row in collision_rows])}."
        )
    return scenes, warnings


def add_ostim_menu_hubs(
    scenes: List[Scene],
    pack: str,
    enabled: bool = False,
    icon: Optional[str] = None,
) -> Tuple[List[Scene], List[str]]:
    if not enabled:
        return scenes, []

    icon_path = normalize_ostim_menu_icon(icon)
    groups: Dict[str, List[Scene]] = {}
    omitted: List[Tuple[Scene, str]] = []
    for scene in scenes:
        if not ostim_menu_source_scene_eligible(scene):
            if is_deployable_scene(scene) and not is_ostim_menu_hub_scene(scene):
                omitted.append((scene, "not a hub-linkable OStim scene"))
            continue
        signatures = ostim_menu_signature_candidates_for_scene(scene)
        if not signatures:
            omitted.append((scene, "no compatible OStim main-menu actor signature"))
            continue
        for signature in signatures:
            groups.setdefault(signature, []).append(scene)

    if not groups:
        return scenes, [
            "OStim menu entry was requested, but no deployable scene could be linked to a supported OStim main idle menu actor signature."
        ]

    used_ids = {scene.scene_id for scene in scenes if scene.scene_id}
    menu_hubs: List[Scene] = []
    collision_rows: List[Dict[str, str]] = []
    ordered_signatures = [
        signature
        for count in sorted(OSTIM_MENU_SIGNATURE_ORDER_BY_COUNT)
        for signature in OSTIM_MENU_SIGNATURE_ORDER_BY_COUNT[count]
        if signature in groups
    ]
    for signature in ordered_signatures:
        group = sorted(
            groups[signature],
            key=lambda scene: (
                scene_has_creature(scene),
                scene_has_furniture(scene),
                scene.no_random_selection,
                scene.name.lower(),
                scene.scene_id.lower(),
            ),
        )
        idle_origin = ostim_menu_idle_origin_for_signature(signature)
        if not idle_origin:
            continue
        hub = ostim_menu_node_scene(
            pack,
            unique_ostim_menu_node_id(pack, [signature.upper()], used_ids, collision_rows),
            f"{pack}|ostim_menu|{signature}",
            pack,
            signature,
            idle_origin,
            (OSTIM_MENU_ROOT_TAG, f"signature:{signature}"),
        )
        for origin in OSTIM_MENU_EXTERNAL_ORIGINS_BY_SIGNATURE.get(signature, []):
            hub.navigations.append(
                Navigation(
                    origin=origin,
                    priority=OSTIM_MENU_ENTRY_PRIORITY,
                    description=pack,
                    icon=icon_path,
                    no_warnings=True,
                )
            )
            hub.navigations.append(
                Navigation(
                    destination=origin,
                    priority=-1000,
                    description=OSTIM_MENU_RETURN_DESCRIPTION,
                    icon="OStim/symbols/return",
                    no_warnings=True,
                )
            )
        if len(group) <= OSTIM_MENU_DIRECT_LINK_LIMIT:
            for destination in group:
                hub.navigations.append(
                    Navigation(
                        destination=destination.scene_id,
                        priority=OSTIM_MENU_ENTRY_PRIORITY + 10,
                        description=scene_menu_description(destination),
                        icon=icon_path,
                    )
                )
            menu_hubs.append(hub)
            continue

        category_map = ostim_menu_category_map_for_group(group)
        for category_index, (category, destinations) in enumerate(category_map.items()):
            category_label = ostim_menu_category_label(category, len(destinations))
            category_node = ostim_menu_node_scene(
                pack,
                unique_ostim_menu_node_id(pack, [signature.upper(), category], used_ids, collision_rows),
                f"{pack}|ostim_menu|{signature}|{category}",
                category_label,
                signature,
                idle_origin,
                (f"{OSTIM_MENU_CATEGORY_TAG_PREFIX}{category}", f"signature:{signature}"),
            )
            category_node.navigations.append(
                Navigation(
                    destination=hub.scene_id,
                    priority=OSTIM_MENU_ENTRY_PRIORITY + 5,
                    description=OSTIM_MENU_RETURN_DESCRIPTION,
                    icon="OStim/symbols/return",
                )
            )
            hub.navigations.append(
                Navigation(
                    destination=category_node.scene_id,
                    priority=OSTIM_MENU_ENTRY_PRIORITY + 10 + category_index,
                    description=category_label,
                    icon=icon_path,
                )
            )

            if len(destinations) <= OSTIM_MENU_PAGE_SIZE:
                for destination in destinations:
                    category_node.navigations.append(
                        Navigation(
                            destination=destination.scene_id,
                            priority=OSTIM_MENU_ENTRY_PRIORITY + 20,
                            description=scene_menu_description(destination),
                            icon=icon_path,
                        )
                    )
                menu_hubs.append(category_node)
                continue

            page_nodes: List[Scene] = []
            for page_index in range(0, len(destinations), OSTIM_MENU_PAGE_SIZE):
                page_number = len(page_nodes) + 1
                page_destinations = destinations[page_index : page_index + OSTIM_MENU_PAGE_SIZE]
                first_number = page_index + 1
                last_number = page_index + len(page_destinations)
                page_label = f"{OSTIM_MENU_CATEGORY_LABELS.get(category, category.title())} {first_number}-{last_number}"
                page_node = ostim_menu_node_scene(
                    pack,
                    unique_ostim_menu_node_id(pack, [signature.upper(), category, f"Page_{page_number}"], used_ids, collision_rows),
                    f"{pack}|ostim_menu|{signature}|{category}|page_{page_number}",
                    page_label,
                    signature,
                    idle_origin,
                    (f"{OSTIM_MENU_CATEGORY_TAG_PREFIX}{category}", f"{OSTIM_MENU_PAGE_TAG_PREFIX}{category}", f"signature:{signature}"),
                )
                page_node.navigations.append(
                    Navigation(
                        destination=category_node.scene_id,
                        priority=OSTIM_MENU_ENTRY_PRIORITY + 5,
                        description=OSTIM_MENU_RETURN_DESCRIPTION,
                        icon="OStim/symbols/return",
                    )
                )
                for destination in page_destinations:
                    page_node.navigations.append(
                        Navigation(
                            destination=destination.scene_id,
                            priority=OSTIM_MENU_ENTRY_PRIORITY + 20,
                            description=scene_menu_description(destination),
                            icon=icon_path,
                        )
                    )
                page_nodes.append(page_node)

            for page_index, page_node in enumerate(page_nodes):
                category_node.navigations.append(
                    Navigation(
                        destination=page_node.scene_id,
                        priority=OSTIM_MENU_ENTRY_PRIORITY + 20 + page_index,
                        description=page_node.name,
                        icon=icon_path,
                    )
                )
                if len(page_nodes) > 1:
                    previous_node = page_nodes[page_index - 1]
                    next_node = page_nodes[(page_index + 1) % len(page_nodes)]
                    if len(page_nodes) > 2:
                        page_node.navigations.append(
                            Navigation(
                                destination=previous_node.scene_id,
                                priority=OSTIM_MENU_ENTRY_PRIORITY + 30,
                                description=OSTIM_MENU_PREVIOUS_DESCRIPTION,
                                icon=icon_path,
                            )
                        )
                    page_node.navigations.append(
                        Navigation(
                            destination=next_node.scene_id,
                            priority=OSTIM_MENU_ENTRY_PRIORITY + 31,
                            description=OSTIM_MENU_NEXT_DESCRIPTION,
                            icon=icon_path,
                        )
                    )
            menu_hubs.append(category_node)
            menu_hubs.extend(page_nodes)
        menu_hubs.append(hub)

    scenes.extend(menu_hubs)
    warnings: List[str] = []
    if collision_rows:
        warnings.append(
            f"Resolved {len(collision_rows)} generated OStim menu node ID collision(s): "
            f"{summarize_values([row['resolved'] for row in collision_rows])}."
        )
    if omitted:
        warnings.append(
            f"{len(omitted)} deployable scene(s) were intentionally left out of generated OStim menu hubs: "
            f"{summarize_values([f'{scene.scene_id or scene.raw_id}: {reason}' for scene, reason in omitted])}."
        )
    return scenes, warnings


def generated_ostim_sequence_key(scene: Scene) -> Tuple[str, str, str, str]:
    action_key = "+".join(sorted({action.type for action in scene.actions if action.type})) or "uncategorized"
    furniture_key = canonical_ostim_furniture_type(scene.furniture) or "none"
    creature_key = "human"
    if scene_has_creature(scene):
        races = sorted(
            {
                (actor.creature_race or next((tag[9:] for tag in actor.tags if tag.startswith("creature:")), "")).lower()
                for actor in scene.actors
                if actor_is_creature(actor)
            }
        )
        creature_key = "creature:" + ("+".join(race for race in races if race) or "unknown")
    return scene_actor_signature(scene), action_key, furniture_key, creature_key


def navigation_destination_exists(scene: Scene, destination: Optional[str]) -> bool:
    if not destination:
        return False
    return any(nav.destination == destination for nav in scene.navigations)


def append_navigation_if_missing(scene: Scene, nav: Navigation) -> bool:
    if nav.destination and navigation_destination_exists(scene, nav.destination):
        return False
    if nav.origin and any(existing.origin == nav.origin for existing in scene.navigations):
        return False
    scene.navigations.append(nav)
    return True


def generated_menu_navigation_key(nav: Navigation) -> Optional[str]:
    if not nav.destination:
        return None
    return nav.destination


def dedupe_generated_ostim_menu_navigations(scenes: Sequence[Scene]) -> List[Dict[str, Any]]:
    removed: List[Dict[str, Any]] = []
    for scene in scenes:
        if not is_ostim_menu_hub_scene(scene):
            continue
        kept: List[Navigation] = []
        seen: Dict[str, int] = {}
        for nav in scene.navigations:
            key = generated_menu_navigation_key(nav)
            if key is None:
                kept.append(nav)
                continue
            prior_index = seen.get(key)
            if prior_index is not None:
                removed.append(
                    {
                        "source": scene.scene_id,
                        "destination": nav.destination,
                        "description": nav.description or "",
                        "icon": normalize_ostim_menu_icon(nav.icon),
                        "border": nav.border or "",
                        "keptIndex": prior_index,
                        "removedIndex": len(kept),
                    }
                )
                continue
            seen[key] = len(kept)
            kept.append(nav)
        if len(kept) != len(scene.navigations):
            scene.navigations = kept
    return removed


def generated_ostim_navigation_counts(scenes: Sequence[Scene]) -> Tuple[int, int]:
    menu_hub_ids = {
        scene.scene_id
        for scene in scenes
        if is_ostim_menu_hub_scene(scene) and not is_ocreatures_menu_hub_scene(scene) and scene.scene_id
    }
    scene_ids = {scene.scene_id for scene in scenes if scene.scene_id}
    return_count = 0
    sequence_count = 0
    for scene in scenes:
        if is_ostim_menu_hub_scene(scene):
            continue
        for nav in scene.navigations:
            if nav.destination in menu_hub_ids and nav.description == OSTIM_MENU_RETURN_DESCRIPTION:
                return_count += 1
            elif (
                nav.destination in scene_ids
                and nav.description in {OSTIM_MENU_PREVIOUS_DESCRIPTION, OSTIM_MENU_NEXT_DESCRIPTION}
            ):
                sequence_count += 1
    return return_count, sequence_count


def add_generated_ostim_navigation_links(
    scenes: List[Scene],
    enabled: bool = False,
    icon: Optional[str] = None,
) -> List[str]:
    if not enabled:
        return []

    icon_path = normalize_ostim_menu_icon(icon)
    scene_by_id = {scene.scene_id: scene for scene in scenes if scene.scene_id}
    return_links_added = 0
    sequence_links_added = 0
    linkable_destination_count = 0

    for hub in [scene for scene in scenes if is_ostim_menu_hub_scene(scene) and not is_ocreatures_menu_hub_scene(scene)]:
        destinations: List[Scene] = []
        seen_destinations: set[str] = set()
        for nav in hub.navigations:
            destination_id = nav.destination or ""
            destination = scene_by_id.get(destination_id)
            if not destination or destination_id in seen_destinations:
                continue
            if is_ostim_menu_hub_scene(destination) or not is_deployable_scene(destination):
                continue
            destinations.append(destination)
            seen_destinations.add(destination_id)

        for scene in destinations:
            if scene.destination or scene.origin:
                continue
            linkable_destination_count += 1
            if append_navigation_if_missing(
                scene,
                Navigation(
                    destination=hub.scene_id,
                    priority=OSTIM_MENU_ENTRY_PRIORITY + 20,
                    description=OSTIM_MENU_RETURN_DESCRIPTION,
                    icon=icon_path,
                ),
            ):
                return_links_added += 1

        grouped: Dict[Tuple[str, str, str, str], List[Scene]] = {}
        for scene in destinations:
            if scene.destination or scene.origin:
                continue
            grouped.setdefault(generated_ostim_sequence_key(scene), []).append(scene)

        for group in grouped.values():
            if len(group) < 3:
                continue
            group_links_added = 0
            for index, scene in enumerate(group):
                previous_scene = group[index - 1]
                next_scene = group[(index + 1) % len(group)]
                if previous_scene.scene_id != scene.scene_id and append_navigation_if_missing(
                    scene,
                    Navigation(
                        destination=previous_scene.scene_id,
                        priority=OSTIM_MENU_ENTRY_PRIORITY + 30,
                        description=OSTIM_MENU_PREVIOUS_DESCRIPTION,
                        icon=icon_path,
                    ),
                ):
                    group_links_added += 1
                if next_scene.scene_id != scene.scene_id and append_navigation_if_missing(
                    scene,
                    Navigation(
                        destination=next_scene.scene_id,
                        priority=OSTIM_MENU_ENTRY_PRIORITY + 31,
                        description=OSTIM_MENU_NEXT_DESCRIPTION,
                        icon=icon_path,
                    ),
                ):
                    group_links_added += 1
            sequence_links_added += group_links_added

    warnings: List[str] = []
    if linkable_destination_count and not return_links_added:
        warnings.append(
            "OStim menu entry was created, but generated return navigation could not be attached to the linked scenes."
        )
    return warnings


def infer_legacy_class(xml_path: Path, raw_id: str = "") -> str:
    parts = list(xml_path.parts)
    index = scene_dir_index(xml_path)
    if index is not None:
        scene_parts = parts[index + 1 : -1]
        for part in reversed(scene_parts):
            key = compact_path_part(part)
            if key in LEGACY_ACTION_CLASS_CODES:
                return key
        if index + 3 < len(parts):
            return parts[index + 3]
        if index + 2 < len(parts):
            return parts[index + 2]
    if raw_id:
        for token in reversed(re.split(r"[|/\\_.!+\-\s]+", raw_id)):
            key = compact_path_part(token)
            if key in LEGACY_ACTION_CLASS_CODES:
                return key
    return xml_path.parent.name


def infer_legacy_class_from_raw_id(raw_id: str) -> str:
    for token in reversed(re.split(r"[|/\\_.!+\-\s]+", raw_id)):
        key = compact_path_part(token)
        if key in LEGACY_ACTION_CLASS_CODES:
            return key
    return ""


def infer_legacy_mod(xml_path: Path) -> str:
    parts = list(xml_path.parts)
    index = scene_dir_index(xml_path)
    if index is not None and index + 1 < len(parts):
        return parts[index + 1]
    return xml_path.parents[2].name if len(xml_path.parents) >= 3 else xml_path.parent.name


def add_action(scene: Scene, action_type: str, actor: int, target: Optional[int] = None, performer: Optional[int] = None) -> None:
    action = Action(
        type=action_type.lower(),
        actor=actor,
        target=actor if target is None else target,
        performer=actor if performer is None else performer,
    )
    scene.actions.append(action)
    scene.ensure_actor_count(action.max_actor_index() + 1)


def normalized_ostim_action_type(action_type: str) -> str:
    key = action_type.strip().lower()
    return ACTION_TYPE_ALIASES.get(key, key)


SFX_FALLBACK_DROPDOWN_OPTIONS: Tuple[Tuple[str, str], ...] = (
    ("Converter moan (recommended)", DEFAULT_SFX_FALLBACK_ACTION_TYPE),
    ("No fallback", "none"),
    ("Kissing", "kissing"),
    ("Hugging", "hugging"),
    ("Cuddling", "cuddling"),
    ("Handjob", "handjob"),
    ("Blowjob", "blowjob"),
    ("Footjob", "footjob"),
    ("Cunnilingus", "cunnilingus"),
    ("Vaginal sex", "vaginalsex"),
    ("Anal sex", "analsex"),
    ("Generic default", "default"),
)
SFX_FALLBACK_DROPDOWN_LABELS: Tuple[str, ...] = tuple(label for label, _value in SFX_FALLBACK_DROPDOWN_OPTIONS)
SFX_FALLBACK_VALUE_BY_LABEL: Dict[str, str] = dict(SFX_FALLBACK_DROPDOWN_OPTIONS)
SFX_FALLBACK_VALUE_BY_NORMALIZED_LABEL: Dict[str, str] = {
    label.lower(): value for label, value in SFX_FALLBACK_DROPDOWN_OPTIONS
}


def sfx_fallback_action_from_dropdown(selection: Optional[str]) -> str:
    value = (selection or "").strip()
    return SFX_FALLBACK_VALUE_BY_LABEL.get(value) or SFX_FALLBACK_VALUE_BY_NORMALIZED_LABEL.get(value.lower()) or value


def sfx_fallback_dropdown_label_for_action(action_type: Optional[str]) -> str:
    normalized = "none" if action_type in DISABLED_SFX_FALLBACK_VALUES else normalize_sfx_fallback_action_type(action_type)
    for label, value in SFX_FALLBACK_DROPDOWN_OPTIONS:
        value_normalized = "none" if value in DISABLED_SFX_FALLBACK_VALUES else normalize_sfx_fallback_action_type(value)
        if value_normalized == normalized:
            return label
    return action_type or SFX_FALLBACK_DROPDOWN_LABELS[0]


def normalize_sfx_fallback_action_type(action_type: Optional[str]) -> str:
    raw = DEFAULT_SFX_FALLBACK_ACTION_TYPE if action_type is None else action_type.strip().lower()
    if raw in DISABLED_SFX_FALLBACK_VALUES:
        return ""
    normalized = normalized_ostim_action_type(raw)
    if not ACTION_TYPE_SAFE_RE.fullmatch(normalized):
        raise ValueError(
            "SFX fallback action must contain only letters, numbers, or underscores. "
            "Use a built-in OStim action such as kissing, a custom name such as ostimconvertermoan, or none."
        )
    return normalized


def needs_generated_sfx_action_file(action_type: Optional[str]) -> bool:
    normalized = normalize_sfx_fallback_action_type(action_type)
    return bool(normalized and normalized not in OSTIM_BUILTIN_ACTION_TYPES)


def infer_legacy_actions(scene: Scene, class_name: str) -> None:
    class_key = compact_path_part(class_name)
    if class_key == "sx":
        add_action(scene, "vaginalsex", 0, 1)
    elif class_key == "an":
        add_action(scene, "analsex", 0, 1)
    elif class_key in {"bj", "hhbj", "pj", "hhpj"}:
        add_action(scene, "blowjob", 1, 0)
    elif class_key == "vj":
        add_action(scene, "cunnilingus", 0, 1)
    elif class_key in {"hj", "aphj"}:
        add_action(scene, "handjob", 1, 0)
    elif class_key == "cr":
        add_action(scene, "rubbingclitoris", 0, 1)
    elif class_key in {"pf1", "pf2"}:
        add_action(scene, "vaginalfingering", 0, 1)
    elif class_key == "boj":
        add_action(scene, "boobjob", 1, 0)
        add_action(scene, "footjob", 1, 0)
    elif class_key == "bof":
        add_action(scene, "suckingnipple", 0, 1)
    elif class_key == "po":
        add_action(scene, CUSTOM_SFX_ACTION_TYPE, 0, 0)
    elif class_key == "dhj":
        add_action(scene, "handjob", 1, 0)
        add_action(scene, "handjob", 1, 2)
    elif class_key == "vbj":
        add_action(scene, "blowjob", 1, 0)
        add_action(scene, "cunnilingus", 0, 1)
    elif class_key == "vhj":
        add_action(scene, "handjob", 1, 0)
        add_action(scene, "cunnilingus", 0, 1)


def parse_legacy_scene(scene_el: ET.Element, xml_path: Path) -> Optional[Scene]:
    raw_id = first_attr(scene_el, SCENE_ID_ATTRS) or xml_path.stem
    scene = Scene(raw_id=raw_id, name=raw_id, modpack=infer_legacy_mod(xml_path))

    actor_count = parse_int(first_attr(scene_el, ACTOR_COUNT_ATTRS), 1)
    scene.ensure_actor_count(max(1, actor_count))
    scene.actors[0].scale = 1.03

    info_el = scene_el.find("info")
    if info_el is not None and first_attr(info_el, SCENE_NAME_ATTRS):
        scene.name = first_attr(info_el, SCENE_NAME_ATTRS) or scene.name

    is_old_format = True
    anim_el = scene_el.find("anim")
    if anim_el is not None:
        transition_type = (first_attr(anim_el, ("t", "type", "transition")) or "").strip().lower()
        if transition_type in {"t", "transition", "true", "1", "yes"}:
            scene.destination = first_attr(anim_el, DESTINATION_ATTRS) or ""
            if scene.destination:
                scene.tags.append("transition")
        length_value = first_attr(anim_el, LENGTH_ATTRS)
        if length_value is not None:
            scene.length = parse_float(length_value, DEFAULT_LENGTH)

    if scene.destination is None:
        speed_el = scene_el.find("speed")
        if speed_el is not None:
            for sp_el in speed_el.findall("sp"):
                if attr(sp_el, "mtx") == "^idle":
                    scene.default_speed = max(0, len(scene.speeds))
                sp_anim_el = sp_el.find("anim")
                if sp_anim_el is None:
                    continue
                anim_id = animation_event_from_value(first_attr(sp_anim_el, ANIMATION_ID_ATTRS))
                if not anim_id:
                    continue
                playback = first_attr(sp_anim_el, ("playbackSpeed", "playback_speed"))
                display = first_attr(sp_el, ("qnt", "displaySpeed", "display_speed"))
                scene.speeds.append(
                    Speed(
                        animation=anim_id,
                        playback_speed=parse_float(playback) if playback is not None else None,
                        display_speed=parse_float(display) if display is not None else None,
                    )
                )

    nav_el = scene_el.find("nav")
    if nav_el is not None:
        for option in nav_el.findall("./tab/page/option"):
            go = attr(option, "go")
            if go:
                scene.navigations.append(Navigation(destination=go))

    if not scene.speeds:
        anim_children = list(scene_el.findall("anim"))
        for index, child in enumerate(anim_children):
            if index == 0 and len(anim_children) > 1:
                continue
            anim_id = animation_event_from_value(first_attr(child, ANIMATION_ID_ATTRS))
            if not anim_id:
                path_value = first_attr(child, ANIMATION_FILE_ATTRS)
                anim_id = event_from_hkx_path(path_value) if path_value else None
            if anim_id:
                scene.speeds.append(Speed(animation=anim_id))

    if not scene.speeds:
        for role in scene_el.findall("./animation/animrole"):
            anim = role.find("./animplan/anim")
            anim_id = animation_event_from_value(first_attr(anim, ANIMATION_ID_ATTRS)) if anim is not None else None
            if anim_id:
                scene.speeds.append(Speed(animation=anim_id))

    metadata_el = scene_el.find("metadata")
    if metadata_el is not None:
        for tag in split_tags(attr(metadata_el, "tags")):
            if tag != "intro" and tag not in scene.tags:
                scene.tags.append(tag)
        if attr(metadata_el, "noRandomSelection") is not None:
            scene.no_random_selection = parse_bool(attr(metadata_el, "noRandomSelection"))
        if attr(metadata_el, "furniture"):
            scene.furniture = attr(metadata_el, "furniture") or "none"
        is_old_format = False

    actors_el = scene_el.find("actors")
    if actors_el is not None:
        for actor_el in actors_el.findall("actor"):
            pos_attr = first_attr(actor_el, ACTOR_INDEX_ATTRS)
            if pos_attr is None:
                continue
            position = parse_int(pos_attr, -1)
            if position < 0:
                continue
            scene.ensure_actor_count(position + 1)
            actor = scene.actors[position]

            sos_bend = first_attr(actor_el, ("sosBend", "penisAngle"))
            if sos_bend is not None:
                actor.sos_bend = parse_int(sos_bend)
            scale = first_attr(actor_el, ("scale",))
            if scale is not None:
                actor.scale = parse_float(scale, actor.scale)
            scale_height = first_attr(actor_el, ("scaleHeight", "scale_height"))
            if scale_height is not None:
                actor.scale_height = parse_float(scale_height, actor.scale_height)
            expression_action = first_attr(actor_el, ("expressionAction", "expression_action"))
            if expression_action is not None:
                actor.expression_action = parse_int(expression_action)
            look_up = first_attr(actor_el, ("lookUp", "look_up"))
            look_down = first_attr(actor_el, ("lookDown", "look_down"))
            if look_up is not None:
                actor.look_up = parse_int(look_up)
            elif look_down is not None:
                actor.look_up = -parse_int(look_down)
            look_left = first_attr(actor_el, ("lookLeft", "look_left"))
            look_right = first_attr(actor_el, ("lookRight", "look_right"))
            if look_left is not None:
                actor.look_left = parse_int(look_left)
            elif look_right is not None:
                actor.look_left = -parse_int(look_right)

            for tag in split_tags(attr(actor_el, "tags")):
                if tag not in actor.tags:
                    actor.tags.append(tag)
            if "openmouth" in actor.tags:
                actor.expression_override = "openmouth"
            elif "licking" in actor.tags:
                actor.expression_override = "tongue"
            if "nostrip" in actor.tags:
                actor.no_strip = True
            if attr(actor_el, "feetOnGround") is not None:
                actor.feet_on_ground = parse_bool(attr(actor_el, "feetOnGround"))
            elif actor.tags:
                actor.feet_on_ground = any(tag in {"standing", "squatting"} for tag in actor.tags)

            for transition in actor_el.findall("autotransition"):
                transition_type = first_attr(transition, ("type", "event"))
                destination = first_attr(transition, DESTINATION_ATTRS)
                if transition_type and destination:
                    actor.auto_transitions[transition_type.lower()] = destination
        is_old_format = False

    actions_el = scene_el.find("actions")
    if actions_el is not None:
        for action_el in actions_el.findall("action"):
            action_type = first_attr(action_el, ("type", "name"))
            actor = first_attr(action_el, ("actor", "actorIndex", "position"))
            if not action_type or actor is None:
                continue
            target = first_attr(action_el, ("target", "targetActor"))
            performer = first_attr(action_el, ("performer", "performerActor"))
            add_action(
                scene,
                action_type.lower(),
                parse_int(actor),
                parse_int(target) if target is not None else None,
                parse_int(performer) if performer is not None else None,
            )
        is_old_format = False

    if is_old_format:
        infer_legacy_actions(scene, infer_legacy_class(xml_path, scene.raw_id))

    scene.finalize_actor_count()
    if not scene.speeds and not scene.destination:
        return None
    return scene


def strip_actor_suffix(event_name: str) -> Tuple[str, Optional[int]]:
    match = re.match(r"^(.*)_([0-9]+)$", event_name)
    if not match:
        return event_name, None
    return match.group(1), int(match.group(2))


def event_from_hkx_path(path_value: str) -> str:
    stem = PurePosixPath(norm_slashes(path_value)).stem
    base, _ = strip_actor_suffix(stem)
    return base


def animation_event_from_value(value: Optional[str]) -> str:
    if not value:
        return ""
    cleaned = value.strip().strip('"').strip("'")
    if not cleaned:
        return ""
    normalized = norm_slashes(cleaned)
    if "/" in normalized or normalized.lower().endswith(".hkx"):
        return event_from_hkx_path(normalized)
    return cleaned


def sexlab_stage_event_aliases(event_name: str) -> List[str]:
    aliases: List[str] = []

    def add(value: str) -> None:
        if value and value not in aliases:
            aliases.append(value)

    add(event_name)
    match = re.match(r"^(?P<prefix>.+)_(?P<first>[AS])(?P<first_num>\d+)_(?P<second>[AS])(?P<second_num>\d+)$", event_name, re.IGNORECASE)
    if not match or match.group("first").lower() == match.group("second").lower():
        return aliases

    first_label = match.group("first").upper()
    first_num = match.group("first_num")
    second_num = match.group("second_num")
    actor_num = first_num if first_label == "A" else second_num
    stage_num = second_num if first_label == "A" else first_num
    numeric_pairs = [(actor_num, stage_num)]
    try:
        normalized_pair = (str(int(actor_num)), str(int(stage_num)))
        if normalized_pair not in numeric_pairs:
            numeric_pairs.append(normalized_pair)
    except ValueError:
        pass

    prefixes = [match.group("prefix")]
    if "_" in prefixes[0]:
        # SLSB packs can keep the author/pack token in SLAL JSON stage ids while
        # storing HKX files without it, e.g. Anubs_A_bedsleep_A1_S1 -> A_bedsleep_A1_S1.hkx.
        prefixes.append(prefixes[0].split("_", 1)[1])
    for prefix in prefixes:
        for actor, stage in numeric_pairs:
            add(f"{prefix}_A{actor}_S{stage}")
            add(f"{prefix}_S{stage}_A{actor}")
    return aliases


def parse_generic_xml(root: ET.Element, xml_path: Path) -> List[Scene]:
    scene_tags = {"scene", "scenedata", "osexscene", "osex", "osex+", "opensex", "sexscene"}
    stage_tags = {"stage", "pose", "position", "step"}
    anim_tags = {"animation", "anim", "clip", "hkx"}

    scene_elements = [el for el in root.iter() if lname(el) in scene_tags]
    if not scene_elements and lname(root) not in scene_tags:
        scene_elements = [root]

    scenes: List[Scene] = []
    for scene_el in scene_elements:
        if local_name(scene_el) == "scene":
            parsed = parse_legacy_scene(scene_el, xml_path)
            if parsed:
                scenes.append(parsed)
                continue

        raw_scene_id = first_attr(scene_el, SCENE_ID_ATTRS) or xml_path.stem
        stage_elements = [el for el in scene_el.iter() if lname(el) in stage_tags]
        if not stage_elements:
            stage_elements = [scene_el]

        previous_raw_id: Optional[str] = None
        for index, stage_el in enumerate(stage_elements):
            raw_stage_id = first_attr(stage_el, ("id", "stage_id")) or (raw_scene_id if len(stage_elements) == 1 else f"{raw_scene_id}_{index + 1}")
            scene = Scene(
                raw_id=raw_stage_id,
                name=first_attr(stage_el, SCENE_NAME_ATTRS) or first_attr(scene_el, SCENE_NAME_ATTRS) or raw_stage_id,
                length=parse_float(first_attr(stage_el, LENGTH_ATTRS), DEFAULT_LENGTH),
            )
            max_actor = parse_int(first_attr(scene_el, ACTOR_COUNT_ATTRS), 0) - 1
            seen_speeds: set[str] = set()
            for anim_el in stage_el.iter():
                if lname(anim_el) not in anim_tags:
                    continue
                path_value = first_attr(anim_el, ANIMATION_FILE_ATTRS)
                anim_id = animation_event_from_value(first_attr(anim_el, ANIMATION_ID_ATTRS))
                event = anim_id or (event_from_hkx_path(path_value) if path_value else "")
                actor_index = parse_int(first_attr(anim_el, ACTOR_INDEX_ATTRS), 0)
                max_actor = max(max_actor, actor_index)
                if not event or event in seen_speeds:
                    continue
                seen_speeds.add(event)
                scene.speeds.append(Speed(animation=event))
                actor = Actor(animation_index=actor_index)
                actor.offset = Offset(
                    parse_float(first_attr(anim_el, ("x", "pos_x"))),
                    parse_float(first_attr(anim_el, ("y", "pos_y"))),
                    parse_float(first_attr(anim_el, ("z", "pos_z"))),
                    parse_float(first_attr(anim_el, ("r", "rot", "rz", "rot_z"))),
                )
                scene.ensure_actor_count(actor_index + 1)
                if not actor.offset.is_default():
                    scene.actors[actor_index].offset = actor.offset
            if scene.speeds:
                scene.ensure_actor_count(max(1, max_actor + 1))
                if previous_raw_id:
                    scene.navigations.append(Navigation(origin=previous_raw_id))
                previous_raw_id = scene.raw_id
                scenes.append(scene)

    return scenes


XML_ATTR_RE = re.compile(r"\s+([A-Za-z_:][\w:.-]*)\s*=\s*(?:\"[^\"]*\"|'[^']*')")
XML_TAG_RE = re.compile(r"<[^!?/][^>]*>")


def remove_duplicate_xml_attributes(text: str) -> Tuple[str, List[str]]:
    warnings: List[str] = []

    def repair_tag(match: re.Match[str]) -> str:
        tag = match.group(0)
        seen: set[str] = set()
        duplicate_spans: List[Tuple[int, int, str]] = []
        for attr_match in XML_ATTR_RE.finditer(tag):
            attr_name = attr_match.group(1)
            if attr_name in seen:
                duplicate_spans.append((attr_match.start(), attr_match.end(), attr_name))
            else:
                seen.add(attr_name)
        if not duplicate_spans:
            return tag

        line = text.count("\n", 0, match.start()) + 1
        duplicate_names = sorted({name for _start, _end, name in duplicate_spans})
        warnings.append(
            f"line {line}: removed duplicate XML attribute(s) {summarize_values(duplicate_names)} from legacy OSex XML tag."
        )

        repaired_parts: List[str] = []
        cursor = 0
        for start, end, _name in duplicate_spans:
            repaired_parts.append(tag[cursor:start])
            cursor = end
        repaired_parts.append(tag[cursor:])
        return "".join(repaired_parts)

    repaired = XML_TAG_RE.sub(repair_tag, text)
    return repaired, warnings


def parse_osex_xml_with_warnings(xml_path: Path) -> Tuple[List[Scene], List[str]]:
    warnings: List[str] = []
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as original_exc:
        text = xml_path.read_text(encoding="utf-8-sig", errors="replace")
        repaired_text, repair_warnings = remove_duplicate_xml_attributes(text)
        if repaired_text == text:
            raise
        try:
            root = ET.fromstring(repaired_text)
        except ET.ParseError as repaired_exc:
            raise original_exc from repaired_exc
        warnings.extend(
            f"{xml_path}: recovered malformed legacy XML after {warning}" for warning in repair_warnings
        )

    if local_name(root) == "scene":
        parsed = parse_legacy_scene(root, xml_path)
        if parsed:
            return [parsed], warnings
    return parse_generic_xml(root, xml_path), warnings


def parse_osex_xml(xml_path: Path) -> List[Scene]:
    scenes, _warnings = parse_osex_xml_with_warnings(xml_path)
    return scenes


def compact_json_key(key: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", key.lower())


