def write_converter_pack_metadata(
    data_root: Path,
    report: Dict[str, Any],
    scenes: Sequence[Scene],
    assets: Sequence[HkxAsset],
    pack: str,
    source_archive: Optional[Path] = None,
    mod_author: Optional[str] = None,
    sfx_fallback_action: Optional[str] = None,
    action_content_paths: Optional[Sequence[str]] = None,
    furniture_type_content_paths: Optional[Sequence[str]] = None,
) -> Path:
    metadata = build_pack_metadata(
        report,
        scenes,
        assets,
        pack,
        source_archive=source_archive,
        mod_author=mod_author,
        sfx_fallback_action=sfx_fallback_action,
        action_content_paths=action_content_paths,
        furniture_type_content_paths=furniture_type_content_paths,
    )
    metadata_path = data_root / Path(*converter_metadata_rel_path(pack).parts)
    metadata_path.parent.mkdir(parents=True, exist_ok=True)
    metadata_path.write_text(json.dumps(metadata, indent=2, ensure_ascii=False), encoding="utf-8")
    return metadata_path


def write_pandora_mod_info(data_root: Path, pack: str, mod_author: Optional[str] = None) -> Path:
    mod_code = safe_behavior_mod_code(pack)
    info_path = data_root / Path(*(PANDORA_MOD_REL / mod_code / "info.xml").parts)
    info_path.parent.mkdir(parents=True, exist_ok=True)

    root = ET.Element("mod", {"code": mod_code})
    ET.SubElement(root, "name").text = metadata_line_value(pack)
    ET.SubElement(root, "author").text = normalized_mod_author(mod_author)
    ET.SubElement(root, "site").text = "Converted OSex/OStim package"
    xml = ET.tostring(root, encoding="unicode", short_empty_elements=False)
    info_path.write_text(xml + "\n", encoding="utf-8")
    return info_path


def write_nemesis_mod_info(data_root: Path, pack: str, mod_author: Optional[str] = None) -> Path:
    mod_code = safe_behavior_mod_code(pack)
    info_path = data_root / Path(*(NEMESIS_MOD_REL / mod_code / "info.ini").parts)
    info_path.parent.mkdir(parents=True, exist_ok=True)
    lines = [
        f"name={metadata_line_value(pack)}",
        f"author={normalized_mod_author(mod_author)}",
        "site=Converted animation package",
        "auto=null",
        "hidden=false",
    ]
    info_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return info_path


def write_pandora_animset_files(root: Path, grouped: Dict[str, List[str]]) -> List[Path]:
    created: List[Path] = []
    for project, rels in sorted(grouped.items()):
        unique_rels = sorted(set(rels))
        created.append(write_lines(root / f"{project}.txt", unique_rels))
        created.append(write_lines(root / project / "H2HDual.txt", unique_rels))
    return created


def write_pandora_animdata_files(root: Path, grouped: Dict[str, List[str]]) -> List[Path]:
    created: List[Path] = []
    for project, events in sorted(grouped.items()):
        unique_events = sorted(set(events))
        created.append(write_lines(root / f"{project}.txt", unique_events))
    return created


def count_text_files(root: Path) -> int:
    if not root.exists():
        return 0
    return sum(1 for path in root.rglob("*.txt") if path.is_file())


def legacy_pandora_project_aliases(pack: str, grouped: Dict[str, List[str]]) -> Dict[str, List[str]]:
    mod_code = safe_behavior_mod_code(pack)
    aliases: Dict[str, List[str]] = {}
    for project, values in grouped.items():
        safe_project = sanitize_name(project, "DefaultMale")
        alias = sanitize_name(f"{mod_code}_{safe_project}", "ConvertedPack_DefaultMale")
        alias = re.sub(r"[^A-Za-z0-9_]+", "_", alias)
        alias = re.sub(r"_+", "_", alias).strip("_")[:96] or "ConvertedPack_DefaultMale"
        aliases.setdefault(alias, []).extend(values)
    return aliases


def generate_pandora_files(
    data_root: Path,
    pack: str,
    assets: Sequence[HkxAsset],
    scenes: Optional[Sequence[Scene]] = None,
    mod_author: Optional[str] = None,
) -> List[Path]:
    created: List[Path] = []
    grouped_paths: Dict[str, List[str]] = {}
    grouped_events: Dict[str, List[str]] = {}
    for event_name, asset in behavior_event_entries(assets, scenes):
        for project in infer_projects_from_path(asset.packaged_path):
            grouped_paths.setdefault(project, []).append(game_path(asset.packaged_path))
            grouped_events.setdefault(project, []).append(event_name)

    mod_code = safe_behavior_mod_code(pack)
    named_mod_root = data_root / Path(*(PANDORA_MOD_REL / mod_code).parts)
    created.append(write_pandora_mod_info(data_root, pack, mod_author=mod_author))
    created.extend(write_pandora_animdata_files(named_mod_root / Path(*PANDORA_MOD_ANIMDATA_REL.parts), grouped_events))
    created.extend(write_pandora_animset_files(named_mod_root / Path(*PANDORA_MOD_ANIMSET_REL.parts), grouped_paths))
    return created


def behavior_event_entries(assets: Sequence[HkxAsset], scenes: Optional[Sequence[Scene]] = None) -> List[Tuple[str, HkxAsset]]:
    entries: List[Tuple[str, HkxAsset]] = []
    seen_keys: set[Tuple[str, str]] = set()
    assets_by_event: Dict[str, List[HkxAsset]] = {}

    for asset in sorted(assets, key=lambda item: (hkx_asset_actor_root(item), item.event_name.lower(), item.packaged_path.as_posix().lower())):
        assets_by_event.setdefault(asset.event_name, []).append(asset)
        key = (hkx_asset_actor_root(asset), asset.event_name)
        if key not in seen_keys:
            seen_keys.add(key)
            entries.append((asset.event_name, asset))

    if scenes:
        for scene in scenes:
            if len(scene_animation_indexes(scene)) != 1:
                continue
            for event in expected_animation_events(scene):
                base, actor_index = strip_actor_suffix(event)
                if actor_index == 0 and base in assets_by_event:
                    for asset in assets_by_event[base]:
                        key = (hkx_asset_actor_root(asset), event)
                        if key in seen_keys:
                            continue
                        seen_keys.add(key)
                        entries.append((event, asset))

    return entries


def behavior_event_names(assets: Sequence[HkxAsset], scenes: Optional[Sequence[Scene]] = None) -> set[str]:
    return {event for event, _asset in behavior_event_entries(assets, scenes)}


def hkx_asset_actor_root(asset: HkxAsset) -> str:
    return (hkx_actor_root(asset.packaged_path) or "character").lower()


def behavior_event_actor_root_keys(assets: Sequence[HkxAsset], scenes: Optional[Sequence[Scene]] = None) -> set[Tuple[str, str]]:
    return {(hkx_asset_actor_root(asset), event) for event, asset in behavior_event_entries(assets, scenes)}


def character_hkx_assets(assets: Sequence[HkxAsset]) -> List[HkxAsset]:
    return [asset for asset in assets if hkx_asset_actor_root(asset) == "character"]


def creature_hkx_assets(assets: Sequence[HkxAsset]) -> List[HkxAsset]:
    return [asset for asset in assets if hkx_asset_actor_root(asset) != "character"]


def scene_playback_speed_by_actor_event(scenes: Optional[Sequence[Scene]]) -> Dict[str, float]:
    speeds: Dict[str, float] = {}
    for scene in scenes or []:
        animation_indexes = scene_animation_indexes(scene)
        for speed in scene.speeds:
            if not speed.animation:
                continue
            playback = float(speed.playback_speed) if speed.playback_speed is not None else 1.0
            for actor_index in animation_indexes:
                speeds.setdefault(f"{speed.animation}_{actor_index}", playback)
    return speeds


def att_playback_speed_text(value: float) -> str:
    if not math.isfinite(value) or value <= 0:
        value = 1.0
    return f"{value:.6g}"


def ostimsa_selected_behavior_mode(
    *,
    has_character_att: bool,
    has_character_fnis: bool,
    has_creature_fnis: bool,
    has_nemesis_patch: bool,
    has_pandora_registration: bool,
) -> str:
    if has_pandora_registration and (has_character_att or has_character_fnis or has_creature_fnis or has_nemesis_patch):
        return OSTIMSA_BEHAVIOR_MODE_MIXED_INVALID
    if has_character_att and has_character_fnis:
        return OSTIMSA_BEHAVIOR_MODE_MIXED_INVALID
    if has_character_att and has_nemesis_patch:
        return OSTIMSA_BEHAVIOR_MODE_NEMESIS_SAFE_WITH_CREATURE if has_creature_fnis else OSTIMSA_BEHAVIOR_MODE_NEMESIS_SAFE
    if has_creature_fnis and not has_character_att and not has_character_fnis:
        return OSTIMSA_BEHAVIOR_MODE_CREATURE_FNIS
    if has_pandora_registration:
        return OSTIMSA_BEHAVIOR_MODE_PANDORA_NATIVE
    if has_character_fnis:
        return OSTIMSA_BEHAVIOR_MODE_FNIS_STYLE
    return OSTIMSA_BEHAVIOR_MODE_UNSUPPORTED


def animation_mod_dir_from_packaged_path(path: PurePosixPath, pack: str) -> PurePosixPath:
    anim_root = actor_animation_root_from_packaged_path(path) or ANIMATION_ROOT_REL
    safe_pack = safe_pack_folder(pack)
    try:
        tail = path.relative_to(anim_root)
    except ValueError:
        return anim_root / safe_pack
    if len(tail.parts) >= 2:
        return anim_root / tail.parts[0]
    return anim_root / safe_pack


def behavior_graph_stem_parts(stem: str, actor_root: str) -> Tuple[str, str]:
    if stem.lower().startswith("fnis_"):
        stem = stem[5:]
    if stem.lower().endswith("_behavior"):
        stem = stem[:-9]
    root_leaf = PurePosixPath(actor_root).name
    if actor_root.lower() != "character" and "_" in stem:
        folder, token = stem.rsplit("_", 1)
        if token:
            return folder, token
    return stem, root_leaf


def default_fnis_list_name_for_anim_dir(anim_dir_rel: PurePosixPath) -> str:
    actor_root = hkx_actor_root(anim_dir_rel) or "character"
    folder = anim_dir_rel.name
    if actor_root.lower() == "character":
        return f"FNIS_{folder}_List.txt"
    return f"FNIS_{folder}_{PurePosixPath(actor_root).name}_List.txt"


def behavior_graph_list_name_map(behavior_graphs: Sequence[BehaviorGraphAsset]) -> Dict[Tuple[str, str], List[str]]:
    mapped: Dict[Tuple[str, str], List[str]] = {}
    for graph in behavior_graphs:
        actor_root = hkx_actor_root(graph.packaged_path) or "character"
        folder, token = behavior_graph_stem_parts(graph.packaged_path.stem, actor_root)
        if not folder:
            continue
        if actor_root.lower() == "character":
            list_name = f"FNIS_{folder}_List.txt"
        else:
            list_name = f"FNIS_{folder}_{token}_List.txt"
        key = (actor_root.lower(), folder.lower())
        names = mapped.setdefault(key, [])
        if list_name not in names:
            names.append(list_name)
    return mapped


def animation_list_names_for_dir(
    anim_dir_rel: PurePosixPath,
    graph_list_names: Dict[Tuple[str, str], List[str]],
) -> List[str]:
    actor_root = hkx_actor_root(anim_dir_rel) or "character"
    key = (actor_root.lower(), anim_dir_rel.name.lower())
    names = graph_list_names.get(key)
    if names:
        return names
    return [default_fnis_list_name_for_anim_dir(anim_dir_rel)]


def generate_animation_list(
    data_root: Path,
    pack: str,
    assets: Sequence[HkxAsset],
    scenes: Optional[Sequence[Scene]] = None,
    behavior_graphs: Optional[Sequence[BehaviorGraphAsset]] = None,
) -> List[Path]:
    if not assets:
        return []
    grouped: Dict[PurePosixPath, List[str]] = {}
    seen_by_dir: Dict[PurePosixPath, set[str]] = {}
    graph_list_names = behavior_graph_list_name_map(behavior_graphs or [])
    for event_name, asset in behavior_event_entries(assets, scenes):
        anim_dir_rel = animation_mod_dir_from_packaged_path(asset.packaged_path, pack)
        try:
            rel_to_anim_dir = asset.packaged_path.relative_to(anim_dir_rel)
        except ValueError:
            rel_to_anim_dir = PurePosixPath(asset.packaged_path.name)
        line = f"b -Tn {event_name} {game_path(rel_to_anim_dir)}"
        for list_name in animation_list_names_for_dir(anim_dir_rel, graph_list_names):
            list_rel = anim_dir_rel / list_name
            seen = seen_by_dir.setdefault(list_rel, set())
            if line not in seen:
                seen.add(line)
                grouped.setdefault(list_rel, []).append(line)
    return [
        write_lines(data_root / Path(*list_rel.parts), lines)
        for list_rel, lines in sorted(grouped.items(), key=lambda item: item[0].as_posix().lower())
    ]


def att_resource_text(name: str) -> str:
    path = resource_path(ATT_RESOURCES_REL / name)
    if not path.is_file():
        raise FileNotFoundError(f"Missing Animlist Transition Tool resource template: {path}")
    return path.read_text(encoding="utf-8")


def format_att_resource(name: str, *values: Any) -> str:
    return att_resource_text(name).format(*values)


def att_object_tag(prefix: str, object_id: int) -> str:
    return f"#{prefix}${object_id}"


def att_hkcstring(value: str) -> str:
    return f"\t\t\t\t<hkcstring>{xml_text(value)}</hkcstring>"


def att_event_flags(count: int) -> str:
    block = (
        "\t\t\t\t<hkobject>\n"
        "\t\t\t\t\t<hkparam name=\"flags\">0</hkparam>\n"
        "\t\t\t\t</hkobject>\n"
    )
    return block * count


def deterministic_att_root_state_id(pack: str, prefix: str) -> int:
    seed = hashlib.sha1(f"{pack}|{prefix}|att-root".encode("utf-8", errors="ignore")).hexdigest()
    return 1_000_000 + (int(seed[:8], 16) % 8_000_000)


def att_animation_name_for_asset(asset: HkxAsset, pack: str) -> str:
    anim_dir_rel = animation_mod_dir_from_packaged_path(asset.packaged_path, pack)
    try:
        rel_to_anim_dir = asset.packaged_path.relative_to(anim_dir_rel)
    except ValueError:
        rel_to_anim_dir = PurePosixPath(asset.packaged_path.name)
    return game_path(PurePosixPath("Animations") / anim_dir_rel.name / rel_to_anim_dir)


def collect_att_patch_animations(
    pack: str,
    assets: Sequence[HkxAsset],
    scenes: Optional[Sequence[Scene]] = None,
) -> List[AttPatchAnimation]:
    animations: Dict[str, AttPatchAnimation] = {}
    for event_name, asset in behavior_event_entries(assets, scenes):
        actor_root = (hkx_actor_root(asset.packaged_path) or "character").lower()
        if actor_root != "character" or not is_actor_animation_path(asset.packaged_path):
            continue
        animations.setdefault(
            event_name,
            AttPatchAnimation(
                event_name=event_name,
                animation_name=att_animation_name_for_asset(asset, pack),
                packaged_path=asset.packaged_path,
            ),
        )
    return [animations[key] for key in sorted(animations, key=str.lower)]


def generate_att_animation_lists(
    data_root: Path,
    pack: str,
    animations: Sequence[AttPatchAnimation],
    *,
    list_code: Optional[str] = None,
    playback_var: Optional[str] = None,
    playback_speed_by_event: Optional[Dict[str, float]] = None,
) -> List[Path]:
    grouped: Dict[PurePosixPath, List[str]] = {}
    seen_by_dir: Dict[PurePosixPath, set[str]] = {}
    list_name = f"ATT_{sanitize_name(list_code or safe_behavior_mod_code(pack), 'ConvertedPack')}_animlist.txt"
    speed_by_event = playback_speed_by_event or {}
    for animation in animations:
        anim_dir_rel = animation_mod_dir_from_packaged_path(animation.packaged_path, pack)
        try:
            rel_to_anim_dir = animation.packaged_path.relative_to(anim_dir_rel)
        except ValueError:
            rel_to_anim_dir = PurePosixPath(animation.packaged_path.name)
        speed_suffix = ""
        if playback_var:
            speed_suffix = f" {playback_var}: {att_playback_speed_text(speed_by_event.get(animation.event_name, 1.0))}"
        line = f"b -Tn {animation.event_name} {game_path(rel_to_anim_dir)}{speed_suffix}"
        seen = seen_by_dir.setdefault(anim_dir_rel, set())
        if line in seen:
            continue
        seen.add(line)
        grouped.setdefault(anim_dir_rel, []).append(line)
    return [
        write_lines(data_root / Path(*(anim_dir_rel / list_name).parts), lines)
        for anim_dir_rel, lines in sorted(grouped.items(), key=lambda item: item[0].as_posix().lower())
    ]


def write_generated_att_nemesis_patch(
    data_root: Path,
    pack: str,
    assets: Sequence[HkxAsset],
    scenes: Optional[Sequence[Scene]] = None,
    mod_author: Optional[str] = None,
) -> Tuple[List[Path], List[Path]]:
    animations = collect_att_patch_animations(pack, assets, scenes)
    if not animations:
        return [], []

    prefix = safe_nemesis_patch_code(pack)
    mod_name = safe_nemesis_patch_object_name(pack)
    mod_root = data_root / Path(*(NEMESIS_MOD_REL / prefix).parts)
    master_root = mod_root / "0_master"
    default_male_root = mod_root / "defaultmale"
    default_female_root = mod_root / "defaultfemale"
    for directory in (master_root, default_male_root, default_female_root):
        directory.mkdir(parents=True, exist_ok=True)

    created_patch_files: List[Path] = []

    def write_patch(rel: PurePosixPath, text: str) -> Path:
        path = data_root / Path(*rel.parts)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text.rstrip() + "\n", encoding="utf-8")
        created_patch_files.append(path)
        return path

    def master_file(name: str, text: str) -> Path:
        return write_patch(NEMESIS_MOD_REL / prefix / "0_master" / name, text)

    playback_var = f"{prefix.upper()}_AnimationSpeed"
    crop_start_var = f"{prefix.upper()}_CropAnimStart"
    crop_end_var = f"{prefix.upper()}_CropAnimEnd"
    start_time_var = f"{prefix.upper()}_AnimStartTime"

    root_state_tag = att_object_tag(prefix, 0)
    state_machine_tag = att_object_tag(prefix, 1)
    default_modifier_tag = att_object_tag(prefix, 2)
    default_expression_tag = att_object_tag(prefix, 3)

    master_file(f"#{prefix}$3.txt", format_att_resource("hkbExpressionDataArray.txt", default_expression_tag, playback_var))
    master_file(
        f"#{prefix}$2.txt",
        format_att_resource(
            "hkbEvaluateExpressionModifier.txt",
            default_modifier_tag,
            f"{mod_name}_DefaultModifier",
            default_expression_tag,
        ),
    )

    states: List[str] = []
    event_names = [att_hkcstring(ATT_EXIT_EVENT)]
    variable_names = [
        att_hkcstring(playback_var),
        att_hkcstring(crop_start_var),
        att_hkcstring(crop_end_var),
        att_hkcstring(start_time_var),
    ]
    animation_names: List[str] = []
    root_transition_infos: List[str] = []

    object_id = 4
    for clip_index, animation in enumerate(animations):
        state_tag = att_object_tag(prefix, object_id)
        modifier_root_tag = att_object_tag(prefix, object_id + 1)
        clip_tag = att_object_tag(prefix, object_id + 2)
        binding_tag = att_object_tag(prefix, object_id + 3)
        modifier_tag = att_object_tag(prefix, object_id + 4)
        modifier_binding_tag = att_object_tag(prefix, object_id + 5)

        master_file(
            f"#{prefix}${object_id}.txt",
            format_att_resource(
                "hkbStateMachineStateInfo.txt",
                state_tag,
                "null",
                "null",
                "null",
                "null",
                modifier_root_tag,
                f"{mod_name}_Anim{clip_index}",
                clip_index,
            ),
        )
        master_file(
            f"#{prefix}${object_id + 1}.txt",
            format_att_resource(
                "hkbModifierGenerator.txt",
                modifier_root_tag,
                f"{mod_name}_Modifier{object_id + 4}",
                modifier_tag,
                clip_tag,
            ),
        )
        master_file(
            f"#{prefix}${object_id + 2}.txt",
            format_att_resource(
                "hkbClipGenerator.txt",
                clip_tag,
                binding_tag,
                f"{mod_name}_AnimClip{clip_index}",
                xml_text(animation.animation_name),
                "null",
                animation.play_mode,
                0,
            ),
        )
        master_file(f"#{prefix}${object_id + 3}.txt", format_att_resource("hkbVariableBindingSet.txt", binding_tag))
        master_file(
            f"#{prefix}${object_id + 4}.txt",
            format_att_resource(
                "BSIsActiveModifier.txt",
                modifier_tag,
                modifier_binding_tag,
                f"{mod_name}_BSIsActiveModifier{object_id + 4}",
            ),
        )
        master_file(
            f"#{prefix}${object_id + 5}.txt",
            format_att_resource("hkbActiveVariableBindingSet.txt", modifier_binding_tag),
        )

        states.append(state_tag)
        event_names.append(att_hkcstring(animation.event_name))
        animation_names.append(att_hkcstring(animation.animation_name))
        object_id += 6

    root_transition_array_tag = att_object_tag(prefix, object_id)
    exit_transition_array_tag = att_object_tag(prefix, object_id + 1)
    object_id += 2

    exit_transition_effect_tag = att_object_tag(prefix, object_id)
    master_file(
        f"#{prefix}${object_id}.txt",
        format_att_resource("hkbBlendingTransitionEffect.txt", exit_transition_effect_tag, "null", "ExitTransition", "0.200000"),
    )
    exit_transition_info = format_att_resource(
        "hkTransitionInfo.txt",
        exit_transition_effect_tag,
        ATT_EXIT_EVENT,
        14,
        0,
        "FLAG_IS_LOCAL_WILDCARD|FLAG_DISABLE_CONDITION",
    )
    master_file(
        f"#{prefix}${object_id - 1}.txt",
        format_att_resource("hkbTransitionInfoArray.txt", exit_transition_array_tag, 1, exit_transition_info),
    )
    object_id += 1

    for clip_index, animation in enumerate(animations):
        transition_effect_tag = att_object_tag(prefix, object_id)
        master_file(
            f"#{prefix}${object_id}.txt",
            format_att_resource(
                "hkbBlendingTransitionEffect.txt",
                transition_effect_tag,
                "null",
                f"{xml_text(animation.event_name)}Transition",
                "0.600000",
            ),
        )
        root_transition_infos.append(
            format_att_resource(
                "hkTransitionInfo.txt",
                transition_effect_tag,
                animation.event_name,
                clip_index,
                0,
                ATT_TRANSITION_FLAGS,
            )
        )
        object_id += 1

    master_file(
        f"#{prefix}${4 + (len(animations) * 6)}.txt",
        format_att_resource(
            "hkbTransitionInfoArray.txt",
            root_transition_array_tag,
            len(root_transition_infos),
            "\n".join(root_transition_infos),
        ),
    )
    master_file(
        "#0340.txt",
        format_att_resource("#0340.txt", prefix, root_state_tag),
    )
    master_file(
        "#2517.txt",
        format_att_resource("#2517.txt", default_modifier_tag),
    )
    master_file(
        "#0106.txt",
        format_att_resource("#0106.txt", prefix, "\n".join(event_names), prefix, "\n".join(variable_names)),
    )
    master_file("#0107.txt", format_att_resource("#0107.txt", prefix))
    master_file(
        "#0108.txt",
        format_att_resource("#0108.txt", prefix, prefix, att_event_flags(len(event_names))),
    )

    anim_names_text = "\n".join(animation_names)
    animation_name_count = ATT_BASE_ANIMATION_NAME_COUNT + len(animation_names)
    write_patch(
        NEMESIS_MOD_REL / prefix / "defaultmale" / "#0029.txt",
        format_att_resource("m#0029.txt", animation_name_count, prefix, anim_names_text),
    )
    write_patch(
        NEMESIS_MOD_REL / prefix / "defaultfemale" / "#0029.txt",
        format_att_resource("f#0029.txt", animation_name_count, prefix, anim_names_text),
    )
    master_file(
        f"#{prefix}$0.txt",
        format_att_resource(
            "hkbStateMachineStateInfo.txt",
            root_state_tag,
            "null",
            "null",
            "null",
            exit_transition_array_tag,
            state_machine_tag,
            f"{mod_name}_State",
            deterministic_att_root_state_id(pack, prefix),
        ),
    )
    master_file(
        f"#{prefix}$1.txt",
        format_att_resource(
            "hkbStateMachine.txt",
            state_machine_tag,
            f"{mod_name}_Root",
            len(states),
            "\t\t\t\t" + " ".join(states),
            root_transition_array_tag,
        ),
    )
    write_patch(
        NEMESIS_MOD_REL / prefix / "info.ini",
        "\n".join(
            [
                f"name={metadata_line_value(pack)}",
                f"author={normalized_mod_author(mod_author)}",
                "site=https://github.com/VersuchDrei/AnimlistTransitionTool",
                "auto=null",
                "hidden=true",
            ]
        ),
    )
    playback_speed_by_event = scene_playback_speed_by_actor_event(scenes)
    att_list_paths = generate_att_animation_lists(
        data_root,
        pack,
        animations,
        list_code=prefix,
        playback_var=playback_var,
        playback_speed_by_event=playback_speed_by_event,
    )
    return created_patch_files, att_list_paths


def copied_files_include_real_nemesis_patch(data_root: Path, files: Sequence[Path]) -> bool:
    for path in files:
        try:
            rel = PurePosixPath(*path.relative_to(data_root).parts)
        except ValueError:
            continue
        nemesis_mod = path_under_mod_root(rel, NEMESIS_MOD_REL)
        if nemesis_mod and is_nemesis_behavior_patch_payload(nemesis_mod[1]):
            return True
    return False


def engine_mod_asset_has_real_nemesis_patch(asset: EngineModAsset) -> bool:
    if not path_startswith(asset.packaged_root, NEMESIS_MOD_REL):
        return False
    if not asset.source_root.exists():
        return False
    for source in asset.source_root.rglob("*"):
        if not source.is_file():
            continue
        rel = PurePosixPath(*source.relative_to(asset.source_root).parts)
        if is_nemesis_behavior_patch_payload(rel):
            return True
    return False


def filter_ostimsa_source_engine_mods(engine_mods: Sequence[EngineModAsset]) -> List[EngineModAsset]:
    return [asset for asset in engine_mods if engine_mod_asset_has_real_nemesis_patch(asset)]


def first_nemesis_mod_code_from_files(data_root: Path, files: Sequence[Path]) -> Optional[str]:
    for path in sorted(files, key=lambda item: str(item).lower()):
        try:
            rel = PurePosixPath(*path.relative_to(data_root).parts)
        except ValueError:
            continue
        nemesis_mod = path_under_mod_root(rel, NEMESIS_MOD_REL)
        if nemesis_mod and is_nemesis_behavior_patch_payload(nemesis_mod[1]):
            return nemesis_mod[0]
    return None


def source_nemesis_playback_variable(data_root: Path, files: Sequence[Path]) -> Optional[str]:
    for path in sorted(files, key=lambda item: str(item).lower()):
        if path.name.lower() != "#0106.txt" or not path.exists():
            continue
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        match = re.search(r"<hkcstring>\s*([^<]*_AnimationSpeed)\s*</hkcstring>", text, flags=re.IGNORECASE)
        if match:
            return xml_unescape_text(match.group(1)).strip()
    code = first_nemesis_mod_code_from_files(data_root, files)
    return f"{code.upper()}_AnimationSpeed" if code else None


def copy_hkx_assets(data_root: Path, assets: Sequence[HkxAsset]) -> List[Path]:
    copied: List[Path] = []
    used: Dict[PurePosixPath, int] = {}
    for asset in assets:
        target_rel = asset.packaged_path
        count = used.get(target_rel, 0)
        used[target_rel] = count + 1
        if count:
            stem = target_rel.stem
            suffix = target_rel.suffix
            target_rel = target_rel.with_name(f"{stem}_{count + 1}{suffix}")
        target = data_root / Path(*target_rel.parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(asset.source, target)
        copied.append(target)
    return copied


def copy_behavior_graph_assets(data_root: Path, behavior_graphs: Sequence[BehaviorGraphAsset]) -> List[Path]:
    copied: List[Path] = []
    used: set[str] = set()
    for graph in behavior_graphs:
        target_rel = graph.packaged_path
        key = target_rel.as_posix().lower()
        if key in used:
            continue
        used.add(key)
        target = data_root / Path(*target_rel.parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(graph.source, target)
        copied.append(target)
    return copied


def copy_engine_mod_assets(data_root: Path, engine_mods: Sequence[EngineModAsset]) -> List[Path]:
    copied: List[Path] = []
    seen_files: set[str] = set()
    for asset in engine_mods:
        if not asset.source_root.exists():
            continue
        target_root = data_root / Path(*asset.packaged_root.parts)
        target_root.mkdir(parents=True, exist_ok=True)
        for source in sorted(asset.source_root.rglob("*")):
            if not source.is_file():
                continue
            rel = source.relative_to(asset.source_root)
            target = target_root / rel
            key = str(target).lower()
            if key in seen_files:
                continue
            seen_files.add(key)
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, target)
            copied.append(target)
    return copied


def copy_ostim_action_files(data_root: Path, action_files: Sequence[Path]) -> List[Path]:
    copied: List[Path] = []
    used_names: set[str] = set()
    for source in action_files:
        if not source.exists():
            continue
        name = sanitize_name(source.stem, "action") + source.suffix.lower()
        if name.lower() in used_names:
            continue
        used_names.add(name.lower())
        target = data_root / Path(*(ACTIONS_REL / name).parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        try:
            loaded = load_json_file(source)
            if isinstance(loaded, dict):
                target.write_text(json.dumps(ensure_ostim_sfx_action_data(loaded), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
            else:
                shutil.copy2(source, target)
        except Exception:
            shutil.copy2(source, target)
        copied.append(target)
    return copied


def copy_ostim_furniture_type_files(data_root: Path, furniture_type_files: Sequence[Path]) -> List[Path]:
    copied: List[Path] = []
    used_names: set[str] = set()
    for source in furniture_type_files:
        if not source.exists():
            continue
        name = furniture_type_output_name(source) + source.suffix.lower()
        if name.lower() in used_names:
            continue
        used_names.add(name.lower())
        target = data_root / Path(*(FURNITURE_TYPES_REL / name).parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
        copied.append(target)
    return copied


def expected_animation_events(scene: Scene) -> List[str]:
    if is_ostim_menu_hub_scene(scene):
        return []
    events: List[str] = []
    for speed in scene.speeds:
        for animation_index in scene_animation_indexes(scene):
            events.append(f"{speed.animation}_{animation_index}")
    return events


def scene_actor_animation_index(actor: Actor, actor_position: int) -> int:
    return actor.animation_index if actor.animation_index is not None else actor_position


def actor_root_from_creature_hint(value: str) -> str:
    if not value:
        return ""
    cleaned = str(value).strip()
    compact = compact_path_part(cleaned)
    for race, actor_root in SLSB_RACE_TO_FOLDER.items():
        if cleaned.lower() == race.lower() or compact == compact_path_part(race):
            return actor_root.lower()
    legacy_race = SLSB_LEGACY_RACE_BY_COMPACT.get(compact)
    if legacy_race:
        return SLSB_RACE_TO_FOLDER.get(legacy_race, "").lower()
    for actor_root, race in SEXLAB_RACE_BY_ACTOR_ROOT.items():
        if cleaned.lower() == actor_root.lower() or compact == compact_path_part(actor_root) or compact == compact_path_part(race):
            return actor_root.lower()
    return ""


def expected_actor_root_for_scene_actor(actor: Actor) -> str:
    if not actor_is_creature(actor):
        return "character"
    candidates = [actor.creature_race, actor.type, *actor.tags]
    for candidate in candidates:
        text = str(candidate or "").strip()
        if text.startswith("creature:"):
            text = text.split(":", 1)[1]
        root = actor_root_from_creature_hint(text)
        if root and root != "character":
            return root
    return ""


def expected_animation_event_rows(scene: Scene) -> List[Dict[str, Any]]:
    if is_ostim_menu_hub_scene(scene):
        return []
    rows: List[Dict[str, Any]] = []
    for speed in scene.speeds:
        if not speed.animation:
            continue
        for actor_position, actor in enumerate(scene.actors):
            actor_index = scene_actor_animation_index(actor, actor_position)
            rows.append(
                {
                    "event": f"{speed.animation}_{actor_index}",
                    "speed": speed.animation,
                    "actorIndex": actor_index,
                    "actorPosition": actor_position,
                    "actorRoot": expected_actor_root_for_scene_actor(actor),
                    "creatureRace": actor.creature_race or "",
                    "creatureActor": actor_is_creature(actor),
                }
            )
    return rows


def expected_events_for_speed(scene: Scene, speed: Speed) -> List[str]:
    events: List[str] = []
    for animation_index in scene_animation_indexes(scene):
        events.append(f"{speed.animation}_{animation_index}")
    return events


def infer_creature_races_from_hkx_roots(scenes: Sequence[Scene], hkx_assets: Sequence[HkxAsset]) -> List[str]:
    event_roots: Dict[str, str] = {}
    for event, asset in behavior_event_entries(hkx_assets, scenes):
        actor_root = hkx_actor_root(asset.packaged_path)
        if actor_root and actor_root.lower() != "character":
            event_roots[event] = actor_root.lower()

    updated: List[str] = []
    for scene in scenes:
        for actor_position, actor in enumerate(scene.actors):
            if not actor_is_creature(actor) or actor.creature_race:
                continue
            animation_index = actor.animation_index if actor.animation_index is not None else actor_position
            roots: List[str] = []
            for speed in scene.speeds:
                root = event_roots.get(f"{speed.animation}_{animation_index}")
                if root:
                    roots.append(root)
            if not roots:
                continue
            actor_root = sorted(set(roots), key=lambda root: (-roots.count(root), root))[0]
            race = sexlab_creature_race_for_actor(actor, actor_root)
            if not race:
                continue
            actor.creature_race = race
            race_tag = f"creature:{compact_path_part(race)}"
            if race_tag not in actor.tags:
                actor.tags.append(race_tag)
            scene_race_tag = compact_path_part(race)
            if scene_race_tag:
                add_scene_tag(scene, scene_race_tag)
            updated.append(scene.raw_id or scene.scene_id or scene.name)

    if not updated:
        return []
    return [
        f"Inferred creature race metadata from HKX actor roots for {len(updated)} scene(s): {summarize_values(updated)}."
    ]


def is_startable_scene(scene: Scene) -> bool:
    return bool(scene.speeds) and bool(scene.actors) and not scene.destination and not scene.no_random_selection


def is_categorized_startable_scene(scene: Scene) -> bool:
    return is_startable_scene(scene) and bool(scene.actions)


def is_furniture_scene(scene: Scene) -> bool:
    return bool(scene.speeds) and bool(scene.actors) and not scene.destination and scene_has_furniture(scene)


def is_categorized_furniture_scene(scene: Scene) -> bool:
    return is_furniture_scene(scene) and bool(scene.actions)


def is_deployable_scene(scene: Scene) -> bool:
    return is_startable_scene(scene) or is_furniture_scene(scene)


def is_categorized_deployable_scene(scene: Scene) -> bool:
    return is_deployable_scene(scene) and bool(scene.actions)


def ostim_menu_scene_omission_reason(scene: Scene) -> str:
    if is_ostim_menu_hub_scene(scene):
        return "generated menu node"
    if not is_deployable_scene(scene):
        return "not deployable/startable"
    if not ostim_menu_signature_candidates_for_scene(scene):
        if len(scene.actors) > 5:
            return "more than five actors; no supported OStim main-menu origin"
        return "no compatible OStim main-menu actor signature"
    return ""


def ostim_menu_root_hub_ids(scenes: Sequence[Scene]) -> List[str]:
    roots = [
        scene.scene_id
        for scene in scenes
        if scene.scene_id
        and is_ostim_menu_hub_scene(scene)
        and any(is_allowed_external_ostim_menu_origin(nav.origin, nav.no_warnings) for nav in scene.navigations)
    ]
    return sorted(dict.fromkeys(roots), key=str.lower)


def ostim_menu_reachable_ids_from_roots(scenes: Sequence[Scene]) -> set[str]:
    scene_by_id = {scene.scene_id: scene for scene in scenes if scene.scene_id}
    roots = ostim_menu_root_hub_ids(scenes)
    reachable: set[str] = set()
    queue_ids = list(roots)
    while queue_ids:
        current = queue_ids.pop(0)
        if current in reachable:
            continue
        reachable.add(current)
        scene = scene_by_id.get(current)
        if not scene:
            continue
        for nav in scene.navigations:
            destination = nav.destination
            if destination and destination in scene_by_id and destination not in reachable:
                queue_ids.append(destination)
    return reachable


def ostim_menu_descendant_scene_ids(scenes: Sequence[Scene], root_id: str) -> set[str]:
    scene_by_id = {scene.scene_id: scene for scene in scenes if scene.scene_id}
    reachable: set[str] = set()
    queue_ids = [root_id]
    while queue_ids:
        current = queue_ids.pop(0)
        if current in reachable:
            continue
        reachable.add(current)
        scene = scene_by_id.get(current)
        if not scene:
            continue
        for nav in scene.navigations:
            destination = nav.destination
            if destination and destination in scene_by_id and destination not in reachable:
                queue_ids.append(destination)
    return {
        scene_id
        for scene_id in reachable
        for scene in [scene_by_id.get(scene_id)]
        if scene and is_deployable_scene(scene) and not is_ostim_menu_hub_scene(scene)
    }


def reachable_scene_ids_from_roots(scenes: Sequence[Scene], root_ids: Sequence[str]) -> set[str]:
    scene_by_id = {scene.scene_id: scene for scene in scenes if scene.scene_id}
    reachable: set[str] = set()
    queue_ids = list(root_ids)
    while queue_ids:
        current = queue_ids.pop(0)
        if current in reachable:
            continue
        reachable.add(current)
        scene = scene_by_id.get(current)
        if not scene:
            continue
        for nav in scene.navigations:
            destination = nav.destination
            if destination and destination in scene_by_id and destination not in reachable:
                queue_ids.append(destination)
    return reachable


def scene_data_path_for_scene(scene: Scene, pack: str) -> str:
    safe_pack = safe_pack_folder(pack)
    if ocreatures_menu_folder_key(scene):
        folder = sanitize_name(ocreatures_menu_folder_key(scene), "OCrUnknown")
        return data_path_text(OCREATURES_SCENES_REL / folder / f"{scene.scene_id}.json")
    if scene_has_creature(scene):
        return data_path_text(OCREATURES_SCENES_REL / safe_pack / f"{scene.scene_id}.json")
    return data_path_text(SCENES_REL / safe_pack / f"{scene.scene_id}.json")


def creature_only_deployable_pack(scenes: Sequence[Scene]) -> bool:
    deployable_scenes = [
        scene
        for scene in scenes
        if is_deployable_scene(scene) and not is_ostim_menu_hub_scene(scene)
    ]
    return bool(deployable_scenes) and all(scene_has_creature(scene) for scene in deployable_scenes)


def ocreatures_menu_root_ids(scenes: Sequence[Scene]) -> List[str]:
    return sorted(
        {
            scene.scene_id
            for scene in scenes
            if scene.scene_id and is_ocreatures_menu_root_scene(scene)
        },
        key=str.lower,
    )


def ocreatures_menu_shortest_path_to_scene(scenes: Sequence[Scene], target_id: str) -> List[str]:
    if not target_id:
        return []
    scene_by_id = {scene.scene_id: scene for scene in scenes if scene.scene_id}
    queue: List[Tuple[str, List[str]]] = [(root, [root]) for root in ocreatures_menu_root_ids(scenes)]
    visited: set[str] = set()
    while queue:
        current, path = queue.pop(0)
        if current in visited:
            continue
        visited.add(current)
        if current == target_id:
            return path
        scene = scene_by_id.get(current)
        if not scene:
            continue
        for nav in scene.navigations:
            destination = nav.destination
            if destination and destination in scene_by_id and destination not in visited:
                queue.append((destination, [*path, destination]))
    return []


def ocreatures_menu_actor_coverage_rows(scenes: Sequence[Scene]) -> List[Dict[str, Any]]:
    scene_by_id = {scene.scene_id: scene for scene in scenes if scene.scene_id}
    rows: List[Dict[str, Any]] = []
    for menu_scene in [scene for scene in scenes if is_ocreatures_menu_hub_scene(scene) and scene.scene_id]:
        reachable_ids = reachable_scene_ids_from_roots(scenes, [menu_scene.scene_id])
        reachable_creature_scenes = [
            scene
            for scene_id in reachable_ids
            for scene in [scene_by_id.get(scene_id)]
            if scene
            and is_deployable_scene(scene)
            and scene_has_creature(scene)
            and not is_ostim_menu_hub_scene(scene)
        ]
        if not reachable_creature_scenes:
            continue
        max_actor_count = max(len(scene.actors) for scene in reachable_creature_scenes)
        if len(menu_scene.actors) >= max_actor_count:
            continue
        rows.append(
            {
                "menuSceneId": menu_scene.scene_id,
                "menuSceneActorCount": len(menu_scene.actors),
                "maxReachableCreatureSceneActorCount": max_actor_count,
                "reachableCreatureSceneCount": len(reachable_creature_scenes),
                "largestReachableCreatureScenes": [
                    scene.scene_id
                    for scene in reachable_creature_scenes
                    if len(scene.actors) == max_actor_count
                ][:25],
            }
        )
    return rows


def ocreatures_menu_integration_report(
    scenes: Sequence[Scene],
    pack: str = "",
    scene_file_by_id: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    scene_file_by_id = scene_file_by_id or {}
    deployable_creature_scenes = [
        scene
        for scene in scenes
        if is_deployable_scene(scene)
        and scene_has_creature(scene)
        and not is_ostim_menu_hub_scene(scene)
    ]
    deployable_creature_ids = sorted({scene.scene_id for scene in deployable_creature_scenes if scene.scene_id}, key=str.lower)
    root_ids = ocreatures_menu_root_ids(scenes)
    reachable_ids = reachable_scene_ids_from_roots(scenes, root_ids)
    reachable_creature_ids = sorted([scene_id for scene_id in deployable_creature_ids if scene_id in reachable_ids], key=str.lower)
    unreachable_creature_ids = sorted([scene_id for scene_id in deployable_creature_ids if scene_id not in reachable_ids], key=str.lower)
    ocreatures_hubs = [scene for scene in scenes if is_ocreatures_menu_hub_scene(scene)]
    category_nodes = [scene for scene in ocreatures_hubs if ocreatures_menu_category_key(scene) and not ocreatures_menu_page_key(scene)]
    page_nodes = [scene for scene in ocreatures_hubs if ocreatures_menu_page_key(scene)]
    missing_destinations = [
        {"source": scene.scene_id, "destination": nav.destination}
        for scene in ocreatures_hubs
        for nav in scene.navigations
        if nav.destination and nav.destination not in {candidate.scene_id for candidate in scenes if candidate.scene_id}
    ]
    empty_roots = [
        scene.scene_id
        for scene in ocreatures_hubs
        if is_ocreatures_menu_root_scene(scene)
        and scene.scene_id
        and not any(nav.destination for nav in scene.navigations)
    ]
    normal_origin_rows = [
        row
        for row in scene_reference_rows(scenes)
        if is_allowed_external_ostim_menu_link_row(row)
    ]
    actor_coverage_rows = ocreatures_menu_actor_coverage_rows(scenes)
    creature_only = creature_only_deployable_pack(scenes)
    entry_generated = bool(root_ids)
    if not deployable_creature_scenes:
        mode = CREATURE_MENU_INTEGRATION_NONE
    elif entry_generated and normal_origin_rows:
        mode = CREATURE_MENU_INTEGRATION_OCREATURES_MENU_PLUS_HUMAN_DEBUG
    elif entry_generated:
        mode = CREATURE_MENU_INTEGRATION_OCREATURES_MENU
    elif normal_origin_rows:
        mode = CREATURE_MENU_INTEGRATION_OSTIM_HUMAN_MENU_ONLY
    else:
        mode = CREATURE_MENU_INTEGRATION_UNKNOWN

    if not deployable_creature_scenes:
        result = "NOT REQUIRED"
        recommended_action = "No creature scenes were written."
    elif not entry_generated:
        result = "FAIL" if creature_only else "PASS WITH WARNINGS"
        recommended_action = (
            "Creature scenes were generated, but no OCreatures menu entry was created. The pack may not appear in the creature menu even though scene files exist."
        )
    elif missing_destinations or empty_roots or unreachable_creature_ids or actor_coverage_rows:
        result = "FAIL"
        recommended_action = (
            "Do not install this ZIP until the generated OCreatures menu entry reaches every retained creature scene "
            "and its menu/helper nodes include enough actors for reachable group scenes."
        )
    else:
        result = "PASS WITH WARNINGS"
        recommended_action = (
            f"Creature menu entry generated: yes. {len(reachable_creature_ids)}/{len(deployable_creature_ids)} creature scenes reachable from OCreatures menu. "
            "Install the ZIP, run Pandora, and test from the OCreatures creature menu."
        )

    def scene_file(scene: Scene) -> str:
        if scene.scene_id in scene_file_by_id:
            return scene_file_by_id[scene.scene_id]
        return scene_data_path_for_scene(scene, pack) if pack else f"{scene.scene_id}.json"

    root_scenes = [scene for scene in ocreatures_hubs if scene.scene_id in root_ids]
    folders = sorted({ocreatures_menu_folder_key(scene) for scene in ocreatures_hubs if ocreatures_menu_folder_key(scene)}, key=str.lower)
    categories = sorted({ocreatures_menu_category_key(scene) for scene in category_nodes if ocreatures_menu_category_key(scene)}, key=str.lower)
    page_counts = Counter(ocreatures_menu_page_key(scene) for scene in page_nodes if ocreatures_menu_page_key(scene))
    return {
        "creatureOnlyPack": creature_only,
        "creatureScenesWritten": len(deployable_creature_scenes),
        "creatureMenuIntegrationMode": mode,
        "recommendedCreatureMenuIntegrationMode": (
            CREATURE_MENU_INTEGRATION_OCREATURES_MENU if deployable_creature_scenes and creature_only else mode
        ),
        "ocreaturesMenuEntryGenerated": entry_generated,
        "ocreaturesMenuEntryFile": scene_file(root_scenes[0]) if root_scenes else None,
        "ocreaturesMenuEntryFiles": [scene_file(scene) for scene in root_scenes],
        "ocreaturesRootIndexFiles": [scene_file(scene) for scene in root_scenes],
        "ocreaturesMenuOriginsUsed": folders,
        "ocreaturesMenuFolders": folders,
        "creatureMenuRootNodeCount": len(root_ids),
        "creatureMenuRootNodeIds": root_ids,
        "creatureMenuCategoryNodeCount": len(category_nodes),
        "creatureMenuCategoryNodeIds": [scene.scene_id for scene in category_nodes if scene.scene_id],
        "creatureMenuPageNodeCount": len(page_nodes),
        "creatureMenuPageNodeIds": [scene.scene_id for scene in page_nodes if scene.scene_id],
        "creatureMenuCategories": categories,
        "creatureMenuPageCounts": dict(sorted(page_counts.items())),
        "creatureScenesReachableFromOCreaturesMenu": len(reachable_creature_ids),
        "creatureScenesNotReachableFromOCreaturesMenu": len(unreachable_creature_ids),
        "reachableCreatureSceneIds": reachable_creature_ids[:500],
        "unreachableCreatureSceneIds": unreachable_creature_ids[:500],
        "missingMenuDestinationCount": len(missing_destinations),
        "missingMenuDestinations": missing_destinations[:200],
        "emptyRootEntryCount": len(empty_roots),
        "emptyRootEntryIds": empty_roots[:200],
        "menuActorCoverageResult": "PASS" if not actor_coverage_rows else "FAIL",
        "menuActorCoverageMismatchCount": len(actor_coverage_rows),
        "menuActorCoverageMismatches": actor_coverage_rows[:200],
        "normalOStimHumanMenuOriginsGenerated": bool(normal_origin_rows),
        "normalOStimHumanMenuOriginCount": len(normal_origin_rows),
        "adapterWarnings": [OCREATURES_MENU_ADAPTER_NOTE] if entry_generated else [],
        "finalOCreaturesMenuIntegrationResult": result,
        "recommendedUserAction": recommended_action,
    }


def expected_ocreatures_target_actor_slot(source_actor_slot: int) -> int:
    if source_actor_slot == 1:
        return 1
    if source_actor_slot == 2:
        return 0
    return max(0, source_actor_slot - 1)


def ocreatures_actor_mapping_rows_from_lifecycle(lifecycle_rows: Sequence[Dict[str, Any]]) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for lifecycle_row in lifecycle_rows:
        for mapping in lifecycle_row.get("actorStageMappings") or []:
            if not isinstance(mapping, dict):
                continue
            if not mapping.get("creatureScene") and mapping.get("mappingRule") != OCREATURES_SLAL_ACTOR_MAPPING_RULE:
                continue
            row = dict(mapping)
            row.setdefault("sourceAnimationId", lifecycle_row.get("sourceAnimationId"))
            row.setdefault("ostimSceneId", lifecycle_row.get("ostimSceneId"))
            row.setdefault("sourceJson", lifecycle_row.get("sourceJson"))
            rows.append(row)
    return rows


def ocreatures_actor_mapping_summary(lifecycle_rows: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    rows = ocreatures_actor_mapping_rows_from_lifecycle(lifecycle_rows)
    mismatches: List[Dict[str, Any]] = []
    for row in rows:
        source_slot = parse_int(str(row.get("sourceActorSlot") or ""), 0)
        if source_slot <= 0:
            continue
        expected_slot = expected_ocreatures_target_actor_slot(source_slot)
        actual_slot = parse_int(str(row.get("targetOCreaturesActorSlot", row.get("targetOStimActorSlot", ""))), -1)
        if actual_slot != expected_slot:
            mismatches.append(
                {
                    **row,
                    "expectedTargetOCreaturesActorSlot": expected_slot,
                    "actualTargetOCreaturesActorSlot": actual_slot,
                }
            )
    return {
        "mappingRule": OCREATURES_SLAL_ACTOR_MAPPING_RULE,
        "mappingRowsChecked": len(rows),
        "mappingMismatchCount": len(mismatches),
        "mappingMismatches": mismatches[:200],
        "mappingRows": rows[:1000],
        "finalActorMappingResult": "PASS" if rows and not mismatches else "FAIL" if mismatches else "NOT REQUIRED",
    }


def ocreatures_output_report(
    *,
    scenes: Sequence[Scene],
    pack: str,
    creature_actor_roots: Sequence[str],
    ocreatures_menu: Dict[str, Any],
    behavior_output_mode: str,
    behavior_summary: Dict[str, Any],
    lifecycle_rows: Sequence[Dict[str, Any]],
    compatibility_match: Dict[str, Any],
    fnis_animation_list_file_count: int,
    att_animation_list_file_count: int,
    pandora_generated: bool,
    reference_comparison: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    creature_scenes = [
        scene
        for scene in scenes
        if is_deployable_scene(scene)
        and scene_has_creature(scene)
        and not is_ostim_menu_hub_scene(scene)
    ]
    mapping = ocreatures_actor_mapping_summary(lifecycle_rows)
    menu_generated = bool(ocreatures_menu.get("ocreaturesMenuEntryGenerated"))
    menu_result = str(ocreatures_menu.get("finalOCreaturesMenuIntegrationResult") or "NOT REQUIRED")
    if not creature_scenes:
        enabled = False
        result = "NOT REQUIRED"
        recommended_action = "No creature scenes were written."
    else:
        enabled = True
        result = "FAIL" if menu_result.upper() == "FAIL" or mapping.get("finalActorMappingResult") == "FAIL" else "PASS WITH WARNINGS"
        recommended_action = (
            "Creature scenes were generated, but no OCreatures pack menu entry was created. The pack may not appear beside Anub/Billy/MNC."
            if not menu_generated
            else "Install the generated ZIP, run Pandora, enable/deploy Pandora output, and test from the OCreatures creature menu."
        )
    compatibility_output_recommended = bool(
        compatibility_match.get("ocreaturesOutputRecommended")
        or compatibility_match.get("creatureOutputRecommended")
        or str(compatibility_match.get("creatureMenuIntegrationRequired") or "") == CREATURE_MENU_INTEGRATION_OCREATURES_MENU
    )
    reference_summary = reference_comparison if isinstance(reference_comparison, dict) else {
        "comparisonRun": False,
        "summary": "No OCreatures reference comparison was run for this build.",
    }
    return {
        "enabled": enabled,
        "modeEnabled": enabled,
        "selectedModes": list(OCREATURES_OUTPUT_MODES) if enabled else [],
        "outputModeNames": list(OCREATURES_OUTPUT_MODES),
        "primaryMode": OCREATURES_OUTPUT_MODE_NATIVE if enabled else "none",
        "fromSlalMode": OCREATURES_OUTPUT_MODE_FROM_SLAL if mapping.get("mappingRowsChecked") else "not_used",
        "menuIndexMode": OCREATURES_OUTPUT_MODE_MENU_INDEX if menu_generated else "not_generated",
        "pandoraMode": OCREATURES_OUTPUT_MODE_PANDORA if pandora_generated else "not_generated",
        "packMenuDisplayName": pack,
        "creatureActorRoots": list(creature_actor_roots),
        "creatureScenesWritten": len(creature_scenes),
        "creatureScenesReachableFromOCreaturesMenu": int(ocreatures_menu.get("creatureScenesReachableFromOCreaturesMenu") or 0),
        "ocreaturesMenuIndexGenerated": menu_generated,
        "ocreaturesMenuIndexFiles": list(ocreatures_menu.get("ocreaturesMenuEntryFiles") or []),
        "ocreaturesRootIndexFiles": list(ocreatures_menu.get("ocreaturesRootIndexFiles") or []),
        "ocreaturesMenuFolders": list(ocreatures_menu.get("ocreaturesMenuFolders") or []),
        "actorMapping": mapping,
        "actorMappingRule": OCREATURES_SLAL_ACTOR_MAPPING_RULE,
        "hkxFilenamePolicy": OCREATURES_HKX_FILENAME_POLICY_EVENT_RENAMED,
        "referenceHkxFilenamePolicy": OCREATURES_REFERENCE_HKX_FILENAME_POLICY,
        "preserveOriginalHkxFilenames": False,
        "referencePreservesOriginalHkxFilenames": True,
        "hkxFilenamePolicyReason": (
            "AAC packages HKX files with generated event names so scene JSON, Pandora/FNIS registration, "
            "and actor-root verification use one deterministic event-to-file contract. The small reference FNIS-list "
            "rewriter preserves source filenames because it rewrites list rows rather than packaging a full scene/behavior ZIP."
        ),
        "tnFlagHandling": {
            "policy": OCREATURES_TN_FLAG_POLICY,
            "requiredForFnisStyleLists": True,
            "emittedForFnisStyleLists": bool(fnis_animation_list_file_count or att_animation_list_file_count),
            "flag": OCREATURES_TN_FLAG,
            "pandoraNativeEquivalent": "Not used; Pandora consumes the generated FNIS-style creature lists directly.",
        },
        "behaviorOutputMode": behavior_output_mode,
        "behaviorSummary": behavior_summary,
        "pandoraOutputGenerated": pandora_generated,
        "fnisStyleAnimationListGenerated": bool(fnis_animation_list_file_count),
        "attAnimationListGenerated": bool(att_animation_list_file_count),
        "runtimeRequirements": CREATURE_SUPPORT_REQUIREMENTS if creature_scenes else [],
        "knownProfileMatch": compatibility_known_pack_line(compatibility_match),
        "compatibilityProfileRecommendsOCreatures": compatibility_output_recommended,
        "referenceComparisonSummary": reference_summary,
        "finalOCreaturesOutputResult": result,
        "recommendedUserAction": recommended_action,
    }


def ocreatures_validation_summary(report: Dict[str, Any]) -> Dict[str, Any]:
    report = dict_or_empty(report)
    creature_scene_count = int(report_count(report, "creatureSceneCount", "creatureAnimationCount", default=0) or 0)
    creature_roots = list(report.get("creatureActorRoots") or report.get("creatureRootsDetected") or [])
    ocreatures_output = report.get("ocreaturesOutput") if isinstance(report.get("ocreaturesOutput"), dict) else {}
    ocreatures_menu = report.get("creatureMenuIntegration") if isinstance(report.get("creatureMenuIntegration"), dict) else {}
    behavior = report.get("behaviorRegistrationSummary") if isinstance(report.get("behaviorRegistrationSummary"), dict) else {}
    actor_mapping = ocreatures_output.get("actorMapping") if isinstance(ocreatures_output.get("actorMapping"), dict) else {}
    tn_flag = ocreatures_output.get("tnFlagHandling") if isinstance(ocreatures_output.get("tnFlagHandling"), dict) else {}

    requires_ocreatures = bool(
        creature_scene_count
        or creature_roots
        or report.get("requiresCreatureSupport")
        or ocreatures_output.get("enabled")
        or ocreatures_menu.get("ocreaturesMenuEntryGenerated")
    )
    expected_behavior_mode = (
        OSTIMSA_BEHAVIOR_MODE_NEMESIS_SAFE_WITH_CREATURE
        if requires_ocreatures
        else str(behavior.get("selectedBehaviorOutputMode") or report.get("behaviorOutputMode") or "")
    )
    selected_behavior_mode = str(
        behavior.get("selectedBehaviorOutputMode")
        or ocreatures_output.get("behaviorOutputMode")
        or report.get("behaviorOutputMode")
        or dict_or_empty(report.get("behaviorGeneration")).get("outputMode")
        or ""
    )

    def count_value(*keys: str) -> int:
        for key in keys:
            value = report.get(key)
            if isinstance(value, bool):
                continue
            if isinstance(value, (int, float)):
                return int(value)
        return 0

    duplicate_registration_count = int(behavior.get("duplicateEventRegistrationsFound") or 0)
    duplicate_file_count = (
        int(behavior.get("duplicateAnimationListFilesFound") or count_value("duplicateAnimationListFileCount") or 0)
        + int(behavior.get("duplicateAnimationDataFilesFound") or count_value("duplicateAnimationDataFileCount") or 0)
        + int(behavior.get("duplicateAnimationSetDataFilesFound") or count_value("duplicateAnimationSetDataFileCount") or 0)
        + count_value("duplicateBehaviorGraphFileCount")
    )
    osa_event_mapping = report.get("osaEventMapping") if isinstance(report.get("osaEventMapping"), dict) else {}
    duplicate_expected_event_count = count_value("duplicateExpectedSceneEventCount") or int(
        osa_event_mapping.get("duplicateExpectedSceneEventCount") or 0
    )
    missing_scene_event_count = count_value("missingAnimationEventCount", "missingHkxEventCount", "missingFnisEventCount")
    behavior_missing_hkx_count = count_value("behaviorEventsPointingToMissingHkxCount", "fnisMissingHkxFileCount")
    missing_tn_count = count_value("creatureFnisTnFlagMissingCount") or int(behavior.get("creatureFnisTnFlagMissing") or 0)
    menu_missing_count = int(ocreatures_menu.get("missingMenuDestinationCount") or 0)
    menu_unreachable_count = int(ocreatures_menu.get("creatureScenesNotReachableFromOCreaturesMenu") or 0)
    menu_empty_root_count = int(ocreatures_menu.get("emptyRootEntryCount") or 0)
    menu_actor_coverage_mismatch_count = int(ocreatures_menu.get("menuActorCoverageMismatchCount") or 0)
    actor_mapping_result = str(actor_mapping.get("finalActorMappingResult") or ("NOT REQUIRED" if not requires_ocreatures else "UNKNOWN")).upper()

    pandora_active = bool(behavior.get("pandoraOutputGenerated") or ocreatures_output.get("pandoraOutputGenerated") or report.get("pandoraOutputGenerated"))
    fnis_active = bool(behavior.get("fnisStyleListGenerated") or ocreatures_output.get("fnisStyleAnimationListGenerated") or report.get("fnisStyleAnimationListGenerated"))
    att_active = bool(behavior.get("attOutputGenerated") or report.get("attAnimationListGenerated"))
    nemesis_active = bool(behavior.get("nemesisOutputGenerated") or report.get("nemesisOutputGenerated"))
    active_components = [
        label
        for label, active in (
            ("obsolete Pandora metadata module", pandora_active),
            ("Pandora-compatible FNIS creature lists", fnis_active),
            ("Pandora-compatible ATT animation list", att_active),
            ("Pandora-compatible Nemesis behavior patch", nemesis_active),
        )
        if active
    ]
    pandora_compatible_modes = {
        OSTIMSA_BEHAVIOR_MODE_NEMESIS_SAFE,
        OSTIMSA_BEHAVIOR_MODE_NEMESIS_SAFE_WITH_CREATURE,
        OSTIMSA_BEHAVIOR_MODE_CREATURE_FNIS,
    }
    single_backend_result = (
        "FAIL"
        if selected_behavior_mode == OSTIMSA_BEHAVIOR_MODE_MIXED_INVALID
        else "PASS"
        if not requires_ocreatures or selected_behavior_mode in pandora_compatible_modes
        else "WARN"
    )

    hard_checks = [
        {
            "id": "scene_hkx_references",
            "label": "Every generated scene references registered HKX events",
            "result": "PASS" if missing_scene_event_count == 0 else "FAIL",
            "count": missing_scene_event_count,
        },
        {
            "id": "behavior_hkx_targets",
            "label": "Behavior registration points to packaged HKX files",
            "result": "PASS" if behavior_missing_hkx_count == 0 else "FAIL",
            "count": behavior_missing_hkx_count,
        },
        {
            "id": "sanitized_event_duplicates",
            "label": "No duplicate event IDs after sanitisation",
            "result": "PASS" if duplicate_expected_event_count == 0 else "FAIL",
            "count": duplicate_expected_event_count,
        },
        {
            "id": "slot_mapping",
            "label": "Actor slot mapping follows the OCreatures preset",
            "result": "PASS" if actor_mapping_result in {"PASS", "NOT REQUIRED"} else "FAIL",
            "count": int(actor_mapping.get("mappingMismatchCount") or 0),
        },
        {
            "id": "single_behavior_path",
            "label": "One selected behavior path is active for this event set",
            "result": single_backend_result,
            "activeComponents": active_components,
        },
        {
            "id": "duplicate_backend_registration",
            "label": "No duplicate behavior backend registrations",
            "result": "PASS" if duplicate_registration_count == 0 and duplicate_file_count == 0 else "FAIL",
            "count": duplicate_registration_count + duplicate_file_count,
        },
        {
            "id": "ocreatures_menu_coverage",
            "label": "OCreatures menu/index reaches retained creature scenes",
            "result": (
                "NOT REQUIRED"
                if not requires_ocreatures
                else "PASS"
                if bool(ocreatures_menu.get("ocreaturesMenuEntryGenerated"))
                and menu_missing_count == 0
                and menu_unreachable_count == 0
                and menu_empty_root_count == 0
                else "FAIL"
            ),
            "unreachableCreatureScenes": menu_unreachable_count,
            "missingMenuDestinations": menu_missing_count,
            "emptyRootEntries": menu_empty_root_count,
        },
        {
            "id": "ocreatures_menu_actor_coverage",
            "label": "OCreatures menu/helper scenes include all actors needed by reachable group scenes",
            "result": (
                "NOT REQUIRED"
                if not requires_ocreatures
                else "PASS"
                if menu_actor_coverage_mismatch_count == 0
                else "FAIL"
            ),
            "count": menu_actor_coverage_mismatch_count,
        },
        {
            "id": "creature_fnis_tn_flag",
            "label": f"Creature FNIS-style rows include {OCREATURES_TN_FLAG} when FNIS-style output is used",
            "result": "PASS" if missing_tn_count == 0 else "FAIL",
            "count": missing_tn_count,
        },
    ]
    failing_checks = [check for check in hard_checks if str(check.get("result")).upper() == "FAIL"]

    runtime_check_result = "NOT REQUIRED" if not requires_ocreatures else "NOT CHECKED"
    runtime_recommended_action = (
        "No creature scenes were written."
        if not requires_ocreatures
        else "Run --check-creature-runtime against the tester's Data/mod staging folder, or attach a creature runtime check report."
    )
    if failing_checks:
        final_result = "FAIL"
        recommended_action = "Do not install this OCreatures output yet. Fix the failed validation checks and rebuild from the original archive."
    elif requires_ocreatures:
        final_result = "PASS WITH WARNINGS"
        recommended_action = (
            "Install the generated ZIP only on a creature-capable setup, run Pandora, enable/deploy Pandora output, "
            "and confirm OCreatures, Creature Framework, and matching creature assets are installed."
        )
    else:
        final_result = "NOT REQUIRED"
        recommended_action = "No OCreatures-specific validation was required for this output."

    return {
        "target": "OCreatures / OStim Standalone" if requires_ocreatures else "OStim Standalone",
        "enabled": requires_ocreatures,
        "creatureScenesWritten": creature_scene_count,
        "creatureActorRoots": creature_roots,
        "expectedDefaultBehaviorOutput": expected_behavior_mode or OSTIMSA_BEHAVIOR_MODE_NEMESIS_SAFE,
        "selectedBehaviorOutputMode": selected_behavior_mode or "not recorded",
        "activeBehaviorComponents": active_components,
        "slotMappingRule": OCREATURES_SLAL_ACTOR_MAPPING_RULE,
        "actorMappingResult": actor_mapping_result,
        "hkxFilenamePolicy": ocreatures_output.get("hkxFilenamePolicy") or OCREATURES_HKX_FILENAME_POLICY_EVENT_RENAMED,
        "preserveOriginalHkxFilenames": bool(ocreatures_output.get("preserveOriginalHkxFilenames")),
        "tnFlagPolicy": tn_flag.get("policy") or OCREATURES_TN_FLAG_POLICY,
        "hardChecks": hard_checks,
        "failedCheckCount": len(failing_checks),
        "failedChecks": failing_checks[:50],
        "runtimeDependencyCheckResult": runtime_check_result,
        "runtimeRequirements": CREATURE_SUPPORT_REQUIREMENTS if requires_ocreatures else [],
        "runtimeRecommendedAction": runtime_recommended_action,
        "finalOCreaturesValidationResult": final_result,
        "recommendedUserAction": recommended_action,
    }


def ostim_menu_generation_report(scenes: Sequence[Scene]) -> Dict[str, Any]:
    menu_hubs = [scene for scene in scenes if is_ostim_menu_hub_scene(scene)]
    root_ids = ostim_menu_root_hub_ids(scenes)
    reachable_ids = ostim_menu_reachable_ids_from_roots(scenes)
    deployable_scenes = [scene for scene in scenes if is_deployable_scene(scene) and not is_ostim_menu_hub_scene(scene)]
    hub_linkable_scenes = [
        scene
        for scene in deployable_scenes
        if not ostim_menu_scene_omission_reason(scene)
    ]
    hub_linkable_ids = sorted({scene.scene_id for scene in hub_linkable_scenes if scene.scene_id}, key=str.lower)
    reachable_hub_linkable_ids = sorted([scene_id for scene_id in hub_linkable_ids if scene_id in reachable_ids], key=str.lower)
    unreachable_hub_linkable_ids = sorted([scene_id for scene_id in hub_linkable_ids if scene_id not in reachable_ids], key=str.lower)
    omitted_rows = [
        {
            "scene": scene.scene_id,
            "name": scene.name,
            "reason": ostim_menu_scene_omission_reason(scene),
            "furnitureStartOnly": is_furniture_scene(scene),
            "creatureRuntimeRequired": scene_has_creature(scene),
        }
        for scene in deployable_scenes
        if scene.scene_id and ostim_menu_scene_omission_reason(scene)
    ]
    category_nodes = [scene for scene in menu_hubs if ostim_menu_category_key(scene) and not ostim_menu_page_key(scene)]
    page_nodes = [scene for scene in menu_hubs if ostim_menu_page_key(scene)]
    category_counts: Dict[str, int] = {}
    category_page_counts: Dict[str, int] = {}
    for node in category_nodes:
        category = ostim_menu_category_key(node)
        if category:
            category_counts[category] = len(ostim_menu_descendant_scene_ids(scenes, node.scene_id))
    for node in page_nodes:
        category = ostim_menu_page_key(node)
        if category:
            category_page_counts[category] = category_page_counts.get(category, 0) + 1
    missing_menu_destinations = [
        {"source": scene.scene_id, "destination": nav.destination}
        for scene in menu_hubs
        for nav in scene.navigations
        if nav.destination
        and nav.destination not in {candidate.scene_id for candidate in scenes if candidate.scene_id}
        and not is_allowed_external_ostim_menu_origin(nav.destination, nav.no_warnings)
    ]
    duplicate_menu_destinations = [
        {"source": scene.scene_id, "destination": destination, "count": count}
        for scene in menu_hubs
        for destination, count in Counter(nav.destination for nav in scene.navigations if nav.destination).items()
        if destination and count > 1
    ]
    normal_human_scenes = [
        scene
        for scene in deployable_scenes
        if not scene_has_creature(scene) and not is_furniture_scene(scene)
    ]
    linked_ratio = (
        len(reachable_hub_linkable_ids) / len(hub_linkable_ids)
        if hub_linkable_ids
        else 1.0
    )
    return {
        "menuHubGenerated": bool(menu_hubs),
        "rootMenuHubCount": len(root_ids),
        "rootMenuHubIds": root_ids,
        "menuNodeCount": len(menu_hubs),
        "categoryNodeCount": len(category_nodes),
        "pageNodeCount": len(page_nodes),
        "totalScenesWritten": len(scenes),
        "normalHumanSceneCount": len(normal_human_scenes),
        "furnitureSceneCount": sum(1 for scene in deployable_scenes if is_furniture_scene(scene)),
        "creatureSceneCount": sum(1 for scene in deployable_scenes if scene_has_creature(scene)),
        "deployableSceneCount": len(deployable_scenes),
        "hubLinkableSceneCount": len(hub_linkable_ids),
        "hubLinkedSceneCount": len(reachable_hub_linkable_ids),
        "hubUnlinkedSceneCount": len(unreachable_hub_linkable_ids),
        "hubLinkedSceneIds": reachable_hub_linkable_ids[:500],
        "hubUnlinkedSceneIds": unreachable_hub_linkable_ids[:500],
        "omittedSceneCount": len(omitted_rows),
        "omittedScenes": omitted_rows[:500],
        "categoriesGenerated": sorted(category_counts, key=lambda key: OSTIM_MENU_CATEGORY_ORDER.index(key) if key in OSTIM_MENU_CATEGORY_ORDER else 999),
        "scenesPerCategory": category_counts,
        "fallbackCategoriesUsed": [key for key in ("all", "other") if category_counts.get(key)],
        "pageCounts": category_page_counts,
        "missingMenuDestinationCount": len(missing_menu_destinations),
        "missingMenuDestinations": missing_menu_destinations[:200],
        "duplicateMenuNavigationCount": len(duplicate_menu_destinations),
        "duplicateMenuNavigations": duplicate_menu_destinations[:200],
        "linkedRatio": linked_ratio,
        "recommendedAction": (
            "Open the report before installing. Most hub-linkable scenes are not reachable from the generated menu."
            if hub_linkable_ids and linked_ratio < 0.5
            else "Install the generated ZIP, run Pandora or Nemesis, then open the generated OStim pack menu."
        ),
    }


def ostim_menu_shortest_path_to_scene(scenes: Sequence[Scene], target_id: str) -> List[str]:
    if not target_id:
        return []
    scene_by_id = {scene.scene_id: scene for scene in scenes if scene.scene_id}
    roots = ostim_menu_root_hub_ids(scenes)
    queue: List[Tuple[str, List[str]]] = [(root, [root]) for root in roots]
    visited: set[str] = set()
    while queue:
        current, path = queue.pop(0)
        if current in visited:
            continue
        visited.add(current)
        if current == target_id:
            return path
        scene = scene_by_id.get(current)
        if not scene:
            continue
        for nav in scene.navigations:
            destination = nav.destination
            if destination and destination in scene_by_id and destination not in visited:
                queue.append((destination, [*path, destination]))
    return []


def finalize_sexlab_scene_lifecycle(
    lifecycle_rows: Sequence[Dict[str, Any]],
    scenes: Sequence[Scene],
    hkx_assets: Sequence[HkxAsset],
) -> List[Dict[str, Any]]:
    if not lifecycle_rows:
        return []

    scene_by_key = {
        scene.source_lifecycle_key: scene
        for scene in scenes
        if scene.source_framework == "sexlabSlal" and scene.source_lifecycle_key
    }
    reachable_ids = ostim_menu_reachable_ids_from_roots(scenes)
    ocreatures_reachable_ids = reachable_scene_ids_from_roots(scenes, ocreatures_menu_root_ids(scenes))
    registered_events = behavior_event_names(hkx_assets, scenes)
    hkx_events = {asset.event_name for asset in hkx_assets}
    finalized: List[Dict[str, Any]] = []

    for source_row in lifecycle_rows:
        row = dict(source_row)
        key = str(row.get("lifecycleKey") or "")
        scene = scene_by_key.get(key)
        generated_events = list(row.get("generatedStageEvents") or [])
        if scene:
            generated_events = expected_animation_events(scene)
        matching_events = [event for event in generated_events if event in hkx_events or event in registered_events]
        row["matchingHkxFilesFound"] = len(matching_events)
        row["matchingHkxEvents"] = matching_events[:200]
        row["behaviorValid"] = bool(generated_events) and all(event in registered_events for event in generated_events)

        if scene:
            categories = ostim_menu_primary_category_keys_for_scene(scene) if is_deployable_scene(scene) else []
            menu_path = ostim_menu_shortest_path_to_scene(scenes, scene.scene_id)
            ocreatures_menu_path = ocreatures_menu_shortest_path_to_scene(scenes, scene.scene_id)
            linked = bool(scene.scene_id and scene.scene_id in reachable_ids)
            ocreatures_linked = bool(scene.scene_id and scene.scene_id in ocreatures_reachable_ids)
            omission_reason = ostim_menu_scene_omission_reason(scene)
            missing_events = [event for event in generated_events if event not in registered_events]
            row.update(
                {
                    "ostimSceneWritten": True,
                    "ostimSceneId": scene.scene_id,
                    "displayName": scene.name or row.get("displayName") or row.get("sourceAnimationId"),
                    "actorCount": len(scene.actors),
                    "stageCount": len(scene.speeds),
                    "skipped": False,
                    "skipReason": None,
                    "classifiedCategories": categories,
                    "menuLinked": linked,
                    "menuLinkDestination": scene.scene_id if linked else None,
                    "menuPath": menu_path,
                    "ocreaturesMenuLinked": ocreatures_linked,
                    "ocreaturesMenuLinkDestination": scene.scene_id if ocreatures_linked else None,
                    "ocreaturesMenuPath": ocreatures_menu_path,
                    "furnitureOnly": is_furniture_scene(scene),
                    "creatureOnly": scene_has_creature(scene),
                    "searchOnly": is_deployable_scene(scene) and not linked,
                    "missingBehaviorEvents": missing_events[:200],
                }
            )
            if missing_events:
                row["warningReason"] = f"{len(missing_events)} generated animation event(s) are missing from packaged behavior/HKX data"
            elif not linked and omission_reason:
                row["warningReason"] = omission_reason
            elif not linked and is_deployable_scene(scene):
                row["warningReason"] = "scene was written but is not reachable from the generated OStim menu hub"
            else:
                row["warningReason"] = None
        else:
            row["ostimSceneWritten"] = False
            row["menuLinked"] = False
            row["menuLinkDestination"] = None
            row["menuPath"] = []
            row["ocreaturesMenuLinked"] = False
            row["ocreaturesMenuLinkDestination"] = None
            row["ocreaturesMenuPath"] = []
            row["behaviorValid"] = False
            row["searchOnly"] = False
            if not row.get("skipped"):
                row["skipped"] = True
                row["skipReason"] = "removed after HKX/stage validation or output repair"
            row["warningReason"] = row.get("skipReason") or "scene was not written"
        finalized.append(row)

    return finalized


def sexlab_scene_lifecycle_summary(lifecycle_rows: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    skip_reasons = Counter(str(row.get("skipReason") or "not skipped") for row in lifecycle_rows if row.get("skipped"))
    unlinked_reasons = Counter(
        str(row.get("warningReason") or "not reachable from generated OStim menu")
        for row in lifecycle_rows
        if row.get("ostimSceneWritten") and not row.get("menuLinked")
    )
    return {
        "totalSourceAnimations": len(lifecycle_rows),
        "totalOStimScenesWritten": sum(1 for row in lifecycle_rows if row.get("ostimSceneWritten")),
        "totalScenesSkipped": sum(1 for row in lifecycle_rows if row.get("skipped")),
        "skipReasons": dict(sorted(skip_reasons.items())),
        "totalHubLinkedScenes": sum(1 for row in lifecycle_rows if row.get("menuLinked")),
        "totalHubUnlinkedScenes": sum(1 for row in lifecycle_rows if row.get("ostimSceneWritten") and not row.get("menuLinked")),
        "totalOCreaturesMenuLinkedScenes": sum(1 for row in lifecycle_rows if row.get("ocreaturesMenuLinked")),
        "totalOCreaturesMenuUnlinkedScenes": sum(
            1
            for row in lifecycle_rows
            if row.get("ostimSceneWritten") and row.get("creatureOnly") and not row.get("ocreaturesMenuLinked")
        ),
        "unlinkedReasons": dict(sorted(unlinked_reasons.items())),
        "furnitureOnlyScenes": sum(1 for row in lifecycle_rows if row.get("furnitureOnly")),
        "creatureOnlyScenes": sum(1 for row in lifecycle_rows if row.get("creatureOnly")),
        "searchOnlyScenes": sum(1 for row in lifecycle_rows if row.get("searchOnly")),
        "behaviorValidScenes": sum(1 for row in lifecycle_rows if row.get("behaviorValid")),
    }


def ostim_menu_visibility_report(
    scenes: Sequence[Scene],
    menu_entry_requested: bool,
    lifecycle_rows: Sequence[Dict[str, Any]],
    menu_generation: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    menu_generation = menu_generation or ostim_menu_generation_report(scenes)
    lifecycle_summary = sexlab_scene_lifecycle_summary(lifecycle_rows)
    hub_linkable = int(menu_generation.get("hubLinkableSceneCount") or 0)
    linked = int(menu_generation.get("hubLinkedSceneCount") or 0)
    unlinked = int(menu_generation.get("hubUnlinkedSceneCount") or 0)
    missing_destinations = int(menu_generation.get("missingMenuDestinationCount") or 0)
    duplicate_navigations = int(menu_generation.get("duplicateMenuNavigationCount") or 0)
    empty_visible_menu = bool(menu_entry_requested and menu_generation.get("menuHubGenerated") and hub_linkable > 0 and linked == 0)
    no_valid_scenes = bool(menu_entry_requested and lifecycle_rows and lifecycle_summary.get("totalOStimScenesWritten") == 0)
    if empty_visible_menu:
        result = "FAIL"
        recommended_action = "Do not install this ZIP. The generated OStim pack menu would appear empty; open the report and attach it to a bug report."
    elif no_valid_scenes:
        result = "FAIL"
        recommended_action = "Do not install this ZIP. No valid OStim scenes were written from the SLAL pack; check skipped scene reasons."
    elif unlinked or missing_destinations or duplicate_navigations:
        result = "FAIL"
        recommended_action = "Do not install this ZIP until the generated OStim menu reachability errors are fixed."
    elif hub_linkable:
        result = "PASS"
        recommended_action = "Install the generated ZIP, run Pandora or Nemesis, then test the generated OStim pack menu."
    elif lifecycle_summary.get("furnitureOnlyScenes") or lifecycle_summary.get("creatureOnlyScenes"):
        result = "PASS WITH WARNINGS"
        recommended_action = "The pack contains furniture or creature scenes; test them from the matching furniture/runtime setup instead of only the normal human menu."
    else:
        result = "PASS WITH WARNINGS" if menu_entry_requested else "NOT REQUESTED"
        recommended_action = "No normal hub-linkable scenes were detected for the generated OStim menu."

    return {
        "addOStimMenuEntryEnabled": bool(menu_entry_requested),
        "menuHubGenerated": bool(menu_generation.get("menuHubGenerated")),
        "totalSLALAnimationsParsed": lifecycle_summary.get("totalSourceAnimations", 0),
        "totalOStimScenesWritten": lifecycle_summary.get("totalOStimScenesWritten", 0),
        "totalScenesSkipped": lifecycle_summary.get("totalScenesSkipped", 0),
        "skipReasonsSummary": lifecycle_summary.get("skipReasons", {}),
        "totalHubLinkableScenes": hub_linkable,
        "scenesLinkedFromGeneratedHub": linked,
        "scenesNotLinkedFromGeneratedHub": unlinked,
        "unlinkedSceneReasons": lifecycle_summary.get("unlinkedReasons", {}),
        "categoriesGenerated": list(menu_generation.get("categoriesGenerated") or []),
        "emptyCategoriesGenerated": [],
        "fallbackCategoriesUsed": list(menu_generation.get("fallbackCategoriesUsed") or []),
        "scenesPerCategory": dict(menu_generation.get("scenesPerCategory") or {}),
        "pageCounts": dict(menu_generation.get("pageCounts") or {}),
        "furnitureScenes": int(menu_generation.get("furnitureSceneCount") or 0),
        "creatureScenes": int(menu_generation.get("creatureSceneCount") or 0),
        "searchOnlyScenes": lifecycle_summary.get("searchOnlyScenes", 0),
        "duplicateIdCollisions": list(menu_generation.get("nodeIdCollisions") or []),
        "duplicateIdCollisionCount": int(menu_generation.get("nodeIdCollisionCount") or 0),
        "navigationErrors": {
            "missingMenuDestinationCount": missing_destinations,
            "duplicateMenuNavigationCount": duplicate_navigations,
        },
        "emptyVisibleMenuFailure": empty_visible_menu,
        "noValidScenesFailure": no_valid_scenes,
        "finalMenuVisibilityResult": result,
        "recommendedUserAction": recommended_action,
    }


def ostim_menu_reachability_for_deployable_scenes(scenes: Sequence[Scene]) -> Tuple[List[str], List[str]]:
    report = ostim_menu_generation_report(scenes)
    return list(report.get("hubLinkedSceneIds") or []), list(report.get("hubUnlinkedSceneIds") or [])


def is_allowed_external_ostim_menu_link_row(row: Dict[str, Any]) -> bool:
    return (
        bool(row.get("noWarnings"))
        and str(row.get("target", "")) in OSTIM_EXTERNAL_MENU_ORIGINS
        and "origin" in str(row.get("kind", ""))
    )


def is_allowed_external_ostim_menu_reference_row(row: Dict[str, Any]) -> bool:
    return (
        bool(row.get("noWarnings"))
        and str(row.get("target", "")) in OSTIM_EXTERNAL_MENU_ORIGINS
        and ("origin" in str(row.get("kind", "")) or "destination" in str(row.get("kind", "")))
    )


def scene_reference_rows(scenes: Sequence[Scene]) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for scene in scenes:
        if scene.destination:
            rows.append(
                {
                    "source": scene.scene_id,
                    "kind": "transition destination",
                    "target": scene.destination,
                    "noWarnings": scene.no_warnings,
                }
            )
        if scene.origin:
            rows.append(
                {
                    "source": scene.scene_id,
                    "kind": "transition origin",
                    "target": scene.origin,
                    "noWarnings": scene.no_warnings,
                }
            )
        for index, nav in enumerate(scene.navigations):
            if nav.destination and nav.destination != scene.scene_id:
                rows.append(
                    {
                        "source": scene.scene_id,
                        "kind": f"navigation {index} destination",
                        "target": nav.destination,
                        "noWarnings": nav.no_warnings,
                    }
                )
            if nav.origin and nav.origin != scene.scene_id:
                rows.append(
                    {
                        "source": scene.scene_id,
                        "kind": f"navigation {index} origin",
                        "target": nav.origin,
                        "noWarnings": nav.no_warnings,
                    }
                )
        for actor_index, actor in enumerate(scene.actors):
            for transition_type, destination in actor.auto_transitions.items():
                if destination:
                    rows.append(
                        {
                            "source": scene.scene_id,
                            "kind": f"actor {actor_index} autoTransition {transition_type}",
                            "target": destination,
                            "noWarnings": False,
                        }
                    )
    return rows


def missing_scene_reference_rows(scenes: Sequence[Scene]) -> List[Dict[str, Any]]:
    scene_ids = {scene.scene_id for scene in scenes if scene.scene_id}
    return [
        row
        for row in scene_reference_rows(scenes)
        if row["target"] not in scene_ids and not is_allowed_external_ostim_menu_reference_row(row)
    ]


def looks_unresolved_relative_scene_ref(value: str) -> bool:
    return "^" in value


def summarize_scene_reference_rows(rows: Sequence[Dict[str, Any]], limit: int = 5) -> str:
    shown = [f"{row['source']} {row['kind']} -> {row['target']}" for row in rows[:limit]]
    suffix = f", ... {len(rows) - limit} more" if len(rows) > limit else ""
    return "; ".join(shown) + suffix


def repair_missing_scene_links(scenes: Sequence[Scene]) -> Tuple[List[Scene], List[str]]:
    scene_by_id = {scene.scene_id: scene for scene in scenes if scene.scene_id}
    kept: List[Scene] = []
    dropped_ids: set[str] = set()
    warnings: List[str] = []

    for scene in scenes:
        if scene.destination and scene.destination not in scene_by_id:
            missing_destination = scene.destination
            if scene.speeds:
                scene.destination = None
                scene.origin = None
                scene.priority = None
                scene.no_warnings = False
                scene.no_random_selection = True
                if not scene.actions:
                    inferred_class = infer_legacy_class_from_raw_id(scene.raw_id)
                    if inferred_class:
                        infer_legacy_actions(scene, inferred_class)
                warnings.append(
                    f"{scene.raw_id}: missing external transition destination '{missing_destination}' was removed; "
                    "kept the transition animation as an internal, menu-reachable scene."
                )
            else:
                dropped_ids.add(scene.scene_id)
                warnings.append(
                    f"{scene.raw_id}: dropped transition-only scene because destination '{missing_destination}' was not converted."
                )
                continue
        kept.append(scene)

    valid_ids = {scene.scene_id for scene in kept if scene.scene_id}
    for scene in kept:
        if (
            scene.origin
            and scene.origin not in valid_ids
            and not is_allowed_external_ostim_menu_origin(scene.origin, scene.no_warnings)
        ):
            warnings.append(f"{scene.raw_id}: removed missing origin scene reference '{scene.origin}'.")
            scene.origin = None

        kept_navs: List[Navigation] = []
        for nav in scene.navigations:
            missing_parts: List[str] = []
            if nav.destination and nav.destination not in valid_ids:
                missing_parts.append(f"destination '{nav.destination}'")
            if (
                nav.origin
                and nav.origin not in valid_ids
                and not is_allowed_external_ostim_menu_origin(nav.origin, nav.no_warnings)
            ):
                missing_parts.append(f"origin '{nav.origin}'")
            if missing_parts:
                warnings.append(f"{scene.raw_id}: removed navigation with missing {' and '.join(missing_parts)}.")
                continue
            kept_navs.append(nav)
        scene.navigations = kept_navs

        if scene.actors:
            for actor_index, actor in enumerate(scene.actors):
                kept_transitions: Dict[str, str] = {}
                for transition_type, destination in actor.auto_transitions.items():
                    if destination in valid_ids:
                        kept_transitions[transition_type] = destination
                    else:
                        warnings.append(
                            f"{scene.raw_id}: removed actor {actor_index} autoTransition '{transition_type}' to missing scene '{destination}'."
                        )
                actor.auto_transitions = kept_transitions

    if dropped_ids:
        valid_ids = {scene.scene_id for scene in kept if scene.scene_id}
        for scene in kept:
            before = len(scene.navigations)
            scene.navigations = [
                nav
                for nav in scene.navigations
                if (not nav.destination or nav.destination in valid_ids)
                and (not nav.origin or nav.origin in valid_ids or is_allowed_external_ostim_menu_origin(nav.origin, nav.no_warnings))
            ]
            if before != len(scene.navigations):
                warnings.append(f"{scene.raw_id}: removed {before - len(scene.navigations)} navigation(s) to dropped transition scenes.")

    return kept, warnings


def prune_missing_scene_speeds(
    scenes: Sequence[Scene],
    hkx_assets: Sequence[HkxAsset],
    strict_when_no_events: bool = False,
) -> Tuple[List[Scene], List[str]]:
    registered_events = behavior_event_names(hkx_assets, scenes)
    if not registered_events:
        if not strict_when_no_events:
            return list(scenes), []
        kept_without_speeds = [scene for scene in scenes if not scene.speeds]
        dropped = [scene for scene in scenes if scene.speeds]
        warnings = [
            f"{scene.raw_id}: dropped scene because no deployable HKX animation events were found."
            for scene in dropped
        ]
        return kept_without_speeds, warnings

    warnings: List[str] = []
    kept_scenes: List[Scene] = []
    for scene in scenes:
        if not scene.speeds:
            kept_scenes.append(scene)
            continue

        kept: List[Speed] = []
        for speed in scene.speeds:
            expected = expected_events_for_speed(scene, speed)
            missing = [event for event in expected if event not in registered_events]
            if missing:
                label = "transition animation" if scene.destination else "animation speed"
                warnings.append(
                    f"{scene.raw_id}: skipped missing {label} '{speed.animation}' because "
                    f"{len(missing)} required HKX event(s) were not found: {summarize_values(missing)}."
                )
                continue
            kept.append(speed)
        scene.speeds = kept
        if scene.speeds or scene.destination:
            kept_scenes.append(scene)
        else:
            warnings.append(f"{scene.raw_id}: dropped scene because all animation speeds were missing from the source archive.")
    return kept_scenes, warnings


def prune_missing_transition_speeds(scenes: Sequence[Scene], hkx_assets: Sequence[HkxAsset]) -> List[str]:
    _kept_scenes, warnings = prune_missing_scene_speeds(scenes, hkx_assets)
    return warnings


