def normalize_sexlab_sound(value: Optional[str], default: str = "Squishing") -> str:
    raw = "" if value is None else str(value).strip()
    if not raw:
        raw = default
    compact = compact_path_part(raw)
    if compact in SEXLAB_SOUND_ALIASES:
        return SEXLAB_SOUND_ALIASES[compact]
    return raw


def sexlab_source_sound_literal(value: Optional[str]) -> str:
    sound = normalize_sexlab_sound(value)
    if sound == SEXLAB_NO_SOUND:
        return "NoSound"
    if sound in {"Sucking", "Squishing"}:
        return sound
    return sexlab_python_string(sound)


def scene_action_type_set(scene: Scene) -> set[str]:
    return {normalized_ostim_action_type(action.type) for action in scene.actions if action.type}


def sexlab_sound_for_scene(scene: Scene, tags: Sequence[str]) -> str:
    if scene.sexlab_sound:
        return normalize_sexlab_sound(scene.sexlab_sound)
    speed_sounds = [
        normalize_sexlab_sound(speed.sexlab_sound, SEXLAB_NO_SOUND)
        for speed in scene.speeds
        if speed.sexlab_sound
    ]
    if speed_sounds and len(set(speed_sounds)) == 1:
        return speed_sounds[0]
    lowered_tags = {tag.lower() for tag in tags}
    action_types = scene_action_type_set(scene)
    if any(action.muted for action in scene.actions):
        return SEXLAB_NO_SOUND
    if action_types & SEXLAB_SUCKING_ACTION_TYPES:
        return "Sucking"
    if action_types & SEXLAB_SQUISHING_ACTION_TYPES:
        return "Squishing"
    if action_types and action_types <= SEXLAB_QUIET_ACTION_TYPES:
        return SEXLAB_NO_SOUND
    if lowered_tags & {"blowjob", "oral", "cunnilingus", "anilingus", "rimjob"}:
        return "Sucking"
    if lowered_tags & {"kissing", "cuddling", "hugging", "foreplay"} and not (
        lowered_tags & {"sex", "vaginal", "anal", "masturbation", "handjob", "footjob", "boobjob"}
    ):
        return SEXLAB_NO_SOUND
    if lowered_tags & {"sex", "vaginal", "anal", "masturbation", "handjob", "footjob", "boobjob", "fingering"}:
        return "Squishing"
    return "Squishing"


def sexlab_stage_sound_for_scene(
    scene: Scene,
    stage_number: int,
    stage_count: int,
    animation_sound: str,
    source_stage_sound: str = "",
) -> str:
    if source_stage_sound:
        return normalize_sexlab_sound(source_stage_sound)
    sound = normalize_sexlab_sound(animation_sound)
    if sound == SEXLAB_NO_SOUND:
        return SEXLAB_NO_SOUND
    if stage_count > 1 and scene_action_type_set(scene) <= SEXLAB_QUIET_ACTION_TYPES:
        return SEXLAB_NO_SOUND
    return sound


def sexlab_actor_source_expression(actor_data: Dict[str, Any]) -> str:
    actor_type = str(actor_data.get("type") or "Male")
    args: List[str] = []
    race = actor_data.get("race")
    if actor_type.startswith("Creature"):
        args.append(f"race={sexlab_python_string(str(race or 'Dogs'))}")
    if json_bool(actor_data.get("strap_on"), False):
        args.append("strap_on=True")
    add_cum = actor_data.get("add_cum")
    cum_values: List[str] = []
    if isinstance(add_cum, str) and add_cum.strip():
        cum_values = [add_cum.strip()]
    elif isinstance(add_cum, list):
        cum_values = [str(value).strip() for value in add_cum if str(value).strip()]
    if cum_values:
        if len(cum_values) == 1 and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", cum_values[0]):
            args.append(f"add_cum={cum_values[0]}")
        else:
            args.append(f"add_cum={sexlab_python_string(','.join(cum_values))}")
    return f"{actor_type}({', '.join(args)})"


def sexlab_source_stage_expression(stage: Dict[str, Any], include_actor_specific: bool = False) -> str:
    number = int(stage.get("number") or 1)
    args: List[str] = [str(number)]
    if stage.get("timer") is not None:
        args.append(f"timer={float(stage.get('timer') or DEFAULT_LENGTH):.3f}")
    if stage.get("sound") is not None:
        args.append(f"sound={sexlab_source_sound_literal(str(stage.get('sound') or SEXLAB_NO_SOUND))}")
    if include_actor_specific:
        if stage.get("sos") is not None:
            args.append(f"sos={parse_int(str(stage.get('sos') or ''), 0)}")
        animvar_tokens, _normalized_count = normalize_sexlab_animvar_tokens(stage.get("animvars"))
        if animvar_tokens:
            animvar_text = ",".join(animvar_tokens)
            args.append(f"animvars={sexlab_python_string(animvar_text)}")
        if json_bool(stage.get("silent"), False):
            args.append("silent=True")
        if stage.get("strap_on") is not None:
            args.append(f"strap_on={str(json_bool(stage.get('strap_on'), False))}")
        if stage.get("strip") is not None:
            strip_value = stage.get("strip")
            if isinstance(strip_value, bool):
                args.append(f"strip={str(strip_value)}")
            else:
                args.append(f"strip={sexlab_python_string(str(strip_value))}")
    return f"Stage({', '.join(args)})"


def sexlab_source_id_prefix(animations: Sequence[Dict[str, Any]]) -> str:
    ids = [str(animation.get("id") or "").strip() for animation in animations if str(animation.get("id") or "").strip()]
    if not ids:
        return ""
    prefixes: List[str] = []
    for animation_id in ids:
        match = re.match(r"^([A-Za-z][A-Za-z0-9]{1,31}_).+", animation_id)
        if not match:
            return ""
        prefix = match.group(1)
        if len(animation_id) <= len(prefix):
            return ""
        prefixes.append(prefix)
    first = prefixes[0]
    if all(prefix.lower() == first.lower() for prefix in prefixes):
        return first
    return ""


def sexlab_source_name_prefix(animations: Sequence[Dict[str, Any]], id_prefix: str = "") -> str:
    names = [
        str(animation.get("name") or animation.get("id") or "").strip()
        for animation in animations
        if str(animation.get("name") or animation.get("id") or "").strip()
    ]
    if not names:
        return ""
    id_token = id_prefix.rstrip("_")
    prefixes: List[str] = []
    for name in names:
        match = re.match(r"^([A-Za-z][A-Za-z0-9]{1,31})(\s+).+", name)
        if not match:
            return ""
        prefix = f"{match.group(1)}{match.group(2)}"
        prefixes.append(prefix)
    first = prefixes[0]
    if not all(prefix.lower() == first.lower() for prefix in prefixes):
        return ""
    if id_token and compact_path_part(first) == compact_path_part(id_token):
        return first
    return first if len(names) > 1 else ""


def sexlab_source_strip_prefix(value: str, prefix: str) -> Tuple[str, bool]:
    if prefix and value.lower().startswith(prefix.lower()):
        stripped = value[len(prefix):].strip()
        if stripped:
            return stripped, True
    return value, False


def sexlab_source_animation_tags(tags_text: str, common_tags: Sequence[str]) -> Tuple[str, int]:
    tags = clean_sexlab_tags(split_tags(tags_text))
    common_keys = {compact_path_part(tag) for tag in common_tags if compact_path_part(tag)}
    overlap_count = sum(1 for tag in tags if compact_path_part(tag) in common_keys)
    source_tags = [tag for tag in tags if compact_path_part(tag) not in common_keys]
    if not source_tags:
        source_tags = ["Sex"]
    return ",".join(source_tags), overlap_count


def build_sexlab_source_text_and_quality(
    pack: str,
    animations: Sequence[Dict[str, Any]],
    discovery_tags: Optional[Sequence[str]] = None,
) -> Tuple[str, Dict[str, Any]]:
    common_tags = list(discovery_tags or [])
    id_prefix = sexlab_source_id_prefix(animations)
    name_prefix = sexlab_source_name_prefix(animations, id_prefix)
    quality: Dict[str, Any] = {
        "sourcePath": "",
        "fnisPaths": [],
        "animIdPrefix": id_prefix,
        "animNamePrefix": name_prefix,
        "animationIdsStrippedCount": 0,
        "animationNamesStrippedCount": 0,
        "doublePrefixRiskCount": 0,
        "doublePrefixRiskFixedCount": 0,
        "sourceFinalIdMismatchCount": 0,
        "commonTags": common_tags,
        "commonTagOverlapRemovedCount": 0,
        "discoveryTagsEnabled": bool(common_tags),
        "duplicateActorDeclarationRiskCount": 0,
        "actorStageParamCollapsedCount": 0,
        "animvarNormalizedCount": 0,
        "animvarCollapsedCount": 0,
        "sosCollapsedCount": 0,
        "fnisDuplicateEventCount": 0,
        "skippedInvalidSceneCount": 0,
        "skippedInvalidScenes": [],
        "warnings": [],
        "recommendedAction": "Install the generated ZIP, run FNIS/Nemesis/Pandora, then register or enable the pack in SexLab.",
    }
    lines: List[str] = [
        f"mcm_name = {sexlab_python_string(pack)}",
        f"anim_dir({sexlab_python_string(safe_pack_folder(pack))})",
    ]
    if id_prefix:
        lines.append(f"anim_id_prefix({sexlab_python_string(id_prefix)})")
    if name_prefix:
        lines.append(f"anim_name_prefix({sexlab_python_string(name_prefix)})")
    if common_tags:
        lines.append(f"common_tags({sexlab_python_string(','.join(common_tags))})")
    lines.append("")
    for animation in animations:
        actor_lines = []
        for index, actor_data in enumerate(animation.get("actors") or [], start=1):
            actor_lines.append(f"    actor{index}={sexlab_actor_source_expression(actor_data)},")
        stage_lines = []
        for stage in animation.get("stages") or []:
            if isinstance(stage, dict) and sexlab_stage_has_generic_params(stage):
                stage_lines.append(f"        {sexlab_source_stage_expression(stage)},")
        actor_stage_param_blocks: List[Tuple[int, List[str]]] = []
        for actor_index, actor_data in enumerate(animation.get("actors") or [], start=1):
            actor_param_lines: List[str] = []
            for stage_for_source in compact_sexlab_actor_stage_params(actor_data.get("stages") or [], quality):
                actor_param_lines.append(f"        {sexlab_source_stage_expression(stage_for_source, include_actor_specific=True)},")
            if actor_param_lines:
                actor_stage_param_blocks.append((actor_index, actor_param_lines))
        final_id = str(animation.get("id") or "Animation")
        source_id, id_stripped = sexlab_source_strip_prefix(final_id, id_prefix)
        if id_stripped:
            quality["animationIdsStrippedCount"] += 1
            quality["doublePrefixRiskCount"] += 1
            quality["doublePrefixRiskFixedCount"] += 1
        generated_id = f"{id_prefix}{source_id}" if id_prefix else source_id
        if generated_id != final_id:
            quality["sourceFinalIdMismatchCount"] += 1
            quality["warnings"].append(f"{final_id}: source ID plus anim_id_prefix would generate {generated_id}.")
        final_name = str(animation.get("name") or animation.get("id") or "Animation")
        source_name, name_stripped = sexlab_source_strip_prefix(final_name, name_prefix)
        if name_stripped:
            quality["animationNamesStrippedCount"] += 1
        source_tags, common_overlap_count = sexlab_source_animation_tags(str(animation.get("tags") or "Sex"), common_tags)
        quality["commonTagOverlapRemovedCount"] += common_overlap_count
        lines.extend(
            [
                "Animation(",
                f"    id={sexlab_python_string(source_id)},",
                f"    name={sexlab_python_string(source_name)},",
                f"    tags={sexlab_python_string(source_tags)},",
                f"    sound={sexlab_source_sound_literal(str(animation.get('sound') or 'Squishing'))},",
                *actor_lines,
            ]
        )
        if stage_lines:
            lines.append("    stage_params=[")
            lines.extend(stage_lines)
            lines.append("    ],")
        for actor_index, actor_param_lines in actor_stage_param_blocks:
            lines.append(f"    a{actor_index}_stage_params=[")
            lines.extend(actor_param_lines)
            lines.append("    ],")
        lines.extend([")", ""])
    return "\n".join(lines).rstrip() + "\n", quality


def sexlab_source_text(
    pack: str,
    animations: Sequence[Dict[str, Any]],
    discovery_tags: Optional[Sequence[str]] = None,
) -> str:
    text, _quality = build_sexlab_source_text_and_quality(pack, animations, discovery_tags)
    return text


SLSB_ID_ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyz"


def slsb_hash_id(*parts: Any, length: int = 8) -> str:
    digest = hashlib.sha1("||".join(str(part) for part in parts).encode("utf-8")).digest()
    value = int.from_bytes(digest[:8], "big")
    chars: List[str] = []
    while value:
        value, remainder = divmod(value, len(SLSB_ID_ALPHABET))
        chars.append(SLSB_ID_ALPHABET[remainder])
    encoded = "".join(reversed(chars)) or "0"
    return encoded[-length:].rjust(length, "0")


def slsb_unique_id(used: set[str], *parts: Any, length: int = 8) -> str:
    index = 0
    while True:
        candidate = slsb_hash_id(*parts, index, length=length)
        if candidate not in used:
            used.add(candidate)
            return candidate
        index += 1


def slsb_tags_from_animation(animation: Dict[str, Any]) -> List[str]:
    tags: List[str] = []
    for tag in split_tags(str(animation.get("tags") or "")):
        lowered = tag.lower()
        if lowered and lowered not in tags:
            tags.append(lowered)
    sound = normalize_sexlab_sound(str(animation.get("sound") or ""), SEXLAB_NO_SOUND)
    if sound == "Sucking" and "sucking" not in tags:
        tags.append("sucking")
    elif sound == "Squishing" and "squishing" not in tags:
        tags.append("squishing")
    return tags


def slsb_position_sex(actor_data: Dict[str, Any]) -> Dict[str, bool]:
    source_flags = actor_data.get("_slsbSex")
    if isinstance(source_flags, dict):
        flags = {
            "male": json_bool(source_flags.get("male"), False),
            "female": json_bool(source_flags.get("female"), False),
            "futa": json_bool(source_flags.get("futa"), False),
        }
        if any(flags.values()):
            return flags
    actor_type = str(actor_data.get("type") or "").lower()
    is_female = "female" in actor_type
    is_male = "male" in actor_type and not is_female
    if not is_female and not is_male:
        is_male = True
    return {
        "male": is_male,
        "female": is_female,
        "futa": False,
    }


def slsb_normalize_race_name(race: Any) -> str:
    race_name = str(race or "Human")
    if race_name in SLSB_RACE_KEYS:
        return race_name
    return SLSB_LEGACY_RACE_BY_COMPACT.get(compact_path_part(race_name), race_name)


def slsb_position_for_actor(actor_data: Dict[str, Any], stage_index: int) -> Dict[str, Any]:
    stages = actor_data.get("stages") if isinstance(actor_data.get("stages"), list) else []
    stage = stages[stage_index] if stage_index < len(stages) and isinstance(stages[stage_index], dict) else {}
    actor_type = str(actor_data.get("type") or "")
    race = slsb_normalize_race_name(actor_data.get("race") or ("Human" if not actor_type.startswith("Creature") else "Unknown"))
    custom_flags = ["silent"] if json_bool(stage.get("silent"), False) else []
    animvars = stage.get("animvars") if isinstance(stage.get("animvars"), dict) else {}
    custom_flags.extend(f"{key}={value}" for key, value in sorted(animvars.items()))
    return {
        "sex": slsb_position_sex(actor_data),
        "race": race,
        "event": [str(stage.get("id") or "")],
        "scale": 1.0,
        "extra": {
            "submissive": False,
            "vampire": False,
            "climax": False,
            "dead": False,
            "custom": custom_flags,
        },
        "offset": {
            "x": 0.0,
            "y": 0.0,
            "z": 0.0,
            "r": 0.0,
        },
        "anim_obj": "",
        "strip_data": {
            "default": True,
            "everything": False,
            "nothing": False,
            "helmet": False,
            "gloves": False,
            "boots": False,
        },
        "schlong": parse_int(str(stage.get("sos") or ""), 0) if isinstance(stage, dict) else 0,
    }


def slsb_position_info_from_position(position: Dict[str, Any]) -> Dict[str, Any]:
    extra = position.get("extra") if isinstance(position.get("extra"), dict) else {}
    return {
        "sex": position.get("sex") if isinstance(position.get("sex"), dict) else {"male": True, "female": False, "futa": False},
        "race": slsb_normalize_race_name(position.get("race") or "Human"),
        "scale": parse_float(str(position.get("scale") or ""), 1.0),
        "submissive": json_bool(extra.get("submissive"), False),
        "vampire": json_bool(extra.get("vampire"), False),
        "dead": json_bool(extra.get("dead"), False),
    }


def slsb_furniture_for_animation(animation: Dict[str, Any]) -> Dict[str, Any]:
    furniture = canonical_ostim_furniture_type(str(animation.get("furniture") or ""))
    furniture_types = SLSB_FURNITURE_BY_OSTIM_TYPE.get(furniture, ["None"])
    return {
        "furni_types": furniture_types,
        "allow_bed": furniture == "bed",
        "offset": {
            "x": 0.0,
            "y": 0.0,
            "z": 0.0,
            "r": 0.0,
        },
    }


def build_slsb_source(pack: str, mod_author: Optional[str], animations: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    used_ids: set[str] = set()
    scenes: Dict[str, Any] = {}
    prefix_hash = slsb_hash_id("prefix", pack, length=4)
    for animation in animations:
        animation_id = str(animation.get("id") or animation.get("name") or "Animation")
        scene_id = slsb_unique_id(used_ids, pack, animation_id)
        stages_in = animation.get("stages") if isinstance(animation.get("stages"), list) else []
        actor_data = [actor for actor in (animation.get("actors") or []) if isinstance(actor, dict)]
        stage_nodes: List[Dict[str, Any]] = []
        stage_ids: List[str] = []
        for stage_index, stage in enumerate(stages_in):
            if not isinstance(stage, dict):
                continue
            stage_id = slsb_unique_id(used_ids, pack, animation_id, stage.get("number") or stage_index + 1)
            stage_ids.append(stage_id)
            stage_tags = slsb_tags_from_animation(animation)
            stage_sound = normalize_sexlab_sound(str(stage.get("sound") or animation.get("sound") or ""), SEXLAB_NO_SOUND)
            if stage_sound == SEXLAB_NO_SOUND and "nosound" not in stage_tags:
                stage_tags.append("nosound")
            stage_nodes.append(
                {
                    "id": stage_id,
                    "name": "",
                    "positions": [slsb_position_for_actor(actor, stage_index) for actor in actor_data],
                    "tags": stage_tags,
                    "extra": {
                        "fixed_len": parse_float(str(stage.get("timer") or ""), 0.0),
                        "nav_text": "",
                    },
                }
            )
        graph = {
            stage_id: {
                "dest": [stage_ids[index + 1]] if index + 1 < len(stage_ids) else [],
                "x": 40.0,
                "y": 40.0,
            }
            for index, stage_id in enumerate(stage_ids)
        }
        scene_positions = [
            slsb_position_info_from_position(position)
            for position in (stage_nodes[0].get("positions") if stage_nodes else [])
            if isinstance(position, dict)
        ]
        scenes[scene_id] = {
            "id": scene_id,
            "name": str(animation.get("name") or animation_id),
            "stages": stage_nodes,
            "root": stage_ids[0] if stage_ids else "",
            "graph": graph,
            "furniture": slsb_furniture_for_animation(animation),
            "private": False,
            "positions": scene_positions,
            "has_warnings": False,
        }
    return {
        "version": SLSB_PROJECT_VERSION,
        "pack_name": pack,
        "pack_author": normalized_mod_author(mod_author),
        "prefix_hash": prefix_hash,
        "scenes": scenes,
    }


def slsb_write_u8(buf: bytearray, value: int) -> None:
    buf.append(max(0, min(255, int(value))))


def slsb_write_u32(buf: bytearray, value: int) -> None:
    buf.extend(int(value).to_bytes(4, "big", signed=False))


def slsb_write_u64(buf: bytearray, value: int) -> None:
    buf.extend(int(value).to_bytes(8, "big", signed=False))


def slsb_write_scaled_f32(buf: bytearray, value: Any) -> None:
    scaled = int(round(parse_float(str(value or ""), 0.0) * 1000.0))
    buf.extend(scaled.to_bytes(4, "big", signed=True))


def slsb_write_bool(buf: bytearray, value: Any) -> None:
    buf.append(1 if bool(value) else 0)


def slsb_write_string(buf: bytearray, value: Any) -> None:
    data = str(value or "").encode("utf-8")
    slsb_write_u64(buf, len(data))
    buf.extend(data)


def slsb_normalize_nanoid(value: Any, length: int) -> str:
    text = re.sub(r"[^a-zA-Z0-9]", "", str(value or "").lower())
    if not text:
        text = "0" * length
    if len(text) < length:
        text = text.rjust(length, "0")
    return text[:length]


def slsb_write_nanoid(buf: bytearray, value: Any, length: int = 8) -> None:
    buf.extend(slsb_normalize_nanoid(value, length).encode("ascii"))


def slsb_write_string_vec(buf: bytearray, values: Iterable[Any], normalize_tags: bool = False) -> None:
    normalized: List[str] = []
    for value in values:
        text = str(value or "")
        if normalize_tags:
            text = "".join(ch for ch in text if not ch.isspace()).lower()
        if text:
            normalized.append(text)
    slsb_write_u64(buf, len(normalized))
    for value in normalized:
        slsb_write_string(buf, value)


def slsb_write_offset(buf: bytearray, offset: Any) -> None:
    data = offset if isinstance(offset, dict) else {}
    for key in ("x", "y", "z", "r"):
        slsb_write_scaled_f32(buf, data.get(key, 0.0))


def slsb_write_sex(buf: bytearray, sex: Any) -> None:
    data = sex if isinstance(sex, dict) else {}
    male = json_bool(data.get("male"), False)
    female = json_bool(data.get("female"), False)
    futa = json_bool(data.get("futa"), False)
    if not male and not female and not futa:
        male = True
    slsb_write_u8(buf, (1 if male else 0) + (2 if female else 0) + (4 if futa else 0))


def slsb_write_stripping(buf: bytearray, stripping: Any) -> None:
    data = stripping if isinstance(stripping, dict) else {}
    if json_bool(data.get("default"), True):
        slsb_write_u8(buf, 1 << 7)
    elif json_bool(data.get("everything"), False):
        slsb_write_u8(buf, 255)
    elif json_bool(data.get("nothing"), False):
        slsb_write_u8(buf, 0)
    else:
        slsb_write_u8(
            buf,
            (1 if json_bool(data.get("helmet"), False) else 0)
            + (2 if json_bool(data.get("gloves"), False) else 0)
            + (4 if json_bool(data.get("boots"), False) else 0),
        )


def slsb_race_key(race: Any, warnings: List[str]) -> int:
    race_name = slsb_normalize_race_name(race)
    if race_name in SLSB_RACE_KEYS:
        return SLSB_RACE_KEYS[race_name]
    warnings.append(f"SLSB registry used Human race fallback for unknown SexLab P+ race '{race_name}'.")
    return SLSB_RACE_KEYS["Human"]


def slsb_write_position_info(buf: bytearray, position: Dict[str, Any], warnings: List[str]) -> None:
    extra = position.get("extra") if isinstance(position.get("extra"), dict) else {}
    slsb_write_u8(buf, slsb_race_key(position.get("race"), warnings))
    slsb_write_sex(buf, position.get("sex"))
    slsb_write_scaled_f32(buf, position.get("scale", 1.0))
    slsb_write_u8(
        buf,
        (1 if json_bool(position.get("submissive", extra.get("submissive")), False) else 0)
        + (2 if json_bool(position.get("vampire", extra.get("vampire")), False) else 0)
        + (4 if json_bool(position.get("dead", extra.get("dead")), False) else 0),
    )


def slsb_position_tags(position: Dict[str, Any]) -> List[str]:
    tags = [str(tag) for tag in position.get("tags") or [] if str(tag or "")]
    extra = position.get("extra") if isinstance(position.get("extra"), dict) else {}
    for tag in extra.get("custom") or []:
        text = str(tag or "")
        if text and text not in tags:
            tags.append(text)
    return tags


def slsb_write_position(buf: bytearray, position: Dict[str, Any]) -> None:
    events = position.get("event") if isinstance(position.get("event"), list) else [position.get("event")]
    slsb_write_string(buf, events[0] if events else "")
    extra = position.get("extra") if isinstance(position.get("extra"), dict) else {}
    slsb_write_bool(buf, json_bool(position.get("climax", extra.get("climax")), False))
    slsb_write_offset(buf, position.get("offset"))
    slsb_write_stripping(buf, position.get("strip_data"))
    slsb_write_string_vec(buf, slsb_position_tags(position))


def slsb_scene_positions(scene: Dict[str, Any]) -> List[Dict[str, Any]]:
    positions = scene.get("positions")
    if isinstance(positions, list) and positions:
        return [position for position in positions if isinstance(position, dict)]
    stages = scene.get("stages") if isinstance(scene.get("stages"), list) else []
    first_stage = stages[0] if stages and isinstance(stages[0], dict) else {}
    stage_positions = first_stage.get("positions") if isinstance(first_stage.get("positions"), list) else []
    return [
        slsb_position_info_from_position(position)
        for position in stage_positions
        if isinstance(position, dict)
    ]


def slsb_write_stage(buf: bytearray, stage: Dict[str, Any]) -> None:
    slsb_write_nanoid(buf, stage.get("id"))
    positions = [position for position in stage.get("positions") or [] if isinstance(position, dict)]
    slsb_write_u64(buf, len(positions))
    for position in positions:
        slsb_write_position(buf, position)
    extra = stage.get("extra") if isinstance(stage.get("extra"), dict) else {}
    slsb_write_scaled_f32(buf, extra.get("fixed_len", 0.0))
    slsb_write_string(buf, extra.get("nav_text", ""))
    slsb_write_string_vec(buf, stage.get("tags") or [], normalize_tags=True)


def slsb_write_graph(buf: bytearray, graph: Any) -> None:
    nodes = graph if isinstance(graph, dict) else {}
    slsb_write_u64(buf, len(nodes))
    for key, node in nodes.items():
        node_data = node if isinstance(node, dict) else {}
        dest = node_data.get("dest", [])
        if isinstance(dest, str):
            dest_values = [dest] if dest else []
        elif isinstance(dest, list):
            dest_values = dest
        else:
            dest_values = []
        slsb_write_nanoid(buf, key)
        slsb_write_u64(buf, len(dest_values))
        for target in dest_values:
            slsb_write_nanoid(buf, target)


def slsb_furniture_bits(furniture: Any) -> int:
    data = furniture if isinstance(furniture, dict) else {}
    bits = 0
    for value in data.get("furni_types") or ["None"]:
        bits |= SLSB_FURNITURE_BITS.get(str(value or ""), 0)
    return bits


def slsb_write_furniture(buf: bytearray, furniture: Any) -> None:
    data = furniture if isinstance(furniture, dict) else {}
    slsb_write_u32(buf, slsb_furniture_bits(data))
    slsb_write_bool(buf, json_bool(data.get("allow_bed"), False))
    slsb_write_offset(buf, data.get("offset"))


def slsb_write_scene(buf: bytearray, scene: Dict[str, Any], warnings: List[str]) -> None:
    slsb_write_nanoid(buf, scene.get("id"))
    slsb_write_string(buf, scene.get("name", ""))
    positions = slsb_scene_positions(scene)
    slsb_write_u64(buf, len(positions))
    for position in positions:
        slsb_write_position_info(buf, position, warnings)
    stages = [stage for stage in scene.get("stages") or [] if isinstance(stage, dict)]
    slsb_write_u64(buf, len(stages))
    for stage in stages:
        slsb_write_stage(buf, stage)
    slsb_write_graph(buf, scene.get("graph"))
    slsb_write_furniture(buf, scene.get("furniture"))
    slsb_write_bool(buf, json_bool(scene.get("private"), False))


def build_slsb_registry_bytes(package: Dict[str, Any]) -> Tuple[bytes, List[str]]:
    warnings: List[str] = []
    buf = bytearray()
    slsb_write_u8(buf, SLSB_PROJECT_VERSION)
    slsb_write_string(buf, package.get("pack_name") or "")
    slsb_write_string(buf, package.get("pack_author") or DEFAULT_METADATA_AUTHOR)
    slsb_write_nanoid(buf, package.get("prefix_hash"), length=4)
    scene_values = [
        scene
        for scene in (package.get("scenes") or {}).values()
        if isinstance(scene, dict) and not json_bool(scene.get("has_warnings"), False) and scene.get("stages")
    ]
    slsb_write_u64(buf, len(scene_values))
    for scene in scene_values:
        slsb_write_scene(buf, scene, warnings)
    return bytes(buf), sorted(set(warnings))


def slsb_position_event_values(position: Dict[str, Any]) -> List[str]:
    events = position.get("event") if isinstance(position.get("event"), list) else [position.get("event")]
    return [str(event) for event in events if str(event or "")]


def slsb_animation_object_values(position: Dict[str, Any]) -> List[str]:
    value = str(position.get("anim_obj") or "")
    return [item.strip() for item in value.split(",") if item.strip()]


def slsb_make_fnis_line(anim_type: str, event: str, prefix_hash: str, options: str, anim_objects: Sequence[str]) -> str:
    if not options and not anim_objects:
        option_text = ""
    elif not anim_objects:
        option_text = f" -{options}"
    elif not options:
        option_text = " -o"
    else:
        option_text = f" -o,{options}"
    object_text = "".join(f" {item}" for item in anim_objects)
    return f"{anim_type}{option_text} {prefix_hash}{event} {event}.hkx{object_text}"


def slsb_make_fnis_lines(events: Sequence[str], prefix_hash: str, fixed_len: bool, anim_objects: Sequence[str]) -> List[str]:
    clean_events = [event for event in events if event]
    if not clean_events:
        return []
    if len(clean_events) == 1:
        return [slsb_make_fnis_line("b", clean_events[0], prefix_hash, "a,Tn" if fixed_len else "", anim_objects)]
    lines: List[str] = []
    for index, event in enumerate(clean_events):
        lines.append(
            slsb_make_fnis_line(
                "s" if index == 0 else "+",
                event,
                prefix_hash,
                "a,Tn" if fixed_len and index == len(clean_events) - 1 else "",
                anim_objects,
            )
        )
    return lines


def slsb_race_aliases(race: str) -> List[str]:
    if race == "Canine":
        return ["Canine", "Dog", "Wolf"]
    if race in {"Dog", "Wolf"}:
        return [race, "Canine"]
    if race in {"Chaurus", "Chaurus Reaper"}:
        return ["Chaurus"]
    if race in {"Spider", "Large Spider", "Giant Spider"}:
        return ["Spider"]
    if race in {"Boar", "Boar (Mounted)", "Boar (Any)"}:
        return ["Boar (Any)"]
    return [race]


def slsb_fnis_list_name(safe_pack: str, race: str, actor_folder: str) -> str:
    creature_token = actor_folder.rsplit("/", 1)[-1]
    if creature_token == "character":
        return f"FNIS_{safe_pack}_List.txt"
    if creature_token == "canine":
        if race == "Canine":
            return f"FNIS_{safe_pack}_canine_List.txt"
        if race == "Dog":
            return f"FNIS_{safe_pack}_dog_List.txt"
        return f"FNIS_{safe_pack}_wolf_List.txt"
    return f"FNIS_{safe_pack}_{creature_token}_List.txt"


def build_slsb_fnis_lines(package: Dict[str, Any], safe_pack: str) -> Tuple[Dict[PurePosixPath, List[str]], List[str]]:
    warnings: List[str] = []
    prefix_hash = slsb_normalize_nanoid(package.get("prefix_hash"), 4)
    events_by_race: Dict[str, List[str]] = {}
    used_events = {"__BLANK__", "__DEFAULT__"}
    for scene in (package.get("scenes") or {}).values():
        if not isinstance(scene, dict) or json_bool(scene.get("has_warnings"), False):
            continue
        scene_positions = slsb_scene_positions(scene)
        for stage in scene.get("stages") or []:
            if not isinstance(stage, dict):
                continue
            stage_positions = [position for position in stage.get("positions") or [] if isinstance(position, dict)]
            if len(stage_positions) != len(scene_positions):
                warnings.append(
                    f"SLSB scene '{scene.get('name') or scene.get('id')}' has {len(stage_positions)} stage position(s) "
                    f"but {len(scene_positions)} actor position definition(s); skipped P+ FNIS lines for that stage."
                )
                continue
            fixed_len = parse_float(str(dict_or_empty(stage.get("extra")).get("fixed_len") or ""), 0.0) > 0.0
            for index, position in enumerate(stage_positions):
                events = slsb_position_event_values(position)
                if not events:
                    continue
                first_event = events[0]
                if first_event in used_events:
                    continue
                used_events.add(first_event)
                lines = slsb_make_fnis_lines(events, prefix_hash, fixed_len, slsb_animation_object_values(position))
                race = slsb_normalize_race_name(scene_positions[index].get("race") or "Human")
                for alias in slsb_race_aliases(race):
                    events_by_race.setdefault(alias, []).extend(lines)

    fnis_lines_by_path: Dict[PurePosixPath, List[str]] = {}
    for race, lines in events_by_race.items():
        actor_folder = SLSB_RACE_TO_FOLDER.get(race)
        if not actor_folder:
            warnings.append(f"SLSB P+ FNIS lines used Human folder fallback for unknown race '{race}'.")
            actor_folder = SLSB_RACE_TO_FOLDER["Human"]
        anim_dir = PurePosixPath("meshes/actors") / PurePosixPath(actor_folder) / "animations" / safe_pack
        list_rel = anim_dir / slsb_fnis_list_name(safe_pack, race, actor_folder)
        fnis_lines_by_path[list_rel] = ["Version V1.0", "", "' SexLab P+ registry events", *lines]
    return fnis_lines_by_path, sorted(set(warnings))


def merge_fnis_line_sets(
    base_lines: Dict[PurePosixPath, List[str]],
    extra_lines: Dict[PurePosixPath, List[str]],
) -> Dict[PurePosixPath, List[str]]:
    merged = {path: list(lines) for path, lines in base_lines.items()}
    for path, lines in extra_lines.items():
        target = merged.setdefault(path, ["Version V1.0"])
        existing = set(target)
        additions = [line for line in lines if line and line != "Version V1.0" and line not in existing]
        if not additions:
            continue
        if target and target[-1] != "":
            target.append("")
        target.extend(additions)
    return merged


def record_sexlab_skipped_scene(
    style_report: Dict[str, Any],
    warnings: List[str],
    scene: Scene,
    reason: str,
) -> None:
    scene_name = scene.raw_id or scene.scene_id or scene.name or "Scene"
    row = {"scene": scene_name, "reason": reason}
    style_report["skippedInvalidSceneCount"] = style_report.get("skippedInvalidSceneCount", 0) + 1
    skipped_rows = style_report.setdefault("skippedInvalidScenes", [])
    if isinstance(skipped_rows, list) and len(skipped_rows) < 200:
        skipped_rows.append(row)
    warnings.append(f"{scene_name}: skipped for SexLab export because {reason}.")


def build_sexlab_export(
    scenes: Sequence[Scene],
    hkx_assets: Sequence[HkxAsset],
    pack: str,
    sexlab_discovery_tags: bool = DEFAULT_SEXLAB_DISCOVERY_TAGS_ENABLED,
) -> Tuple[List[Dict[str, Any]], List[HkxAsset], Dict[PurePosixPath, List[str]], List[str], Dict[str, Any]]:
    safe_pack = safe_pack_folder(pack)
    event_assets: Dict[str, HkxAsset] = {}
    for event_name, asset in behavior_event_entries(hkx_assets, scenes):
        event_assets.setdefault(event_name, asset)

    animations: List[Dict[str, Any]] = []
    export_assets: List[HkxAsset] = []
    fnis_lines_by_path: Dict[PurePosixPath, List[str]] = {}
    warnings: List[str] = []
    used_ids: Dict[str, int] = {}
    style_report: Dict[str, Any] = {
        "source": "OStim",
        "sexLabNativeSourceStyle": True,
        "discoveryTagsEnabled": sexlab_discovery_tags,
        "actorRoleRows": [],
        "actorOrderChangedCount": 0,
        "ambiguousActorRoleCount": 0,
        "tagRows": [],
        "animationLevelSoundCount": 0,
        "stageLevelSoundOverrideCount": 0,
        "redundantStageSoundRemovedCount": 0,
        "timerEmissionCount": 0,
        "actorSpecificStageParamCount": 0,
        "cumMetadataCount": 0,
        "sosMetadataCount": 0,
        "skippedInvalidSceneCount": 0,
        "skippedInvalidScenes": [],
        "fnisDuplicateEventCount": 0,
        "fnisDuplicateEvents": [],
        "warnings": [],
    }
    registered_fnis_events: set[str] = set()

    for scene in scenes:
        if is_ostim_menu_hub_scene(scene):
            record_sexlab_skipped_scene(style_report, warnings, scene, "it is an OStim menu/navigation hub, not a playable SexLab animation")
            continue
        if not is_deployable_scene(scene):
            record_sexlab_skipped_scene(style_report, warnings, scene, "it is an OStim transition, idle, internal, or non-startable scene")
            continue
        actor_indexes = scene_animation_indexes(scene)
        if len(actor_indexes) > 5:
            warnings.append(f"{scene.raw_id}: skipped for SexLab export because SLAL supports at most 5 actors.")
            continue

        animation_id = sexlab_unique_animation_id(scene, used_ids)
        complete_stage_rows: List[Tuple[Speed, List[Tuple[int, HkxAsset]]]] = []
        for speed in scene.speeds:
            missing_events: List[str] = []
            stage_assets: List[Tuple[int, HkxAsset]] = []
            for actor_position, animation_index in enumerate(actor_indexes):
                event_name = f"{speed.animation}_{animation_index}"
                asset = event_assets.get(event_name)
                if asset is None:
                    missing_events.append(event_name)
                    continue
                stage_assets.append((actor_position, asset))
            if missing_events:
                warnings.append(
                    f"{scene.raw_id}: skipped SexLab stage '{speed.animation}' because required HKX event(s) were missing: "
                    f"{summarize_values(missing_events)}."
                )
                continue
            complete_stage_rows.append((speed, stage_assets))

        if not complete_stage_rows:
            warnings.append(f"{scene.raw_id}: skipped for SexLab export because no complete actor stages were available.")
            continue
        usable_actor_stage_hkx_count = sum(len(stage_assets) for _speed, stage_assets in complete_stage_rows)
        if usable_actor_stage_hkx_count <= 1 or usable_actor_stage_hkx_count < len(actor_indexes):
            record_sexlab_skipped_scene(
                style_report,
                warnings,
                scene,
                f"only {usable_actor_stage_hkx_count} usable actor-stage HKX event(s) were available for {len(actor_indexes)} actor(s)",
            )
            continue

        actor_root_votes: Dict[int, Dict[str, int]] = {index: {} for index in range(len(actor_indexes))}
        actor_root_first_seen: Dict[int, Dict[str, int]] = {index: {} for index in range(len(actor_indexes))}
        for row_index, (_speed, stage_assets) in enumerate(complete_stage_rows):
            for actor_position, asset in stage_assets:
                root = sexlab_actor_root_from_path(asset.packaged_path)
                actor_root_votes[actor_position][root] = actor_root_votes[actor_position].get(root, 0) + 1
                actor_root_first_seen[actor_position].setdefault(root, row_index)

        chosen_actor_roots: Dict[int, str] = {}
        for actor_position in range(len(actor_indexes)):
            votes = actor_root_votes.get(actor_position) or {"character": 1}
            first_seen = actor_root_first_seen.get(actor_position) or {"character": 0}
            choices = sorted(votes, key=lambda root: (-votes[root], first_seen.get(root, 0), root))
            chosen = choices[0]
            chosen_actor_roots[actor_position] = chosen
            if len(choices) > 1:
                warnings.append(
                    f"{scene.raw_id}: actor {actor_position + 1} uses multiple actor roots in source stages "
                    f"({', '.join(choices)}); using dominant root '{chosen}' and skipping mismatched stages."
                )

        role_inference = infer_sexlab_roles_for_export(scene, chosen_actor_roots)
        warnings.extend(role_inference.warnings)
        style_report["warnings"].extend(role_inference.warnings)
        if role_inference.changed:
            style_report["actorOrderChangedCount"] += 1
            warnings.append(
                f"{scene.raw_id}: reordered actors for SexLab-native MF output "
                f"({','.join(str(index + 1) for index in role_inference.actor_order)})."
            )
        if role_inference.confidence == "low":
            style_report["ambiguousActorRoleCount"] += 1
        style_report["actorRoleRows"].append(
            {
                "scene": scene.raw_id or scene.scene_id or scene.name,
                "actorOrder": [index + 1 for index in role_inference.actor_order],
                "actorTypes": role_inference.actor_types,
                "confidence": role_inference.confidence,
                "reason": role_inference.reason,
                "changed": role_inference.changed,
            }
        )

        actor_order = role_inference.actor_order
        actor_stage_ids: Dict[int, List[Dict[str, Any]]] = {index: [] for index in range(len(actor_order))}
        actor_roots: Dict[int, List[str]] = {index: [] for index in range(len(actor_order))}
        entries_by_actor: Dict[int, List[HkxAsset]] = {index: [] for index in range(len(actor_order))}
        stage_params: List[Dict[str, Any]] = []

        for speed, stage_assets in complete_stage_rows:
            root_mismatches = [
                f"actor {actor_position + 1}: {sexlab_actor_root_from_path(asset.packaged_path)}"
                for actor_position, asset in stage_assets
                if sexlab_actor_root_from_path(asset.packaged_path) != chosen_actor_roots.get(actor_position, "character")
            ]
            if root_mismatches:
                warnings.append(
                    f"{scene.raw_id}: skipped SexLab stage '{speed.animation}' because actor root(s) changed from the "
                    f"chosen animation setup: {summarize_values(root_mismatches)}."
                )
                continue
            stage_number = len(stage_params) + 1
            stage_assets_by_actor = {actor_position: asset for actor_position, asset in stage_assets}
            for sexlab_actor_position, source_actor_position in enumerate(actor_order):
                asset = stage_assets_by_actor.get(source_actor_position)
                if asset is None:
                    continue
                sexlab_event = f"{animation_id}_A{sexlab_actor_position + 1}_S{stage_number}"
                anim_root = actor_animation_root_from_packaged_path(asset.packaged_path) or ANIMATION_ROOT_REL
                target_rel = anim_root / safe_pack / f"{sexlab_event}.hkx"
                export_asset = HkxAsset(
                    source=asset.source,
                    data_path=target_rel,
                    packaged_path=target_rel,
                    event_name=sexlab_event,
                )
                export_assets.append(export_asset)
                entries_by_actor[sexlab_actor_position].append(export_asset)
                actor_stage_node: Dict[str, Any] = {"id": sexlab_event}
                actor = scene.actors[source_actor_position] if source_actor_position < len(scene.actors) else Actor()
                actor_type = (
                    role_inference.actor_types[sexlab_actor_position]
                    if sexlab_actor_position < len(role_inference.actor_types)
                    else sexlab_actor_type(actor, sexlab_actor_position, chosen_actor_roots.get(source_actor_position, "character"))
                )
                if "silent" in {tag.lower() for tag in actor.tags}:
                    actor_stage_node["silent"] = True
                sos_value = sexlab_sos_value_for_stage(scene, actor, actor_type)
                if sos_value:
                    actor_stage_node["sos"] = sos_value
                    style_report["sosMetadataCount"] += 1
                if actor.feet_on_ground is False and not actor_type.startswith("Creature"):
                    actor_stage_node["animvars"] = {"AVbHumanoidFootIKDisable": 1}
                if sexlab_actor_stage_has_specific_params(actor_stage_node):
                    style_report["actorSpecificStageParamCount"] += 1
                actor_stage_ids[sexlab_actor_position].append(actor_stage_node)
                actor_roots[sexlab_actor_position].append(sexlab_actor_root_from_path(target_rel))

            stage_params.append(
                {
                    "number": stage_number,
                    "_sourceSound": speed.sexlab_sound,
                }
            )

        if not stage_params:
            warnings.append(f"{scene.raw_id}: skipped for SexLab export because no stages matched a stable actor-root setup.")
            continue

        actor_data: List[Dict[str, Any]] = []
        actor_types: List[str] = []
        cum_value = sexlab_cum_value_for_scene(scene)
        cum_target_actor = -1
        if cum_value and "Male" in role_inference.actor_types and "Female" in role_inference.actor_types:
            cum_target_actor = role_inference.actor_types.index("Female")
        for sexlab_actor_position, source_actor_position in enumerate(actor_order):
            roots = sorted(set(actor_roots.get(sexlab_actor_position) or ["character"]))
            actor_root = roots[0]
            if len(roots) > 1:
                warnings.append(
                    f"{scene.raw_id}: actor {sexlab_actor_position + 1} used multiple actor roots in SexLab export; using {actor_root}."
                )
            actor = scene.actors[source_actor_position] if source_actor_position < len(scene.actors) else Actor()
            actor_type = (
                role_inference.actor_types[sexlab_actor_position]
                if sexlab_actor_position < len(role_inference.actor_types)
                else sexlab_actor_type(actor, sexlab_actor_position, actor_root)
            )
            actor_types.append(actor_type)
            actor_node: Dict[str, Any] = {
                "type": actor_type,
                "stages": actor_stage_ids[sexlab_actor_position],
            }
            if actor.sexlab_sex_flags:
                actor_node["_slsbSex"] = dict(actor.sexlab_sex_flags)
            elif "futa" in {tag.lower() for tag in actor.tags} and not actor_type.startswith("Creature"):
                actor_node["_slsbSex"] = {
                    "male": actor_type == "Male",
                    "female": actor_type == "Female",
                    "futa": True,
                }
            if "strapon" in {tag.lower() for tag in actor.tags}:
                actor_node["strap_on"] = True
            if sexlab_actor_position == cum_target_actor:
                actor_node["add_cum"] = cum_value
                style_report["cumMetadataCount"] += 1
            if actor_type.startswith("Creature"):
                race = sexlab_creature_race_for_actor(actor, actor_root)
                if race:
                    actor_node["race"] = race
                else:
                    warnings.append(
                        f"{scene.raw_id}: actor {sexlab_actor_position + 1} uses creature root '{actor_root}', "
                        "but no SexLab race name is known for it."
                    )
            actor_data.append(actor_node)

        tags = add_sexlab_discovery_tags(clean_sexlab_tags(sexlab_tags_for_scene(scene, actor_types)), pack, sexlab_discovery_tags)
        sound = sexlab_sound_for_scene(scene, tags)
        if normalize_sexlab_sound(sound, SEXLAB_NO_SOUND) != SEXLAB_NO_SOUND:
            style_report["animationLevelSoundCount"] += 1
        for stage in stage_params:
            source_stage_sound = str(stage.pop("_sourceSound", "") or "")
            if source_stage_sound:
                stage_sound = sexlab_stage_sound_for_scene(
                    scene,
                    int(stage.get("number") or 1),
                    len(stage_params),
                    sound,
                    source_stage_sound,
                )
                if normalize_sexlab_sound(stage_sound, SEXLAB_NO_SOUND) != normalize_sexlab_sound(sound, SEXLAB_NO_SOUND):
                    stage["sound"] = stage_sound
                    style_report["stageLevelSoundOverrideCount"] += 1
                else:
                    style_report["redundantStageSoundRemovedCount"] += 1
        animation: Dict[str, Any] = {
            "id": animation_id,
            "name": scene.name or scene.raw_id or animation_id,
            "tags": ",".join(tags),
            "sound": sound,
            "actors": actor_data,
            "stages": stage_params,
        }
        style_report["tagRows"].append({"animation": animation_id, "tags": tags})
        furniture_type = canonical_ostim_furniture_type(scene.furniture)
        if furniture_type:
            animation["furniture"] = furniture_type
        creature_races = [str(actor.get("race")) for actor in actor_data if actor.get("race")]
        if creature_races:
            animation["creature_race"] = creature_races[0]
        animations.append(animation)

        for _actor_position, actor_entries in entries_by_actor.items():
            if not actor_entries:
                continue
            grouped_actor_entries: Dict[PurePosixPath, List[HkxAsset]] = {}
            for entry in actor_entries:
                actor_root = sexlab_actor_root_from_path(entry.packaged_path)
                anim_dir = (actor_animation_root_from_packaged_path(entry.packaged_path) or ANIMATION_ROOT_REL) / safe_pack
                list_rel = anim_dir / sexlab_fnis_list_name(pack, actor_root)
                grouped_actor_entries.setdefault(list_rel, []).append(entry)
            for list_rel, grouped_entries in sorted(grouped_actor_entries.items(), key=lambda item: item[0].as_posix().lower()):
                lines = fnis_lines_by_path.setdefault(list_rel, ["Version V1.0"])
                lines.append("")
                lines.append(f"' {animation_id}")
                for index, entry in enumerate(grouped_entries):
                    prefix = "s" if index == 0 else "+"
                    event_key = entry.event_name.lower()
                    if event_key in registered_fnis_events:
                        style_report["fnisDuplicateEventCount"] += 1
                        duplicate_rows = style_report.setdefault("fnisDuplicateEvents", [])
                        if isinstance(duplicate_rows, list) and len(duplicate_rows) < 200:
                            duplicate_rows.append(entry.event_name)
                    registered_fnis_events.add(event_key)
                    lines.append(f"{prefix} {entry.event_name} {entry.packaged_path.name}")

    return animations, export_assets, fnis_lines_by_path, warnings, style_report


def public_sexlab_animation_payload(animations: Sequence[Dict[str, Any]]) -> List[Dict[str, Any]]:
    payload = copy.deepcopy(list(animations))
    for animation in payload:
        for actor in animation.get("actors") or []:
            if not isinstance(actor, dict):
                continue
            for key in [key for key in actor if str(key).startswith("_")]:
                actor.pop(key, None)
    return payload


def sexlab_conversion_report_text(report: Dict[str, Any]) -> str:
    report = dict_or_empty(report)
    title = "SexLab P+/SLSB Conversion Report" if report.get("sexlabPlusExport") else "SexLab/SLAL Conversion Report"
    lines = [
        title,
        "=" * len(title),
        f"Status: {report.get('status')}",
        f"Converter version: {report.get('converterVersion')}",
        f"Target: {report.get('target')}",
        f"Pack: {report.get('pack')}",
        f"Source archive: {report.get('sourceArchiveName') or report.get('sourceArchive') or 'unknown'}",
        f"Detected source type: {report.get('selectedSourceTypeLabel') or 'not recorded'}",
        f"Animations: {report.get('animationCount')}",
        f"Stages: {report.get('stageCount')}",
        f"Actors: {report.get('actorCount')}",
        f"Furniture animations: {report.get('furnitureAnimationCount')}",
        f"Creature animations: {report.get('creatureAnimationCount')}",
        f"Creature actor roots: {', '.join(report.get('creatureActorRoots') or []) or 'none'}",
        f"SexLab SFX profiles: {report.get('soundProfileCount')}",
        f"SexLab stage SFX entries: {report.get('stageSoundEntryCount')}",
        f"NoSound stage entries: {report.get('noSoundStageEntryCount')}",
        f"Stage timer entries: {report.get('timerEntryCount', 0)}",
        f"Actor-specific stage params: {report.get('actorSpecificStageParamCount', 0)}",
        f"SFX fallback action: {report.get('sfxFallbackAction') or 'disabled'}",
        f"SexLab discovery tags: {', '.join(report.get('sexlabDiscoveryTags') or []) or 'disabled'}",
        f"HKX files: {report.get('hkxCount')}",
        f"Behavior graph HKX files: {report.get('behaviorGraphHkxCount', 0)}",
        f"SLAL JSON files: {report.get('slalJsonFileCount')}",
        f"SLAL source files: {report.get('slalSourceFileCount')}",
        f"SexLab P+ export: {report.get('sexlabPlusExport')}",
        f"SLSB source files: {report.get('slsbSourceFileCount')}",
        f"SexLab P+ compiled registry files: {report.get('sexlabPlusCompiledRegistryCount')}",
        f"Ready for SexLab P+ runtime: {report.get('readyForSexLabPlusRuntime')}",
        f"FNIS animation lists: {report.get('fnisListCount')}",
        f"Pandora registration mode: {report.get('pandoraRegistrationMode') or 'not recorded'}",
        f"Pandora patch-list entry expected: {public_bool(report.get('pandoraPatchListEntryExpected'))}",
        f"Pandora expected FNIS Mod names: {', '.join(report.get('pandoraExpectedFnisModNames') or []) or 'none'}",
    ]
    style = report.get("sexLabExportStyle") if isinstance(report.get("sexLabExportStyle"), dict) else {}
    if style:
        lines.append("SexLab Export Style:")
        lines.extend(
            [
                f"- SexLab-native source style: {style.get('sexLabNativeSourceStyle')}",
                f"- Actor order changed: {style.get('actorOrderChangedCount', 0)}",
                f"- Ambiguous actor-role scenes: {style.get('ambiguousActorRoleCount', 0)}",
                f"- Discovery tags enabled: {style.get('discoveryTagsEnabled')}",
                f"- Animation-level sounds: {style.get('animationLevelSoundCount', 0)}",
                f"- Stage-level sound overrides: {style.get('stageLevelSoundOverrideCount', 0)}",
                f"- Redundant stage sounds removed: {style.get('redundantStageSoundRemovedCount', 0)}",
                f"- Timers emitted: {style.get('timerEmissionCount', 0)}",
                f"- Actor-specific params emitted: {style.get('actorSpecificStageParamCount', 0)}",
                f"- Cum metadata inferred: {style.get('cumMetadataCount', 0)}",
                f"- SOS metadata inferred: {style.get('sosMetadataCount', 0)}",
                f"- Invalid/internal scenes skipped: {style.get('skippedInvalidSceneCount', 0)}",
                f"- Duplicate FNIS events generated: {style.get('fnisDuplicateEventCount', 0)}",
            ]
        )
    quality = report.get("sexLabSourceFnisQuality") if isinstance(report.get("sexLabSourceFnisQuality"), dict) else {}
    if quality:
        lines.append("SexLab Source/FNIS Quality:")
        lines.extend(
            [
                f"- SLAnim source path: {quality.get('sourcePath') or 'not recorded'}",
                f"- FNIS list paths: {', '.join(quality.get('fnisPaths') or []) or 'not recorded'}",
                f"- anim_id_prefix emitted: {quality.get('animIdPrefix') or 'none'}",
                f"- anim_name_prefix emitted: {quality.get('animNamePrefix') or 'none'}",
                f"- Animation IDs stripped for source: {quality.get('animationIdsStrippedCount', 0)}",
                f"- Double-prefix risks fixed: {quality.get('doublePrefixRiskFixedCount', 0)}",
                f"- common_tags: {', '.join(quality.get('commonTags') or []) or 'none'}",
                f"- Discovery enabled: {quality.get('discoveryTagsEnabled')}",
                f"- Common tag overlap removed: {quality.get('commonTagOverlapRemovedCount', 0)}",
                f"- Actor declarations duplicated: {quality.get('duplicateActorDeclarationRiskCount', 0)}",
                f"- Animvars normalized: {quality.get('animvarNormalizedCount', 0)}",
                f"- Actor stage params collapsed: {quality.get('actorStageParamCollapsedCount', 0)}",
                f"- SOS repeats collapsed: {quality.get('sosCollapsedCount', 0)}",
                f"- Invalid/internal scenes skipped: {quality.get('skippedInvalidSceneCount', 0)}",
                f"- Duplicate FNIS events: {quality.get('fnisDuplicateEventCount', 0)}",
            ]
        )
    warnings = report.get("warnings") or []
    if warnings:
        lines.append("Warnings:")
        grouped = report.get("warningSeverityGroups") or warnings_by_severity(warnings)
        for severity in ("high", "medium", "low"):
            lines.extend(f"- [{severity.upper()}] {warning}" for warning in grouped.get(severity, []))
    lines.extend(
        [
            "Deploy Notes:",
            "- Install this ZIP with a mod manager.",
            "- Run GenerateFNISforUsers, Nemesis, or Pandora after installing so the FNIS animation list and behavior graph hooks are registered.",
            "- Pandora auto-discovers the FNIS_*_List.txt file; this SexLab export is not expected to appear as a selectable Pandora patch.",
            "- In Pandora Engine.log, confirm an 'FNIS Mod' entry matches the expected FNIS Mod name shown above.",
            "- In game, open SexLab Animation Loader and register/enable the generated pack.",
            "- If SexLab P+ export is true, the ZIP includes a compiled .slr registry plus editable SLSB source.",
            "- If SexLab P+ export is false, use the app checkbox to generate a native P+ .slr registry.",
        ]
    )
    if report.get("recommendedUserAction"):
        lines.append(f"- {report.get('recommendedUserAction')}")
    return "\n".join(lines) + "\n"


def sexlab_export_conversion_warnings(warnings: Sequence[str]) -> List[str]:
    rewritten: List[str] = []
    for warning in warnings:
        if warning.startswith("Source HKX files were found under non-character actor root(s):"):
            roots = warning.split(":", 1)[1].strip() if ":" in warning else "creature"
            roots = roots.split(" Creature animation roots", 1)[0].strip().rstrip(".")
            rewritten.append(
                f"Source HKX files were found under creature actor root(s): {roots}. "
                "SexLab creature exports require FNIS Creature Pack, matching creature assets, and creature-capable behavior generation."
            )
            continue
        if warning.startswith("Added converter SFX fallback actions"):
            rewritten.append(
                warning.replace(
                    "so OStim voice/moan sounds can play",
                    "so SexLab/SLAL exports receive fallback sound metadata",
                )
            )
            continue
        rewritten.append(warning)
    return rewritten


def make_sexlab_ready_zip(
    zip_path: Path,
    pack: str,
    scenes: Sequence[Scene],
    hkx_assets: Sequence[HkxAsset],
    source_archive: Optional[Path] = None,
    conversion_warnings: Optional[Sequence[str]] = None,
    mod_author: Optional[str] = None,
    sfx_fallback_action: Optional[str] = None,
    sexlab_plus: bool = False,
    sexlab_discovery_tags: bool = DEFAULT_SEXLAB_DISCOVERY_TAGS_ENABLED,
    behavior_graphs: Optional[Sequence[BehaviorGraphAsset]] = None,
    source_detection: Optional[Dict[str, Any]] = None,
    conversion_diagnostics: Optional[Dict[str, Any]] = None,
) -> Tuple[Path, Dict[str, Any], List[HkxAsset], List[str]]:
    zip_path.parent.mkdir(parents=True, exist_ok=True)
    safe_pack = safe_pack_folder(pack)
    fallback_action = normalize_sfx_fallback_action_type(sfx_fallback_action)
    discovery_tags = sexlab_discovery_tags_for_pack(pack) if sexlab_discovery_tags else []
    animations, export_assets, fnis_lines_by_path, export_warnings, sexlab_style_report = build_sexlab_export(
        scenes,
        hkx_assets,
        pack,
        sexlab_discovery_tags=sexlab_discovery_tags,
    )
    warnings = [*sexlab_export_conversion_warnings(conversion_warnings or []), *export_warnings]
    if not animations:
        raise RuntimeError("No SexLab/SLAL animations could be built from the converted scenes.")
    if not export_assets:
        raise RuntimeError("No HKX animation files were available for SexLab/SLAL export.")

    temp_data = make_converter_temp_dir("sexlab_package_", zip_path)
    data_root = temp_data / "Data"
    json_rel = SLANIMS_JSON_REL / f"{safe_pack}.json"
    source_rel = SLANIMS_SOURCE_REL / f"{safe_pack}.txt"
    json_path = data_root / Path(*json_rel.parts)
    source_path = data_root / Path(*source_rel.parts)
    json_path.parent.mkdir(parents=True, exist_ok=True)
    source_path.parent.mkdir(parents=True, exist_ok=True)
    slal_json = {
        "name": pack,
        "author": normalized_mod_author(mod_author),
        "animations": public_sexlab_animation_payload(animations),
    }
    json_path.write_text(json.dumps(slal_json, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    source_text, sexlab_source_quality = build_sexlab_source_text_and_quality(pack, animations, discovery_tags)
    source_path.write_text(source_text, encoding="utf-8")
    slsb_source_rel: Optional[PurePosixPath] = None
    slsb_registry_rel: Optional[PurePosixPath] = None
    slsb_source_file_count = 0
    slsb_registry_file_count = 0
    slsb_fnis_lines_by_path: Dict[PurePosixPath, List[str]] = {}
    if sexlab_plus:
        slsb_source_rel = SLSB_SOURCE_REL / f"{safe_pack}.slsb.json"
        slsb_registry_rel = SLSB_REGISTRY_REL / f"{safe_pack}.slr"
        slsb_source = build_slsb_source(pack, mod_author, animations)
        slsb_source_path = data_root / Path(*slsb_source_rel.parts)
        slsb_source_path.parent.mkdir(parents=True, exist_ok=True)
        slsb_source_path.write_text(json.dumps(slsb_source, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        slsb_source_file_count = 1
        registry_bytes, registry_warnings = build_slsb_registry_bytes(slsb_source)
        warnings.extend(registry_warnings)
        slsb_registry_path = data_root / Path(*slsb_registry_rel.parts)
        slsb_registry_path.parent.mkdir(parents=True, exist_ok=True)
        slsb_registry_path.write_bytes(registry_bytes)
        slsb_registry_file_count = 1
        slsb_fnis_lines_by_path, slsb_fnis_warnings = build_slsb_fnis_lines(slsb_source, safe_pack)
        warnings.extend(slsb_fnis_warnings)

    copied_targets: set[PurePosixPath] = set()
    for asset in export_assets:
        if asset.packaged_path in copied_targets:
            continue
        copied_targets.add(asset.packaged_path)
        target = data_root / Path(*asset.packaged_path.parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(asset.source, target)

    if sexlab_plus and slsb_fnis_lines_by_path:
        fnis_lines_by_path = merge_fnis_line_sets(fnis_lines_by_path, slsb_fnis_lines_by_path)

    sexlab_source_quality["sourcePath"] = source_rel.as_posix()
    sexlab_source_quality["fnisPaths"] = [path.as_posix() for path in sorted(fnis_lines_by_path)]
    sexlab_source_quality["skippedInvalidSceneCount"] = sexlab_style_report.get("skippedInvalidSceneCount", 0)
    sexlab_source_quality["skippedInvalidScenes"] = sexlab_style_report.get("skippedInvalidScenes", [])
    sexlab_source_quality["fnisDuplicateEventCount"] = sexlab_style_report.get("fnisDuplicateEventCount", 0)
    sexlab_source_quality["fnisDuplicateEvents"] = sexlab_style_report.get("fnisDuplicateEvents", [])
    sexlab_style_report["sourceQuality"] = sexlab_source_quality

    copied_behavior_graphs = copy_behavior_graph_assets(
        data_root,
        sexlab_behavior_graph_assets_for_fnis_lists(behavior_graphs or [], fnis_lines_by_path),
    )

    for list_rel, lines in fnis_lines_by_path.items():
        write_lines(data_root / Path(*list_rel.parts), lines)

    stage_count = sum(len(animation.get("stages") or []) for animation in animations)
    actor_count = sum(len(animation.get("actors") or []) for animation in animations)
    furniture_animation_count = sum(
        1
        for animation in animations
        if animation.get("furniture")
        or any(compact_path_part(tag) == "furniture" for tag in split_tags(str(animation.get("tags") or "")))
    )
    sound_profile_count = sum(
        1
        for animation in animations
        if normalize_sexlab_sound(str(animation.get("sound") or ""), SEXLAB_NO_SOUND) != SEXLAB_NO_SOUND
    )
    stage_sound_entry_count = sum(
        1
        for animation in animations
        for stage in animation.get("stages") or []
        if isinstance(stage, dict) and stage.get("sound") is not None
    )
    no_sound_stage_entry_count = sum(
        1
        for animation in animations
        for stage in animation.get("stages") or []
        if isinstance(stage, dict)
        and stage.get("sound") is not None
        and normalize_sexlab_sound(str(stage.get("sound") or ""), SEXLAB_NO_SOUND) == SEXLAB_NO_SOUND
    )
    timer_entry_count = sum(
        1
        for animation in animations
        for stage in animation.get("stages") or []
        if isinstance(stage, dict) and stage.get("timer") is not None
    )
    actor_specific_stage_param_count = sum(
        1
        for animation in animations
        for actor in animation.get("actors") or []
        if isinstance(actor, dict)
        for stage in actor.get("stages") or []
        if isinstance(stage, dict) and sexlab_actor_stage_has_specific_params(stage)
    )
    creature_animation_count = sum(
        1
        for animation in animations
        if animation.get("creature_race")
        or any(str(actor.get("type", "")).startswith("Creature") for actor in animation.get("actors") or [] if isinstance(actor, dict))
    )
    creature_actor_roots = sorted(
        {
            root
            for asset in export_assets
            for root in [hkx_actor_root(asset.packaged_path)]
            if root and root.lower() != "character"
        },
        key=str.lower,
    )
    report: Dict[str, Any] = {
        "target": "SexLab P+/SLSB" if sexlab_plus else "SexLab/SLAL",
        "pack": pack,
        "sourceArchive": source_archive.name if source_archive else None,
        "sourceArchiveFingerprint": source_archive_fingerprint(source_archive),
        "author": normalized_mod_author(mod_author),
        "animationCount": len(animations),
        "stageCount": stage_count,
        "actorCount": actor_count,
        "furnitureAnimationCount": furniture_animation_count,
        "creatureAnimationCount": creature_animation_count,
        "creatureActorRoots": creature_actor_roots,
        "soundProfileCount": sound_profile_count,
        "stageSoundEntryCount": stage_sound_entry_count,
        "noSoundStageEntryCount": no_sound_stage_entry_count,
        "timerEntryCount": timer_entry_count,
        "actorSpecificStageParamCount": actor_specific_stage_param_count,
        "usesSexLabSfx": sound_profile_count > 0 or stage_sound_entry_count > no_sound_stage_entry_count,
        "usesConverterSfxFallback": uses_sfx_fallback_action(scenes, fallback_action),
        "sfxFallbackAction": fallback_action or None,
        "sexlabDiscoveryTagsEnabled": sexlab_discovery_tags,
        "sexlabDiscoveryTags": discovery_tags,
        "sexlabDiscoveryTagCount": len(discovery_tags),
        "sexLabExportStyle": sexlab_style_report,
        "sexLabSourceFnisQuality": sexlab_source_quality,
        "sexLabNativeSourceStyle": bool(sexlab_style_report.get("sexLabNativeSourceStyle")),
        "sexLabActorOrderChangedCount": sexlab_style_report.get("actorOrderChangedCount", 0),
        "sexLabAmbiguousActorRoleCount": sexlab_style_report.get("ambiguousActorRoleCount", 0),
        "sexLabRedundantStageSoundRemovedCount": sexlab_style_report.get("redundantStageSoundRemovedCount", 0),
        "sexLabStageLevelSoundOverrideCount": sexlab_style_report.get("stageLevelSoundOverrideCount", 0),
        "sexLabCumMetadataCount": sexlab_style_report.get("cumMetadataCount", 0),
        "sexLabSosMetadataCount": sexlab_style_report.get("sosMetadataCount", 0),
        "sexLabSkippedInvalidSceneCount": sexlab_style_report.get("skippedInvalidSceneCount", 0),
        "sexLabFnisDuplicateEventCount": sexlab_style_report.get("fnisDuplicateEventCount", 0),
        "requiresCreatureSupport": creature_animation_count > 0,
        "creatureSupportRequirements": ["FNIS Creature Pack", "matching creature assets", "creature-capable behavior generation"] if creature_animation_count > 0 else [],
        "hkxCount": len(copied_targets),
        "legacyHkxConversion": dict_or_empty(
            conversion_diagnostics.get("legacyHkxConversion") if isinstance(conversion_diagnostics, dict) else None
        ),
        "behaviorGraphHkxCount": len(copied_behavior_graphs),
        "behaviorGraphFiles": [
            data_path_text(PurePosixPath(*path.relative_to(data_root).parts))
            for path in sorted(copied_behavior_graphs, key=lambda item: str(item).lower())
        ],
        **sexlab_pandora_registration_details(sorted(fnis_lines_by_path)),
        "pandoraOutputGenerated": False,
        "nemesisOutputGenerated": bool(copied_behavior_graphs),
        "fnisStyleAnimationListGenerated": bool(fnis_lines_by_path),
        "nemesisCheckboxRequired": False,
        "nemesisSafeOutput": True,
        "recommendedBehaviorTool": (
            "Pandora, Nemesis, or FNIS can automatically read the generated FNIS-style lists. "
            "No Pandora patch-list checkbox is expected; register or enable the pack in SexLab after behavior generation."
        ),
        "slalJsonFileCount": 1,
        "slalSourceFileCount": 1,
        "sexlabPlusExport": sexlab_plus,
        "slsbSourceFileCount": slsb_source_file_count,
        "sexlabPlusCompiledRegistryCount": slsb_registry_file_count,
        "requiresSexLabPlusCompilation": False,
        "readyForSexLabPlusRuntime": bool(sexlab_plus and slsb_registry_file_count > 0),
        "sexLabPlusPrefixHash": slsb_hash_id("prefix", pack, length=4) if sexlab_plus else None,
        "fnisListCount": len(fnis_lines_by_path),
        "paths": {
            "json": json_rel.as_posix(),
            "source": source_rel.as_posix(),
            "animationFolder": f"{(ANIMATION_ROOT_REL / safe_pack).as_posix()}/",
            "fnisLists": [path.as_posix() for path in sorted(fnis_lines_by_path)],
        },
        "warnings": warnings,
    }
    report = finalize_conversion_report(
        report,
        "SexLab P+/SLSB" if sexlab_plus else "SexLab/SLAL",
        source_detection=source_detection,
    )
    if slsb_source_rel:
        report["paths"]["slsbSource"] = slsb_source_rel.as_posix()
    if slsb_registry_rel:
        report["paths"]["sexlabPlusRegistry"] = slsb_registry_rel.as_posix()

    readme = textwrap.dedent(
        f"""\
        {APP_NAME} - {"SexLab P+/SLSB export" if sexlab_plus else "SexLab/SLAL export"}
        Pack: {pack}

        Install this ZIP with your mod manager. The archive root contains the Skyrim Data folders directly.
        Run GenerateFNISforUsers, Nemesis, or Pandora after installing.
        Pandora auto-discovers the generated FNIS_*_List.txt file. This SexLab export is not a selectable Pandora patch, so no converted-pack checkbox is expected.
        To confirm Pandora recognized it, open Engine.log after a completed run and look for an "FNIS Mod" entry matching: {", ".join(sexlab_pandora_registration_details(sorted(fnis_lines_by_path))["pandoraExpectedFnisModNames"]) or "the generated FNIS list"}.
        In game, open SexLab Animation Loader and register or enable this pack if you are using classic SLAL.

        Contents:
        - {json_rel.as_posix()}
        - {source_rel.as_posix()}
        - meshes/actors/*/animations/{safe_pack}/
        - meshes/actors/*/behaviors/FNIS_*_Behavior.hkx
        {f"- {slsb_source_rel.as_posix()}" if slsb_source_rel else ""}
        {f"- {slsb_registry_rel.as_posix()}" if slsb_registry_rel else ""}

        {"SexLab P+ is supported by the included compiled .slr registry and SLSB source project. The SLAL JSON/source are kept for compatibility and inspection." if sexlab_plus else "Note: This is a SLAL-style SexLab export. Check SexLab P+ export in the app if you need a native .slr registry."}
        """
    )
    try:
        (temp_data / "README_SexLab_SLAL.txt").write_text(readme, encoding="utf-8")
        (temp_data / "sexlab_conversion_report.json").write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
        (temp_data / "sexlab_conversion_report.txt").write_text(sexlab_conversion_report_text(report), encoding="utf-8")
        (temp_data / "conversion_report_README.txt").write_text(conversion_report_readme_text(report), encoding="utf-8")
        (temp_data / AAC_README_FILE).write_text(aac_readme_text(report), encoding="utf-8")
        (temp_data / AAC_MANIFEST_FILE).write_text(json.dumps(aac_manifest_for_report(report), indent=2, ensure_ascii=False), encoding="utf-8")

        with ZipFile(zip_path, "w", compression=ZIP_DEFLATED) as zf:
            add_ready_package_to_zip(zf, temp_data, data_root)
        return zip_path, report, export_assets, warnings
    finally:
        cleanup_converter_temp_dir(temp_data)


def make_ready_to_install_zip(
    zip_path: Path,
    generated_scenes_root: Path,
    pack: str,
    alignment_path: Optional[Path] = None,
    hkx_assets: Optional[Sequence[HkxAsset]] = None,
    scenes: Optional[Sequence[Scene]] = None,
    source_archive: Optional[Path] = None,
    conversion_warnings: Optional[Sequence[str]] = None,
    mod_author: Optional[str] = None,
    sfx_fallback_action: Optional[str] = None,
    ostim_action_files: Optional[Sequence[Path]] = None,
    ostim_furniture_type_files: Optional[Sequence[Path]] = None,
    behavior_graphs: Optional[Sequence[BehaviorGraphAsset]] = None,
    source_engine_mods: Optional[Sequence[EngineModAsset]] = None,
    source_detection: Optional[Dict[str, Any]] = None,
    ostim_menu_entry_requested: bool = False,
    conversion_diagnostics: Optional[Dict[str, Any]] = None,
    nemesis_safe_output: bool = DEFAULT_NEMESIS_SAFE_OUTPUT,
) -> Path:
    requested_obsolete_pandora_output = not bool(nemesis_safe_output)
    # Pandora 4.x reads generated ATT/Nemesis patches and FNIS creature lists,
    # but ignores animationdata/animationsetdata placed in Pandora mod folders.
    # Keep the old argument for settings/CLI compatibility while always emitting
    # the registration format that Pandora actually assembles.
    nemesis_safe_output = True
    conversion_warnings = list(conversion_warnings or [])
    if requested_obsolete_pandora_output:
        conversion_warnings.append(
            "The obsolete Pandora animationdata/animationsetdata output setting was ignored. "
            "A Pandora-compatible ATT/Nemesis behavior patch was generated instead."
        )
    fallback_action = normalize_sfx_fallback_action_type(sfx_fallback_action)
    zip_path.parent.mkdir(parents=True, exist_ok=True)
    safe_pack = safe_pack_folder(pack)
    pack_dir = scene_output_folder(generated_scenes_root, pack)
    creature_pack_dir = generated_scenes_root / "OCreatures" / safe_pack
    if not pack_dir.exists() and not creature_pack_dir.exists():
        raise FileNotFoundError(f"Expected scenes at {pack_dir} or {creature_pack_dir}")

    temp_data = make_converter_temp_dir("ostim_sa_package_", zip_path)
    data_root = temp_data / "Data"
    behavior_code = safe_behavior_mod_code(pack)
    if pack_dir.exists():
        scenes_dst = data_root / Path(*(SCENES_REL / safe_pack).parts)
        shutil.copytree(pack_dir, scenes_dst, dirs_exist_ok=True)
    ocreatures_generated_root = generated_scenes_root / "OCreatures"
    if ocreatures_generated_root.exists():
        creature_scenes_dst = data_root / Path(*OCREATURES_SCENES_REL.parts)
        shutil.copytree(ocreatures_generated_root, creature_scenes_dst, dirs_exist_ok=True)

    assets = list(hkx_assets or [])
    source_engine_mods_to_copy = filter_ostimsa_source_engine_mods(source_engine_mods or [])
    copied_source_engine_mod_files = copy_engine_mod_assets(data_root, source_engine_mods_to_copy)
    copied_action_files = copy_ostim_action_files(data_root, ostim_action_files or [])
    copied_furniture_type_files = copy_ostim_furniture_type_files(data_root, ostim_furniture_type_files or [])
    copied_behavior_graphs: List[Path] = []
    animation_list_paths: List[Path] = []
    att_animation_list_paths: List[Path] = []
    generated_nemesis_patch_files: List[Path] = []
    if assets:
        copy_hkx_assets(data_root, assets)
        character_assets = character_hkx_assets(assets)
        creature_assets = creature_hkx_assets(assets)
        animation_list_paths = generate_animation_list(
            data_root,
            pack,
            creature_assets,
            scenes=scenes,
            behavior_graphs=behavior_graphs,
        )
        animation_list_rels = [
            PurePosixPath(*path.relative_to(data_root).parts)
            for path in animation_list_paths
            if path.is_relative_to(data_root)
        ]
        copied_behavior_graphs = copy_behavior_graph_assets(
            data_root,
            behavior_graph_assets_for_fnis_list_paths(behavior_graphs or [], animation_list_rels, include_all_source=False),
        )
        copied_real_nemesis_patch = copied_files_include_real_nemesis_patch(data_root, copied_source_engine_mod_files)
        if character_assets and not copied_real_nemesis_patch:
            generated_nemesis_patch_files, att_animation_list_paths = write_generated_att_nemesis_patch(
                data_root,
                pack,
                character_assets,
                scenes=scenes,
                mod_author=mod_author,
            )
        elif character_assets and copied_real_nemesis_patch:
            source_patch_code = first_nemesis_mod_code_from_files(data_root, copied_source_engine_mod_files)
            source_playback_var = source_nemesis_playback_variable(data_root, copied_source_engine_mod_files)
            att_animation_list_paths = generate_att_animation_lists(
                data_root,
                pack,
                collect_att_patch_animations(pack, character_assets, scenes),
                list_code=source_patch_code or safe_behavior_mod_code(pack),
                playback_var=source_playback_var,
                playback_speed_by_event=scene_playback_speed_by_actor_event(scenes),
            )
    generated_fallback_action_file = uses_generated_sfx_action_file(scenes, fallback_action)
    if generated_fallback_action_file:
        write_converter_sfx_action(data_root, fallback_action)

    action_content_paths: List[str] = []
    if generated_fallback_action_file:
        action_content_paths.append(f"Data/{ACTIONS_REL}/{fallback_action}.json")
    for copied_action in copied_action_files:
        try:
            rel = copied_action.relative_to(data_root)
            action_content_paths.append("Data/" + PurePosixPath(*rel.parts).as_posix())
        except ValueError:
            action_content_paths.append(f"Data/{ACTIONS_REL}/{copied_action.name}")
    furniture_type_content_paths: List[str] = []
    for copied_furniture in copied_furniture_type_files:
        try:
            rel = copied_furniture.relative_to(data_root)
            furniture_type_content_paths.append("Data/" + PurePosixPath(*rel.parts).as_posix())
        except ValueError:
            furniture_type_content_paths.append(f"Data/{FURNITURE_TYPES_REL}/{copied_furniture.name}")
    action_contents_block = "\n".join(f"- {package_display_path(path)}" for path in sorted(set(action_content_paths)))
    furniture_contents_block = "\n".join(f"- {package_display_path(path)}" for path in sorted(set(furniture_type_content_paths)))
    human_filter = conversion_diagnostics.get("humanOnlyOStimFiltering") if isinstance(conversion_diagnostics, dict) and isinstance(conversion_diagnostics.get("humanOnlyOStimFiltering"), dict) else {}
    human_only_note = (
        f"Human-only OStim output: enabled. Creature/mixed creature scenes skipped: {human_filter.get('creatureScenesSkipped', 0)}."
        if human_filter.get("enabled")
        else "Human-only OStim output: disabled. Creature output, if present, requires a creature-capable setup."
    )
    behavior_runtime_note = (
        "Run Pandora after installing. Pandora consumes the generated Nemesis-compatible ATT patch "
        "and FNIS creature lists when building behavior output."
    )
    behavior_contents_block = (
        f"- Nemesis_Engine/mod/{safe_nemesis_patch_code(pack)}/0_master/ (Pandora-compatible ATT patch for human actor events, when needed)\n"
        f"- meshes/actors/character/animations/<pack>/ATT_{safe_nemesis_patch_code(pack)}_animlist.txt (human actor events, when needed)\n"
        "- meshes/actors/<creature>/animations/<pack>/FNIS_*_List.txt (creature events, when needed)"
    )
    readme = textwrap.dedent(
        f"""\
        OSex/OSex+/OpenSex/SexLab/FlowerGirls/legacy FNIS to OStim Standalone conversion
        Pack: {pack}

        Install this ZIP with your mod manager. The archive root contains the Skyrim Data folders directly.
        {behavior_runtime_note}
        {human_only_note}
        Creature scenes require OCreatures or another OStim creature extension, Creature Framework, matching creature assets, and creature behavior generation.

        Contents:
        - SKSE/Plugins/OStim/scenes/{safe_pack}/
        - SKSE/Plugins/OStim/scenes/OCreatures/{safe_pack}/ (creature scenes, when present)
        {action_contents_block}
        {furniture_contents_block}
        - meshes/actors/*/animations/<source pack folders>/
        - meshes/actors/*/behaviors/FNIS_*_Behavior.hkx (creature lists only, when needed)
        {behavior_contents_block}
        - {CONVERTER_METADATA_REL}/{safe_pack}/metadata.json
        """
    )
    try:
        (temp_data / "README_OStim_SA.txt").write_text(readme, encoding="utf-8")
        if alignment_path and alignment_path.exists():
            shutil.copy2(alignment_path, temp_data / "alignment.json")

        root_pandora_animdata_count = count_text_files(data_root / Path(*PANDORA_ANIMDATA_REL.parts))
        root_pandora_animset_count = count_text_files(data_root / Path(*PANDORA_ANIMSET_REL.parts))
        named_pandora_animdata_count = count_text_files(
            data_root / Path(*(PANDORA_MOD_REL / behavior_code / PANDORA_MOD_ANIMDATA_REL).parts)
        )
        named_pandora_animset_count = count_text_files(
            data_root / Path(*(PANDORA_MOD_REL / behavior_code / PANDORA_MOD_ANIMSET_REL).parts)
        )
        behavior_output_mode = ostimsa_selected_behavior_mode(
            has_character_att=bool(att_animation_list_paths),
            has_character_fnis=any((hkx_actor_root(PurePosixPath(*path.relative_to(data_root).parts)) or "character").lower() == "character" for path in animation_list_paths if path.is_relative_to(data_root)),
            has_creature_fnis=any((hkx_actor_root(PurePosixPath(*path.relative_to(data_root).parts)) or "character").lower() != "character" for path in animation_list_paths if path.is_relative_to(data_root)),
            has_nemesis_patch=bool(copied_source_engine_mod_files or generated_nemesis_patch_files),
            has_pandora_registration=bool(root_pandora_animdata_count or root_pandora_animset_count or named_pandora_animdata_count or named_pandora_animset_count),
        )

        report = build_conversion_report(
            scenes or [],
            assets,
            pack,
            source_archive=source_archive,
            conversion_warnings=conversion_warnings,
            mod_author=mod_author,
            sfx_fallback_action=fallback_action,
            furniture_type_file_count=len(copied_furniture_type_files),
            behavior_graph_hkx_count=len(copied_behavior_graphs),
            source_engine_patch_file_count=len(copied_source_engine_mod_files) + len(generated_nemesis_patch_files),
            generated_engine_patch_file_count=len(generated_nemesis_patch_files),
            pandora_animdata_file_count=root_pandora_animdata_count + named_pandora_animdata_count,
            pandora_animset_file_count=root_pandora_animset_count + named_pandora_animset_count,
            pandora_named_animdata_file_count=named_pandora_animdata_count,
            pandora_named_animset_file_count=named_pandora_animset_count,
            behavior_output_mode=behavior_output_mode,
            fnis_animation_list_file_count=len(animation_list_paths),
            att_animation_list_file_count=len(att_animation_list_paths),
            source_detection=source_detection,
            output_type="OStim Standalone",
            ostim_menu_entry_requested=ostim_menu_entry_requested,
            conversion_diagnostics=conversion_diagnostics,
        )
        all_animation_list_paths = [*animation_list_paths, *att_animation_list_paths]
        if all_animation_list_paths:
            report["behaviorLists"] = [
                data_path_text(PurePosixPath(*path.relative_to(data_root).parts))
                for path in [
                    *sorted(animation_list_paths, key=lambda item: str(item).lower()),
                    *sorted(att_animation_list_paths, key=lambda item: str(item).lower()),
                ]
            ]
        if copied_behavior_graphs:
            report["behaviorGraphFiles"] = [
                data_path_text(PurePosixPath(*path.relative_to(data_root).parts))
                for path in sorted(copied_behavior_graphs, key=lambda item: str(item).lower())
            ]
        write_converter_pack_metadata(
            data_root,
            report,
            scenes or [],
            assets,
            pack,
            source_archive=source_archive,
            mod_author=mod_author,
            sfx_fallback_action=fallback_action,
            action_content_paths=action_content_paths,
            furniture_type_content_paths=furniture_type_content_paths,
        )
        (temp_data / "conversion_report.json").write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
        (temp_data / "conversion_report.txt").write_text(report_to_text(report), encoding="utf-8")
        (temp_data / "conversion_report_README.txt").write_text(conversion_report_readme_text(report), encoding="utf-8")
        (temp_data / AAC_README_FILE).write_text(aac_readme_text(report), encoding="utf-8")
        (temp_data / AAC_MANIFEST_FILE).write_text(json.dumps(aac_manifest_for_report(report), indent=2, ensure_ascii=False), encoding="utf-8")

        with ZipFile(zip_path, "w", compression=ZIP_DEFLATED) as zf:
            add_ready_package_to_zip(zf, temp_data, data_root)
        return zip_path
    finally:
        cleanup_converter_temp_dir(temp_data)


def convert_archive_to_ready_zip(
    archive: Path,
    zip_path: Optional[Path] = None,
    pack: Optional[str] = None,
    mod_author: Optional[str] = None,
    sfx_fallback_action: Optional[str] = None,
    ostim_menu_entry: bool = False,
    ostim_menu_icon: Optional[str] = None,
    human_only_ostim: Optional[bool] = None,
    nemesis_safe_output: bool = DEFAULT_NEMESIS_SAFE_OUTPUT,
    ocreatures_compatible_output: bool = True,
    legacy_hkx_converter: Optional[Path | str] = None,
) -> ArchiveConversionResult:
    archive = archive.expanduser()
    if not archive.exists():
        raise FileNotFoundError(f"Archive not found: {archive}")

    pack_name = pack.strip() if pack and pack.strip() else pack_name_from_archive(archive)
    output_zip = zip_path.expanduser() if zip_path else default_zip_path_for_archive(archive)
    fallback_action = normalize_sfx_fallback_action_type(sfx_fallback_action)

    extracted: Optional[Path] = None
    working_output: Optional[Path] = None
    source_detection: Optional[Dict[str, Any]] = None
    try:
        extracted = extract_mod_archive(archive, output_zip)
        source_detection = detect_source_pack_summary(extracted)
        source_detection = add_compatibility_match_to_source_detection(source_detection, archive, extracted)
        branch_layout = archive_branch_layout_report(
            extracted,
            str(source_detection.get("selectedSourceType") or "unknown"),
            source_detection,
        )
        source_detection["archiveBranchLayout"] = branch_layout
        source_detection["sourceSelection"] = source_selection_report(
            source_detection,
            source_detection.get("compatibilityMatch") if isinstance(source_detection.get("compatibilityMatch"), dict) else {},
            branch_layout,
        )
        enforce_adult_only_source(source_detection)
        effective_human_only_ostim = (
            default_human_only_ostim_from_source_detection(source_detection)
            if human_only_ostim is None
            else bool(human_only_ostim)
        )
        input_root = find_scene_source_root(extracted)
        working_output = make_converter_temp_dir("ostim_sa_scenes_", output_zip)
        alignment_path = working_output / "alignment.json"
        result = run_conversion(
            input_xml=input_root,
            output_scenes=working_output,
            pack=pack_name,
            emit_alignment=alignment_path,
            harvest_search_roots=[extracted, input_root],
            sfx_fallback_action=fallback_action,
            ostim_menu_entry=ostim_menu_entry,
            ostim_menu_icon=ostim_menu_icon,
            human_only_ostim=effective_human_only_ostim,
            ocreatures_compatible_output=ocreatures_compatible_output,
            legacy_hkx_converter=legacy_hkx_converter,
        )
        author = normalized_mod_author(mod_author)
        report = build_conversion_report(
            result.scenes,
            result.hkx_assets,
            pack_name,
            source_archive=archive,
            conversion_warnings=result.warnings,
            mod_author=author,
            sfx_fallback_action=fallback_action,
            furniture_type_file_count=len(result.ostim_furniture_type_files),
            source_detection=source_detection,
            output_type="OStim Standalone",
            ostim_menu_entry_requested=ostim_menu_entry,
            conversion_diagnostics=result.diagnostics,
        )
        make_ready_to_install_zip(
            zip_path=output_zip,
            generated_scenes_root=working_output,
            pack=pack_name,
            alignment_path=result.alignment_written,
            hkx_assets=result.hkx_assets,
            scenes=result.scenes,
            source_archive=archive,
            conversion_warnings=result.warnings,
            mod_author=author,
            sfx_fallback_action=fallback_action,
            ostim_action_files=result.ostim_action_files,
            ostim_furniture_type_files=result.ostim_furniture_type_files,
            behavior_graphs=result.behavior_graphs,
            source_engine_mods=result.source_engine_mods,
            source_detection=source_detection,
            ostim_menu_entry_requested=ostim_menu_entry,
            conversion_diagnostics=result.diagnostics,
            nemesis_safe_output=nemesis_safe_output,
        )
        packaged_report = read_packaged_conversion_report(output_zip) or report
        verification = verify_converted_zip(output_zip)
        output_zip = mark_failed_zip_do_not_install(verification)
        packaged_report = read_packaged_conversion_report(output_zip) or packaged_report
        packaged_report["postBuildVerification"] = verification_summary_for_report(verification)
        write_packaged_conversion_report_files(output_zip, packaged_report, verification)
        write_external_conversion_report_files(output_zip, packaged_report, verification)
        return ArchiveConversionResult(
            output_zip,
            pack_name,
            author,
            result.scenes,
            result.hkx_assets,
            packaged_report,
            result.warnings,
            result.ostim_action_files,
            result.ostim_furniture_type_files,
            verification,
        )
    except Exception as exc:
        write_conversion_failure_report(output_zip, archive, "OStim Standalone", exc, source_detection=source_detection)
        raise
    finally:
        cleanup_converter_temp_dir(working_output)
        cleanup_converter_temp_dir(extracted)


def convert_archive_to_sexlab_zip(
    archive: Path,
    zip_path: Optional[Path] = None,
    pack: Optional[str] = None,
    mod_author: Optional[str] = None,
    sfx_fallback_action: Optional[str] = None,
    sexlab_plus: bool = False,
    sexlab_discovery_tags: bool = DEFAULT_SEXLAB_DISCOVERY_TAGS_ENABLED,
    legacy_hkx_converter: Optional[Path | str] = None,
) -> ArchiveConversionResult:
    archive = archive.expanduser()
    if not archive.exists():
        raise FileNotFoundError(f"Archive not found: {archive}")

    pack_name = pack.strip() if pack and pack.strip() else pack_name_from_archive(archive)
    output_zip = zip_path.expanduser() if zip_path else (
        default_sexlab_plus_zip_path_for_archive(archive) if sexlab_plus else default_sexlab_zip_path_for_archive(archive)
    )
    fallback_action = normalize_sfx_fallback_action_type(sfx_fallback_action)
    extracted: Optional[Path] = None
    working_output: Optional[Path] = None
    source_detection: Optional[Dict[str, Any]] = None
    output_type = "SexLab P+/SLSB" if sexlab_plus else "SexLab/SLAL"
    try:
        extracted = extract_mod_archive(archive, output_zip)
        source_detection = detect_source_pack_summary(extracted)
        source_detection = add_compatibility_match_to_source_detection(source_detection, archive, extracted)
        enforce_adult_only_source(source_detection)
        input_root = find_scene_source_root(extracted)
        working_output = make_converter_temp_dir("sexlab_scene_parse_", output_zip)
        result = run_conversion(
            input_xml=input_root,
            output_scenes=working_output,
            pack=pack_name,
            harvest_search_roots=[extracted, input_root],
            sfx_fallback_action=fallback_action,
            normalize_ostim_actor_slots=False,
            legacy_hkx_converter=legacy_hkx_converter,
        )
        author = normalized_mod_author(mod_author)
        output_zip, report, export_assets, warnings = make_sexlab_ready_zip(
            zip_path=output_zip,
            pack=pack_name,
            scenes=result.scenes,
            hkx_assets=result.hkx_assets,
            source_archive=archive,
            conversion_warnings=result.warnings,
            mod_author=author,
            sfx_fallback_action=fallback_action,
            sexlab_plus=sexlab_plus,
            sexlab_discovery_tags=sexlab_discovery_tags,
            behavior_graphs=result.behavior_graphs,
            source_detection=source_detection,
            conversion_diagnostics=result.diagnostics,
        )
        packaged_report = read_packaged_conversion_report(output_zip) or report
        verification = verify_converted_zip(output_zip)
        output_zip = mark_failed_zip_do_not_install(verification)
        packaged_report = read_packaged_conversion_report(output_zip) or packaged_report
        packaged_report["postBuildVerification"] = verification_summary_for_report(verification)
        write_packaged_conversion_report_files(output_zip, packaged_report, verification)
        write_external_conversion_report_files(output_zip, packaged_report, verification)
        return ArchiveConversionResult(
            output_zip,
            pack_name,
            author,
            result.scenes,
            export_assets,
            packaged_report,
            warnings,
            [],
            [],
            verification,
        )
    except Exception as exc:
        write_conversion_failure_report(output_zip, archive, output_type, exc, source_detection=source_detection)
        raise
    finally:
        cleanup_converter_temp_dir(working_output)
        cleanup_converter_temp_dir(extracted)


def convert_archive_to_ostim_tools_project(
    archive: Path,
    project_out: Optional[Path] = None,
    pack: Optional[str] = None,
    mod_author: Optional[str] = None,
    sfx_fallback_action: Optional[str] = None,
    options: Optional[OStimToolsProjectOptions] = None,
    legacy_hkx_converter: Optional[Path | str] = None,
) -> OStimToolsProjectExportResult:
    archive = archive.expanduser()
    if not archive.exists():
        raise FileNotFoundError(f"Archive not found: {archive}")

    options = options or OStimToolsProjectOptions()
    pack_name = pack.strip() if pack and pack.strip() else pack_name_from_archive(archive)
    output_root = (project_out.expanduser() if project_out else (
        default_scene_json_folder_path_for_archive(archive, pack_name)
        if options.scene_json_folder_only
        else default_ostim_tools_project_path_for_archive(archive, pack_name)
    ))
    fallback_action = normalize_sfx_fallback_action_type(sfx_fallback_action)
    extracted: Optional[Path] = None
    working_output: Optional[Path] = None
    source_detection: Optional[Dict[str, Any]] = None
    try:
        extracted = extract_mod_archive(archive, output_root)
        source_detection = detect_source_pack_summary(extracted)
        source_detection = add_compatibility_match_to_source_detection(source_detection, archive, extracted)
        enforce_adult_only_source(source_detection)
        input_root = find_scene_source_root(extracted)
        working_output = make_converter_temp_dir("ostim_tools_scene_parse_", output_root)
        result = run_conversion(
            input_xml=input_root,
            output_scenes=working_output,
            pack=pack_name,
            harvest_search_roots=[extracted, input_root],
            sfx_fallback_action=fallback_action,
            ostim_menu_entry=False,
            human_only_ostim=options.human_only_ostim,
            legacy_hkx_converter=legacy_hkx_converter,
        )
        if mod_author:
            source_detection["modAuthor"] = normalized_mod_author(mod_author)
        if options.scene_json_folder_only:
            return export_scene_json_folder(
                output_root,
                result.scenes,
                pack_name,
                source_archive=archive,
                source_detection=source_detection,
                conversion_warnings=result.warnings,
                options=options,
                conversion_diagnostics=result.diagnostics,
            )
        return export_ostim_tools_project(
            output_root,
            result.scenes,
            pack_name,
            hkx_assets=result.hkx_assets,
            source_archive=archive,
            source_detection=source_detection,
            conversion_warnings=result.warnings,
            options=options,
            conversion_diagnostics=result.diagnostics,
        )
    except Exception as exc:
        write_conversion_failure_report(None, archive, "OStim Tools JSON Project", exc, source_detection=source_detection)
        raise
    finally:
        cleanup_converter_temp_dir(working_output)
        cleanup_converter_temp_dir(extracted)


def convert_imported_ostim_tools_project_to_ready_zip(
    project_path: Path,
    zip_path: Path,
    pack: Optional[str] = None,
    mod_author: Optional[str] = None,
    sfx_fallback_action: Optional[str] = None,
    ostim_menu_entry: bool = False,
    ostim_menu_icon: Optional[str] = None,
    legacy_hkx_converter: Optional[Path | str] = None,
) -> ArchiveConversionResult:
    imported = import_ostim_tools_project(project_path)
    manifest_pack = imported.manifest.get("pack") if isinstance(imported.manifest.get("pack"), dict) else {}
    pack_name = pack or str(manifest_pack.get("displayName") or manifest_pack.get("safeName") or project_path.expanduser().stem or "ImportedOStimToolsProject")
    scenes = list(imported.scenes)
    import_warnings = list(imported.warnings)
    if ostim_menu_entry:
        scenes, menu_warnings = add_ostim_menu_hubs(
            scenes,
            pack_name,
            enabled=True,
            icon=ostim_menu_icon,
        )
        import_warnings.extend(menu_warnings)
        import_warnings.extend(
            add_generated_ostim_navigation_links(
                scenes,
                enabled=True,
                icon=ostim_menu_icon,
            )
        )
        removed_menu_navigations = dedupe_generated_ostim_menu_navigations(scenes)
        if removed_menu_navigations:
            import_warnings.append(f"Removed {len(removed_menu_navigations)} duplicate generated OStim menu navigation link(s) during project import packaging.")
    output_scenes = make_converter_temp_dir("ostim_tools_import_scenes_", zip_path)
    try:
        project_hkx_assets, legacy_hkx_warnings, legacy_hkx_diagnostics = convert_legacy_hkx_assets_for_sse(
            imported.hkx_assets,
            output_scenes,
            configured_converter=legacy_hkx_converter,
        )
        import_warnings.extend(legacy_hkx_warnings)
        for scene in scenes:
            write_scene_json(scene, output_scenes, pack_name)
        warnings = [
            "Imported OStim Tools/AAC project. Behavior files and HKX assets are generated or packaged only through the normal OStimSA build path.",
            *import_warnings,
        ]
        make_ready_to_install_zip(
            zip_path=zip_path.expanduser(),
            generated_scenes_root=output_scenes,
            pack=pack_name,
            alignment_path=None,
            hkx_assets=project_hkx_assets,
            scenes=scenes,
            source_archive=None,
            conversion_warnings=warnings,
            mod_author=mod_author,
            sfx_fallback_action=sfx_fallback_action,
            ostim_action_files=[],
            ostim_furniture_type_files=[],
            behavior_graphs=[],
            source_engine_mods=[],
            source_detection={
                "selectedSourceType": "ostimToolsProject",
                "selectedSourceTypeLabel": "OStim Tools/AAC project",
                "compatibilityMatch": known_pack_none_match(),
            },
            ostim_menu_entry_requested=ostim_menu_entry,
            conversion_diagnostics={"legacyHkxConversion": legacy_hkx_diagnostics},
        )
        verification = verify_converted_zip(zip_path.expanduser())
        verified_zip = mark_failed_zip_do_not_install(verification)
        report = read_packaged_conversion_report(verified_zip) or build_conversion_report(
            imported.scenes,
            project_hkx_assets,
            pack_name,
            conversion_warnings=warnings,
            mod_author=mod_author,
            sfx_fallback_action=sfx_fallback_action,
            source_detection={
                "selectedSourceType": "ostimToolsProject",
                "selectedSourceTypeLabel": "OStim Tools/AAC project",
                "compatibilityMatch": known_pack_none_match(),
            },
            output_type="OStim Standalone",
            ostim_menu_entry_requested=ostim_menu_entry,
            conversion_diagnostics={"legacyHkxConversion": legacy_hkx_diagnostics},
        )
        report["importedOStimToolsProject"] = {
            "source": project_path.expanduser().name,
            "sceneCount": len(scenes),
            "hkxAssetCount": len(project_hkx_assets),
            "unsupportedFields": imported.unsupported_fields,
        }
        report["postBuildVerification"] = verification_summary_for_report(verification)
        write_packaged_conversion_report_files(verified_zip, report, verification)
        write_external_conversion_report_files(verified_zip, report, verification)
        return ArchiveConversionResult(
            verified_zip,
            pack_name,
            normalized_mod_author(mod_author),
            scenes,
            project_hkx_assets,
            report,
            warnings,
            [],
            [],
            verification,
        )
    finally:
        cleanup_converter_temp_dir(output_scenes)


def launch_gui() -> int:
    if not TK_AVAILABLE:
        print("tkinter is not available in this Python environment.")
        return 2
    if not CTK_AVAILABLE:
        print("customtkinter is not available in this Python environment.")
        return 2

    ctk.set_appearance_mode("dark")
    theme_path = resource_path(APP_THEME_REL)
    if theme_path.exists():
        ctk.set_default_color_theme(str(theme_path))
    if sys.platform == "win32":
        try:
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("AdultAnimationConverter.App")
        except Exception:
            pass

    root = ctk.CTk()
    root.title(APP_NAME)
    root.geometry("1040x720")
    root.minsize(760, 420)
    root.resizable(True, True)
    icon_path = resource_path(APP_ICON_REL)
    if icon_path.exists():
        try:
            root.iconbitmap(default=str(icon_path))
            root.wm_iconbitmap(default=str(icon_path))
        except Exception:
            pass

    app_settings = load_app_settings()
    slsb_setting = app_settings.get("slsbRepoPath")
    slsb_repo_path = Path(slsb_setting).expanduser() if isinstance(slsb_setting, str) and is_sexlab_scene_builder_repo(slsb_setting) else detect_sexlab_scene_builder_repo()
    sexlab_plus_available = slsb_repo_path is not None

    state = {
        "mod_archive": tk.StringVar(),
        "input_xml": tk.StringVar(),
        "output_scenes": tk.StringVar(),
        "pack": tk.StringVar(value="ConvertedPack"),
        "mod_author": tk.StringVar(),
        "sfx_fallback_choice": tk.StringVar(value=sfx_fallback_dropdown_label_for_action(str(app_settings.get("sfxFallbackAction") or DEFAULT_SFX_FALLBACK_ACTION_TYPE))),
        "ostim_menu_entry": tk.BooleanVar(value=bool(app_settings.get("addOStimMenuEntry", True))),
        "ostim_menu_icon": tk.StringVar(value=normalize_ostim_menu_icon(str(app_settings.get("ostimMenuIcon") or DEFAULT_OSTIM_MENU_ICON))),
        "human_only_ostim": tk.BooleanVar(value=bool(app_settings.get("humanOnlyOStimOutput", DEFAULT_HUMAN_ONLY_OSTIM_OUTPUT))),
        "ocreatures_compatible_output": tk.BooleanVar(value=bool(app_settings.get("ocreaturesCompatibleOutput", True))),
        "sexlab_discovery_tags": tk.BooleanVar(value=bool(app_settings.get("sexLabDiscoveryTags", DEFAULT_SEXLAB_DISCOVERY_TAGS_ENABLED))),
        "sexlab_plus": tk.BooleanVar(value=bool(app_settings.get("sexLabPlusExport", False))),
        "nemesis_safe_output": tk.BooleanVar(value=True),
        "debug_mode": tk.BooleanVar(value=bool(app_settings.get("debugMode", False))),
        "status_summary": tk.StringVar(value="Status: idle\nNext: choose a source archive or verify a converted ZIP."),
        "recommended_workflow": tk.StringVar(value="Detected: not run yet\nRecommended next step: choose or drop a source archive, then click Diagnose Archive."),
        "install_steps": tk.StringVar(value="Install steps will appear after a successful build."),
        "ui_mode": tk.StringVar(value=str(app_settings.get("uiMode") or "Simple Mode")),
        "open_output_after_build": tk.BooleanVar(value=bool(app_settings.get("openOutputAfterBuild", True))),
        "sexlab_plus_repo_status": tk.StringVar(value=sexlab_scene_builder_repo_status_text(slsb_repo_path)),
        "seven_zip_path": tk.StringVar(value=str(app_settings.get("sevenZipPath") or "")),
        "legacy_hkx_converter": tk.StringVar(value=str(app_settings.get("legacyHkxConverterPath") or "")),
        "emit_alignment": tk.StringVar(),
        "merge_alignment": tk.StringVar(),
        "zip_out": tk.StringVar(),
        "ostim_tools_project_out": tk.StringVar(value=str(app_settings.get("lastOStimToolsProjectOutputFolder") or "")),
        "ostim_tools_template": tk.StringVar(value=str(app_settings.get("lastOStimToolsTemplatePath") or "")),
        "ostim_tools_include_actions": tk.BooleanVar(value=bool(app_settings.get("ostimToolsIncludeActions", True))),
        "ostim_tools_include_alignment": tk.BooleanVar(value=bool(app_settings.get("ostimToolsIncludeAlignment", True))),
        "ostim_tools_alignment_template": tk.BooleanVar(value=bool(app_settings.get("ostimToolsAlignmentTemplate", False))),
        "ostim_tools_include_source_metadata": tk.BooleanVar(value=bool(app_settings.get("ostimToolsIncludeSourceMetadata", True))),
        "ostim_tools_menu_scaffold": tk.BooleanVar(value=bool(app_settings.get("ostimToolsMenuScaffold", False))),
        "ostim_tools_scene_json_folder_mode": tk.BooleanVar(value=bool(app_settings.get("ostimToolsSceneJsonFolderMode", False))),
    }

    accent_magenta = ("#8f18c8", "#c327ff")
    accent_magenta_hover = ("#6f119a", "#8c16c4")
    secondary_button = ("#4a1530", "#3a1028")
    secondary_hover = ("#681944", "#5c1642")
    muted_text = ("#6c4453", "#c99bad")

    root.columnconfigure(0, weight=1)
    root.rowconfigure(0, weight=1)
    frame = ctk.CTkScrollableFrame(
        root,
        fg_color="transparent",
        border_width=0,
        corner_radius=0,
        scrollbar_button_color=accent_magenta,
        scrollbar_button_hover_color=accent_magenta_hover,
    )
    frame.grid(row=0, column=0, sticky="nsew", padx=14, pady=12)
    frame.columnconfigure(0, weight=1)

    header = ctk.CTkFrame(frame, fg_color="transparent", border_width=0, corner_radius=0)
    header.grid(row=0, column=0, sticky="ew", pady=(0, 14))
    header.columnconfigure(1, weight=1)

    logo_image = None
    logo_path = resource_path(APP_ICON_PNG_REL)
    if PIL_AVAILABLE and logo_path.exists():
        try:
            logo = Image.open(logo_path)
            logo_image = ctk.CTkImage(light_image=logo, dark_image=logo, size=(72, 72))
            root.logo_image = logo_image
        except Exception:
            logo_image = None
