    def browse_dir(var: tk.StringVar) -> None:
        path = filedialog.askdirectory()
        if path:
            var.set(path)

    def browse_file_open_json(var: tk.StringVar) -> None:
        path = filedialog.askopenfilename(filetypes=(("JSON", "*.json"), ("All", "*.*")))
        if path:
            var.set(path)

    def browse_file_save_json(var: tk.StringVar) -> None:
        path = filedialog.asksaveasfilename(defaultextension=".json", filetypes=(("JSON", "*.json"), ("All", "*.*")))
        if path:
            var.set(path)

    def browse_file_open_executable(var: tk.StringVar) -> None:
        path = filedialog.askopenfilename(filetypes=(("Executable", "*.exe"), ("All", "*.*")))
        if path:
            var.set(path)
            save_current_settings()

    def browse_save_zip(var: tk.StringVar) -> None:
        path = filedialog.asksaveasfilename(defaultextension=".zip", filetypes=(("ZIP file", "*.zip"),))
        if path:
            var.set(path)

    def browse_mod_archive() -> None:
        path = filedialog.askopenfilename(filetypes=(("Mod archives", "*.zip;*.7z;*.rar"), ("ZIP", "*.zip"), ("7z", "*.7z"), ("RAR", "*.rar"), ("All", "*.*")))
        if path:
            archive = Path(path)
            state["mod_archive"].set(path)
            state["pack"].set(pack_name_from_archive(archive))
            if not state["zip_out"].get().strip():
                state["zip_out"].set(str(default_zip_path_for_archive(archive)))
            state["recommended_workflow"].set(
                "\n".join(
                    [
                        f"Detected: archive selected ({archive.suffix.lower()})",
                        "Confidence: not diagnosed yet",
                        "Recommended output: run diagnosis",
                        "Recommended behavior tool: not recorded",
                        "",
                        "Recommended next step: click Diagnose Archive or Build Recommended Package.",
                    ]
                )
            )

    def selected_sfx_fallback_action() -> str:
        return sfx_fallback_action_from_dropdown(state["sfx_fallback_choice"].get()).strip()

    def current_selected_archive() -> Optional[Path]:
        value = state["mod_archive"].get().strip()
        if not value:
            return None
        try:
            return Path(value)
        except (TypeError, ValueError):
            return None

    def save_current_settings() -> None:
        zip_out_text = state["zip_out"].get().strip()
        last_output_folder = str(Path(zip_out_text).expanduser().parent) if zip_out_text else str(app_settings.get("lastOutputFolder") or "")
        last_human_report = str(app_settings.get("lastHumanReport") or "")
        last_json_report = str(app_settings.get("lastJsonReport") or "")
        try:
            paths = operation_paths()
            if paths.get("output_folder"):
                last_output_folder = str(paths["output_folder"])
            if paths.get("human_report"):
                last_human_report = str(paths["human_report"])
            if paths.get("json_report"):
                last_json_report = str(paths["json_report"])
        except Exception:
            pass
        save_app_settings(
            {
                "lastOutputFolder": last_output_folder,
                "sfxFallbackAction": selected_sfx_fallback_action(),
                "addOStimMenuEntry": bool(state["ostim_menu_entry"].get()),
                "ostimMenuIcon": normalize_ostim_menu_icon(state["ostim_menu_icon"].get()),
                "humanOnlyOStimOutput": bool(state["human_only_ostim"].get()),
                "ocreaturesCompatibleOutput": bool(state["ocreatures_compatible_output"].get()),
                "sexLabPlusExport": bool(state["sexlab_plus"].get()),
                "sexLabDiscoveryTags": bool(state["sexlab_discovery_tags"].get()),
                "sevenZipPath": state["seven_zip_path"].get().strip() or find_7z_executable() or "",
                "legacyHkxConverterPath": state["legacy_hkx_converter"].get().strip(),
                "slsbRepoPath": str(slsb_repo_path) if slsb_repo_path else "",
                "nemesisSafeOutput": bool(state["nemesis_safe_output"].get()),
                "debugMode": bool(state["debug_mode"].get()),
                "uiMode": state["ui_mode"].get() if state["ui_mode"].get() in {"Simple Mode", "Advanced Mode"} else "Simple Mode",
                "advancedOptionsExpanded": state["ui_mode"].get() == "Advanced Mode",
                "openOutputAfterBuild": bool(state["open_output_after_build"].get()),
                "lastHumanReport": last_human_report,
                "lastJsonReport": last_json_report,
                "lastOStimToolsProjectOutputFolder": state["ostim_tools_project_out"].get().strip(),
                "lastOStimToolsTemplatePath": state["ostim_tools_template"].get().strip(),
                "ostimToolsIncludeActions": bool(state["ostim_tools_include_actions"].get()),
                "ostimToolsIncludeAlignment": bool(state["ostim_tools_include_alignment"].get()),
                "ostimToolsAlignmentTemplate": bool(state["ostim_tools_alignment_template"].get()),
                "ostimToolsIncludeSourceMetadata": bool(state["ostim_tools_include_source_metadata"].get()),
                "ostimToolsMenuScaffold": bool(state["ostim_tools_menu_scaffold"].get()),
                "ostimToolsSceneJsonFolderMode": bool(state["ostim_tools_scene_json_folder_mode"].get()),
            }
        )

    busy_buttons: List[Any] = []
    sexlab_plus_controls: Dict[str, Any] = {}
    last_operation: Dict[str, Any] = {}
    last_pandora_log_analysis: Dict[str, Optional[PandoraLogAnalysisResult]] = {"result": None}
    last_error: Dict[str, Any] = {"path": None, "summary": ""}
    ui_events: "queue.Queue[Tuple[str, Any]]" = queue.Queue()
    background_job_state: Dict[str, Any] = {"active": False, "started": 0.0, "lastHeartbeat": 0.0}

    def apply_sexlab_plus_availability(busy: bool = False) -> None:
        checkbox = sexlab_plus_controls.get("checkbox")
        if checkbox is None:
            return
        if not sexlab_plus_available:
            state["sexlab_plus"].set(False)
            checkbox.configure(state="disabled")
            return
        checkbox.configure(state="disabled" if busy else "normal")

    def set_busy(busy: bool) -> None:
        state_value = "disabled" if busy else "normal"
        for button in busy_buttons:
            button.configure(state=state_value)
        apply_sexlab_plus_availability(busy)
        root.configure(cursor="watch" if busy else "")
        root.update_idletasks()

    def worker_log(message: str) -> None:
        ui_events.put(("log", message))

    def run_background_job(job: Any, on_success: Optional[Any] = None) -> None:
        set_busy(True)
        started = time.monotonic()
        background_job_state.update({"active": True, "started": started, "lastHeartbeat": started})

        def target() -> None:
            try:
                result = job(worker_log)
            except Exception as exc:
                ui_events.put(("error", (exc, traceback.format_exc())))
            else:
                ui_events.put(("success", (on_success, result)))

        threading.Thread(target=target, daemon=True).start()

    def process_ui_events() -> None:
        try:
            while True:
                kind, payload = ui_events.get_nowait()
                if kind == "log":
                    log(str(payload))
                elif kind == "error":
                    background_job_state["active"] = False
                    set_busy(False)
                    if isinstance(payload, tuple) and len(payload) == 2:
                        exc, tb = payload
                    else:
                        exc, tb = payload, ""
                    debug_mode = bool(state["debug_mode"].get())
                    operation = str(last_operation.get("kind") or "background job")
                    log_path, summary = write_internal_error_log(
                        exc if isinstance(exc, BaseException) else RuntimeError(str(exc)),
                        str(tb),
                        operation=operation,
                        source_archive=current_selected_archive(),
                        debug_mode=debug_mode,
                    )
                    last_error["path"] = log_path
                    last_error["summary"] = summary
                    error_log_button.configure(state="normal" if can_open_path(log_path) else "disabled")
                    copy_error_button.configure(state="normal")
                    dialog_lines = [
                        "An internal error occurred.",
                        "",
                        f"Converter version: {CONVERTER_VERSION}",
                        f"Operation: {operation}",
                    ]
                    if current_selected_archive() is not None:
                        archive_text = public_path_text(current_selected_archive(), debug_mode)
                        dialog_lines.append(f"Selected archive: {archive_text}")
                    dialog_lines.append(f"Debug mode: {public_bool(debug_mode)}")
                    if log_path is not None:
                        dialog_lines.extend(
                            [
                                "",
                                "A detailed error log was written to:",
                                str(log_path),
                                "",
                                "Please attach that log or a Nexus-safe report bundle when reporting this issue.",
                            ]
                        )
                    else:
                        dialog_lines.extend(
                            [
                                "",
                                "The app could not write a detailed error log. Use Copy Error Summary before reporting this issue.",
                            ]
                        )
                    messagebox.showerror("Internal Error", "\n".join(dialog_lines))
                    log(f"ERROR: {public_safe_text(str(exc), debug_mode=debug_mode)}")
                    if log_path is not None:
                        log(f"Error log written: {public_path_text(log_path, debug_mode)}")
                    if tb:
                        log(str(tb).rstrip())
                elif kind == "success":
                    background_job_state["active"] = False
                    callback, result = payload
                    try:
                        if callback is not None:
                            callback(result)
                    finally:
                        set_busy(False)
        except queue.Empty:
            pass
        if background_job_state.get("active"):
            now = time.monotonic()
            if now - float(background_job_state.get("lastHeartbeat") or 0.0) >= 15.0:
                elapsed = max(0, int(now - float(background_job_state.get("started") or now)))
                log(f"Still working... {elapsed} seconds elapsed. Large solid archives and behavior patches can take several minutes.")
                background_job_state["lastHeartbeat"] = now
        root.after(100, process_ui_events)

    tooltip_window: Dict[str, Optional[Any]] = {"window": None}

    def add_tooltip(widget: Any, text: str) -> None:
        try:
            widget.tooltip_text = text

            def show_tooltip(_event: Any = None) -> None:
                if tooltip_window.get("window") is not None:
                    return
                tip = tk.Toplevel(root)
                tip.wm_overrideredirect(True)
                x = widget.winfo_rootx() + 20
                y = widget.winfo_rooty() + widget.winfo_height() + 8
                tip.wm_geometry(f"+{x}+{y}")
                label = tk.Label(
                    tip,
                    text=text,
                    justify="left",
                    background="#2b101f",
                    foreground="#f4d6e3",
                    relief="solid",
                    borderwidth=1,
                    padx=8,
                    pady=5,
                    wraplength=360,
                )
                label.pack()
                tooltip_window["window"] = tip

            def hide_tooltip(_event: Any = None) -> None:
                tip = tooltip_window.get("window")
                if tip is not None:
                    tip.destroy()
                    tooltip_window["window"] = None

            widget.bind("<Enter>", show_tooltip, add="+")
            widget.bind("<Leave>", hide_tooltip, add="+")
            widget.bind("<ButtonPress>", hide_tooltip, add="+")
        except Exception:
            pass

