    def focused_widget_allows_text_navigation() -> bool:
        try:
            focused = root.focus_get()
            widget_class = focused.winfo_class() if focused is not None else ""
        except Exception:
            return False
        return widget_class in {"Entry", "Text", "TEntry", "TCombobox", "Spinbox"}

    def scroll_main_content(units: int = 0, moveto: Optional[float] = None) -> str:
        if focused_widget_allows_text_navigation():
            return ""
        canvas = getattr(frame, "_parent_canvas", None)
        if canvas is None:
            return ""
        try:
            if moveto is not None:
                canvas.yview_moveto(moveto)
            else:
                canvas.yview_scroll(units, "units")
        except Exception:
            return ""
        return "break"

    root.bind("<Prior>", lambda _event: scroll_main_content(-8))
    root.bind("<Next>", lambda _event: scroll_main_content(8))
    root.bind("<Control-Home>", lambda _event: scroll_main_content(moveto=0.0))
    root.bind("<Control-End>", lambda _event: scroll_main_content(moveto=1.0))

    def clear_log() -> None:
        log_box.configure(state="normal")
        log_box.delete("1.0", "end")
        log_box.configure(state="disabled")

    def log(message: str) -> None:
        log_box.configure(state="normal")
        log_box.insert("end", message + "\n")
        log_box.see("end")
        log_box.configure(state="disabled")
        root.update_idletasks()

    def operation_paths() -> Dict[str, Optional[Path]]:
        result = last_operation.get("result")
        if isinstance(result, ArchiveConversionResult):
            return {
                "output_folder": result.zip_path.parent,
                "human_report": result.zip_path.with_name(f"{result.zip_path.stem}_conversion_report_README.txt"),
                "json_report": result.zip_path.with_name(f"{result.zip_path.stem}_conversion_report.json"),
            }
        if isinstance(result, ZipVerificationResult):
            return {
                "output_folder": result.zip_path.parent,
                "human_report": result.text_report_path,
                "json_report": result.report_path,
            }
        if isinstance(result, SourceDiagnosisResult):
            return {
                "output_folder": result.archive.parent,
                "human_report": result.text_report_path,
                "json_report": result.report_path,
            }
        if isinstance(result, OStimToolsProjectExportResult):
            return {
                "output_folder": result.project_path,
                "human_report": result.text_report_path,
                "json_report": result.report_path,
            }
        if isinstance(result, OStimToolsProjectValidationResult):
            return {
                "output_folder": result.project_path,
                "human_report": result.text_report_path,
                "json_report": result.report_path,
            }
        saved = load_app_settings()
        def saved_path(key: str) -> Optional[Path]:
            value = saved.get(key)
            if not isinstance(value, str) or not value.strip():
                return None
            return Path(value).expanduser()

        return {
            "output_folder": saved_path("lastOutputFolder"),
            "human_report": saved_path("lastHumanReport"),
            "json_report": saved_path("lastJsonReport"),
        }

    def refresh_open_buttons() -> None:
        paths = operation_paths()
        open_output_button.configure(state="normal" if can_open_path(paths.get("output_folder")) else "disabled")
        open_report_button.configure(state="normal" if can_open_path(paths.get("human_report")) else "disabled")
        open_json_report_button.configure(state="normal" if can_open_path(paths.get("json_report")) else "disabled")
        simple_open_output_button.configure(state="normal" if can_open_path(paths.get("output_folder")) else "disabled")
        simple_open_report_button.configure(state="normal" if can_open_path(paths.get("human_report")) else "disabled")
        simple_open_json_button.configure(state="normal" if can_open_path(paths.get("json_report")) else "disabled")

    def report_for_status(result: Any) -> Tuple[Dict[str, Any], str, str]:
        if isinstance(result, ArchiveConversionResult):
            verification = result.verification.report if result.verification else {}
            return result.report, verification.get("status") or result.report.get("status") or "UNKNOWN", result.report.get("outputType") or "OStim Standalone"
        if isinstance(result, ZipVerificationResult):
            return result.report, result.report.get("status") or ("PASS" if result.ok else "FAIL"), result.report.get("target") or result.report.get("outputType") or "Converted ZIP"
        if isinstance(result, SourceDiagnosisResult):
            return result.report, result.report.get("status") or "UNKNOWN", "Diagnosis"
        if isinstance(result, OStimToolsProjectExportResult):
            return result.report, result.report.get("status") or "DONE", result.report.get("outputTarget") or "OStim Tools JSON Project"
        if isinstance(result, OStimToolsProjectValidationResult):
            return result.report, result.report.get("status") or ("PASS" if result.ok else "FAIL"), "OStim Tools Project Validation"
        if isinstance(result, ConversionResult):
            return {"sceneCount": len(result.scenes), "hkxCount": len(result.hkx_assets)}, "DONE", "Folder conversion"
        return {}, "idle", "not selected"

    def update_status_summary(kind: str, result: Any) -> None:
        report, status, output_mode = report_for_status(result)
        match = report.get("compatibilityMatch") if isinstance(report.get("compatibilityMatch"), dict) else {}
        detected = report.get("selectedSourceTypeLabel") or report.get("detectedSourceType") or "not recorded"
        known = (
            f"{match.get('matchedPack')} ({match.get('matchResult')})"
            if match and match.get("matchResult") != "None"
            else "none"
        )
        behavior = report.get("recommendedBehaviorTool") or "Pandora recommended for most OStim Standalone packages"
        paths = operation_paths()
        report_path = paths.get("human_report")
        next_action = report.get("recommendedActionOneLine") or report.get("recommendedUserAction") or "Install generated ZIP, rerun Pandora/Nemesis, then test in game."
        ocreatures_menu = report.get("creatureMenuIntegration") if isinstance(report.get("creatureMenuIntegration"), dict) else {}
        creature_menu_line = ""
        if ocreatures_menu and int(ocreatures_menu.get("creatureScenesWritten") or 0):
            creature_menu_line = (
                f"OCreatures menu entry generated: {'yes' if ocreatures_menu.get('ocreaturesMenuEntryGenerated') else 'no'} "
                f"({ocreatures_menu.get('creatureScenesReachableFromOCreaturesMenu', 0)}/"
                f"{ocreatures_menu.get('creatureScenesWritten', 0)} reachable)"
            )
        summary_lines = [
            f"Status: {status}",
            f"Detected: {detected}",
            f"Known match: {known}",
            f"Output: {output_mode}",
            f"Behavior: {behavior}",
        ]
        if creature_menu_line:
            summary_lines.append(creature_menu_line)
            summary_lines.append("Test location: OCreatures creature menu")
            summary_lines.append("Runtime required: OCreatures + Creature Framework + matching creature assets + Pandora output")
        summary_lines.extend(
            [
                f"Report: {public_path_text(report_path)}",
                f"Next: {next_action}",
            ]
        )
        state["status_summary"].set(
            "\n".join(summary_lines)
        )
        state["recommended_workflow"].set(recommended_workflow_panel_text(report))
        if isinstance(result, (ArchiveConversionResult, ZipVerificationResult)):
            zip_name = result.zip_path.name if isinstance(result, ArchiveConversionResult) else result.zip_path.name
            state["install_steps"].set(install_steps_text(report, zip_name=zip_name))

    def open_path_in_shell(path: Optional[Path]) -> None:
        if not path:
            messagebox.showinfo("Nothing to open", "No file or folder is available yet.")
            return
        target = Path(path)
        if not target.exists():
            messagebox.showwarning("Missing file", f"This path is not available yet:\n{target.name}")
            refresh_open_buttons()
            return
        try:
            if os.name == "nt":
                os.startfile(str(target))  # type: ignore[attr-defined]
            else:
                subprocess.Popen(["xdg-open", str(target)])
        except Exception as exc:
            messagebox.showerror("Open failed", str(exc))

    def open_output_folder() -> None:
        open_path_in_shell(operation_paths().get("output_folder"))

    def open_human_report() -> None:
        open_path_in_shell(operation_paths().get("human_report"))

    def open_json_report() -> None:
        open_path_in_shell(operation_paths().get("json_report"))

    def open_compatibility_db_folder() -> None:
        folder = compatibility_database_folder()
        try:
            folder.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            messagebox.showerror("Compatibility DB folder", str(exc))
            return
        open_path_in_shell(folder)
        log(f"Compatibility database folder: {public_path_text(folder, bool(state['debug_mode'].get()))}")

