    def show_known_compatibility_dialog() -> None:
        db = load_compatibility_database()
        entries = db.get("entries") or []
        if not entries:
            message = "No compatibility database was loaded."
        else:
            blocks: List[str] = []
            for entry in entries[:60]:
                blocks.append(
                    "\n".join(
                        [
                            str(entry.get("packDisplayName") or entry.get("name") or entry.get("id") or "Unnamed profile"),
                            f"Status: {entry.get('status') or 'not recorded'}",
                            f"Recommended output: {entry.get('recommendedOutputType') or entry.get('recommendedOutput') or 'not recorded'}",
                            f"Recommended behavior tool: {entry.get('recommendedBehaviorTool') or 'not recorded'}",
                            f"Known limitations: {summarize_values(normalize_string_list(entry.get('limitations'))) or 'none recorded'}",
                            f"Minimum recommended converter version: {entry.get('minimumConverterVersionRecommended') or entry.get('minimumConverterVersion') or 'not recorded'}",
                            f"Notes: {summarize_values(normalize_string_list(entry.get('notes'))) or 'none recorded'}",
                        ]
                    )
                )
            message = "\n\n".join(blocks)
            if len(entries) > 60:
                message += f"\n\n... {len(entries) - 60} more profile(s)."
        messagebox.showinfo("Known Compatibility", message)

    def remember_operation(kind: str, result: Any) -> None:
        last_operation.clear()
        last_operation.update({"kind": kind, "result": result})
        refresh_open_buttons()
        update_status_summary(kind, result)
        save_current_settings()

    def apply_ui_mode() -> None:
        mode = state["ui_mode"].get()
        if mode not in {"Simple Mode", "Advanced Mode"}:
            mode = "Simple Mode"
            state["ui_mode"].set(mode)
        if mode == "Simple Mode":
            quick_frame.grid_remove()
            form_frame.grid_remove()
            run_button.grid_remove()
        else:
            quick_frame.grid(row=3, column=0, sticky="ew", pady=(0, 12))
            form_frame.grid(row=4, column=0, sticky="ew", pady=(0, 12))
            run_button.grid(row=5, column=0, sticky="ew", pady=(0, 12))
        save_current_settings()

