    def pandora_report_from_last_operation() -> Dict[str, Any]:
        result = last_operation.get("result")
        report: Dict[str, Any] = {}
        if isinstance(result, ArchiveConversionResult):
            if result.verification and isinstance(result.verification.report, dict):
                report = result.verification.report
            elif isinstance(result.report, dict):
                report = result.report
        elif isinstance(result, ZipVerificationResult):
            report = result.report
        return report

    def expected_pandora_modules_from_last_operation() -> List[str]:
        report = pandora_report_from_last_operation()
        if report_output_type(report).lower().startswith("sexlab"):
            return []
        modules: List[str] = []
        diagnostics = report.get("pandoraModuleDiagnostics") if isinstance(report.get("pandoraModuleDiagnostics"), dict) else {}
        for value in (
            diagnostics.get("pandoraModuleCode"),
            diagnostics.get("pandoraModuleDisplayName"),
            report.get("behaviorCode"),
            report.get("pack"),
            report.get("packName"),
        ):
            if isinstance(value, str) and value.strip():
                modules.append(value.strip())
        for row in report.get("pandoraNamedMods") or []:
            if not isinstance(row, dict):
                continue
            for key in ("code", "modCode", "name", "displayName"):
                value = row.get(key)
                if isinstance(value, str) and value.strip():
                    modules.append(value.strip())
        return sorted(set(modules), key=str.lower)

    def expected_pandora_fnis_lists_from_last_operation() -> List[str]:
        report = pandora_report_from_last_operation()
        if not report_output_type(report).lower().startswith("sexlab"):
            return []
        paths = report.get("paths") if isinstance(report.get("paths"), dict) else {}
        files = report.get("files") if isinstance(report.get("files"), dict) else {}
        quality = report.get("sexLabSourceFnisQuality") if isinstance(report.get("sexLabSourceFnisQuality"), dict) else {}
        values: List[str] = []
        for candidate in (
            report.get("pandoraExpectedFnisListFiles"),
            paths.get("fnisLists"),
            files.get("fnisLists"),
            quality.get("fnisPaths"),
        ):
            values.extend(normalize_string_list(candidate))
        return sorted({pandora_fnis_mod_name(value) for value in values if pandora_fnis_mod_name(value)}, key=str.lower)

    def import_pandora_log() -> None:
        path = filedialog.askopenfilename(filetypes=(("Pandora log", "*.log;*.txt"), ("Log", "*.log"), ("Text", "*.txt"), ("All", "*.*")))
        if not path:
            return
        log_path = Path(path).expanduser()
        expected_modules = expected_pandora_modules_from_last_operation()
        expected_fnis_lists = expected_pandora_fnis_lists_from_last_operation()
        clear_log()

        def job(job_log: Any) -> PandoraLogAnalysisResult:
            job_log(f"Analyzing Pandora log: {log_path.name}")
            if expected_modules:
                job_log(f"Expected module(s): {', '.join(expected_modules)}")
            else:
                job_log("Expected module(s): not supplied")
            if expected_fnis_lists:
                job_log(f"Expected FNIS list(s): {', '.join(expected_fnis_lists)}")
                job_log("SexLab FNIS lists are auto-discovered; no converted-pack checkbox is expected.")
            return analyze_pandora_log_file(
                log_path,
                expected_modules=expected_modules,
                expected_fnis_lists=expected_fnis_lists,
            )

        def on_success(result: PandoraLogAnalysisResult) -> None:
            last_pandora_log_analysis["result"] = result
            report = result.report
            log(f"Pandora log analysis: {report.get('status')}")
            log(f"Expected module mentioned: {public_bool(report.get('expectedModuleMentioned'))}")
            log(f"Expected module skipped: {public_bool(report.get('expectedModuleSkipped'))}")
            log(f"Expected FNIS list mentioned: {public_bool(report.get('expectedFnisListMentioned'))}")
            log(f"Output generated evidence: {public_bool(report.get('outputGenerated'))}")
            log(f"No/zero animations evidence: {public_bool(report.get('noAnimationsFound'))}")
            if report.get("maxAnimationsAdded") is not None:
                log(f"Max animations added: {report.get('maxAnimationsAdded')}")
            for error in (report.get("errorLines") or [])[:10]:
                log(f"ERROR: {error}")
            for warning in (report.get("warningLines") or [])[:10]:
                log(f"WARNING: {warning}")
            log(f"Recommended action: {report.get('recommendedUserAction')}")
            if result.report_path:
                log(f"Pandora log JSON report: {public_path_text(result.report_path, bool(state['debug_mode'].get()))}")
            if result.text_report_path:
                log(f"Pandora log text report: {public_path_text(result.text_report_path, bool(state['debug_mode'].get()))}")
            messagebox.showinfo("Pandora log analyzed", f"Status: {report.get('status')}\n\n{report.get('recommendedUserAction')}")

        run_background_job(job, on_success)

    def create_report_bundle_from_last_operation() -> None:
        result = last_operation.get("result")
        report: Optional[Dict[str, Any]] = None
        verification: Optional[ZipVerificationResult] = None
        diagnosis: Optional[Dict[str, Any]] = None
        base_folder = Path(state["mod_archive"].get()).expanduser().parent if state["mod_archive"].get().strip() else app_base_dir()
        pack_name = state["pack"].get().strip() or "AdultAnimationConverter"
        if isinstance(result, ArchiveConversionResult):
            report = result.report
            verification = result.verification
            if isinstance(result.report.get("sourceDiagnosisSummary"), dict):
                diagnosis = result.report.get("sourceDiagnosisSummary")
            base_folder = result.zip_path.parent
            pack_name = result.pack
        elif isinstance(result, ZipVerificationResult):
            report = result.report
            verification = result
            packaged_report = result.report.get("packagedConversionReport") if isinstance(result.report.get("packagedConversionReport"), dict) else {}
            if isinstance(packaged_report.get("sourceDiagnosisSummary"), dict):
                diagnosis = packaged_report.get("sourceDiagnosisSummary")
            base_folder = result.zip_path.parent
            pack_name = result.zip_path.stem
        elif isinstance(result, SourceDiagnosisResult):
            diagnosis = result.report
            base_folder = result.archive.parent
            pack_name = pack_name_from_archive(result.archive)

        archive_path = Path(state["mod_archive"].get()).expanduser() if state["mod_archive"].get().strip() else None
        settings_snapshot = selected_settings_summary()
        log_snapshot = visible_log_text()
        debug_snapshot = bool(state["debug_mode"].get())
        pandora_log_result = last_pandora_log_analysis.get("result")
        pandora_log_report = pandora_log_result.report if isinstance(pandora_log_result, PandoraLogAnalysisResult) else None
        if not any([report, verification, diagnosis]) and isinstance(pandora_log_result, PandoraLogAnalysisResult):
            report = pandora_log_result.report
            base_folder = pandora_log_result.log_path.parent
            pack_name = pandora_log_result.log_path.stem

        def job(job_log: Any) -> Path:
            job_log("Creating Nexus-safe report bundle")
            structure = archive_structure_report_for_archive(archive_path) if archive_path and archive_path.exists() else {}
            bundle = base_folder / f"AAC_BugReport_{safe_pack_folder(pack_name)}.zip"
            return create_nexus_safe_report_bundle(
                bundle,
                report=report,
                verification=verification,
                diagnosis=diagnosis,
                archive_structure=structure,
                pandora_log_analysis=pandora_log_report,
                selected_settings=settings_snapshot,
                log_text=log_snapshot,
                debug_mode=debug_snapshot,
            )

        def on_success(path: Path) -> None:
            log(f"Nexus-safe report bundle: {public_path_text(path, bool(state['debug_mode'].get()))}")
            messagebox.showinfo("Report bundle created", f"Created:\n{public_path_text(path)}")

        run_background_job(job, on_success)

    def export_archive_structure_from_selection() -> None:
        archive_text = state["mod_archive"].get().strip()
        if not archive_text:
            messagebox.showinfo("Choose archive", "Choose a source archive first.")
            return
        archive = Path(archive_text).expanduser()

        def job(job_log: Any) -> Tuple[Path, Path]:
            job_log(f"Exporting archive structure: {archive.name}")
            structure = archive_structure_report_for_archive(archive)
            json_path = archive.with_name(f"{archive.stem}_archive_structure.json")
            text_path = archive.with_name(f"{archive.stem}_archive_structure.txt")
            json_path.write_text(json.dumps(structure, indent=2, ensure_ascii=False), encoding="utf-8")
            text_path.write_text(archive_structure_report_to_text(structure), encoding="utf-8")
            return json_path, text_path

        def on_success(paths: Tuple[Path, Path]) -> None:
            json_path, text_path = paths
            log(f"Archive structure JSON: {public_path_text(json_path, bool(state['debug_mode'].get()))}")
            log(f"Archive structure text: {public_path_text(text_path, bool(state['debug_mode'].get()))}")
            messagebox.showinfo("Archive structure exported", f"Created:\n{public_path_text(text_path)}")

        run_background_job(job, on_success)

    def log_verification_summary(result: ArchiveConversionResult) -> None:
        if not result.verification:
            log("Post-build verification: NOT RUN")
            return
        verification = result.verification
        status = verification.report.get("status") or ("PASS" if verification.ok else "FAIL")
        log("Running verification")
        log(f"Post-build verification: {status}")
        if verification.report.get("warningCount"):
            log(f"Verification warnings: {verification.report.get('warningCount')}")
        if verification.report.get("errorCount"):
            log(f"Verification errors: {verification.report.get('errorCount')}")
        ocreatures_menu = verification.report.get("creatureMenuIntegration") if isinstance(verification.report.get("creatureMenuIntegration"), dict) else {}
        if ocreatures_menu and int(ocreatures_menu.get("creatureScenesWritten") or 0):
            log(
                "Creature menu entry generated: "
                f"{'yes' if ocreatures_menu.get('ocreaturesMenuEntryGenerated') else 'no'}; "
                f"{ocreatures_menu.get('creatureScenesReachableFromOCreaturesMenu', 0)}/"
                f"{ocreatures_menu.get('creatureScenesWritten', 0)} creature scenes reachable from OCreatures menu"
            )
        if verification.report_path:
            log(f"Verification JSON report: {public_path_text(verification.report_path, bool(state['debug_mode'].get()))}")
        if verification.text_report_path:
            log(f"Verification text report: {public_path_text(verification.text_report_path, bool(state['debug_mode'].get()))}")

    def show_build_done_message(result: ArchiveConversionResult) -> None:
        remember_operation("conversion", result)
        save_current_settings()
        log(f"ZIP created: {public_path_text(result.zip_path, bool(state['debug_mode'].get()))}")
        log_verification_summary(result)
        log(result_summary_text(result.report, result.verification, output_path=result.zip_path))
        log("Install steps:")
        log(install_steps_text(result.report, zip_name=result.zip_path.name))
        status = result.verification.report.get("status") if result.verification else "NOT RUN"
        if not result.verification:
            messagebox.showwarning(
                "Post-build verification incomplete",
                "Post-build verification did not complete. Do not install this ZIP.",
            )
        elif result.verification and not result.verification.ok:
            behavior_summary = result.verification.report.get("behaviorRegistrationSummary") if isinstance(result.verification.report.get("behaviorRegistrationSummary"), dict) else {}
            conflict_failure = behavior_summary.get("finalBehaviorValidationResult") == "FAIL"
            message = (
                "Build failed verification because the generated package contains duplicate or conflicting behavior registrations. "
                "Do not install this ZIP. Open the report for details."
                if conflict_failure
                else "Created ZIP, but verification failed.\n\nDo not install this ZIP yet."
            )
            messagebox.showwarning(
                "Build verification failed",
                f"{message}\n\nZIP:\n{public_path_text(result.zip_path)}\n\nReport:\n{public_path_text(result.verification.text_report_path)}",
            )
        elif status == "PASS WITH WARNINGS":
            messagebox.showwarning(
                "Build passed with warnings",
                f"Created ZIP and verification returned PASS WITH WARNINGS.\n\nWarnings: {result.verification.report.get('warningCount', 0) if result.verification else 0}\nReport:\n{public_path_text(result.verification.text_report_path if result.verification else None)}",
            )
        else:
            messagebox.showinfo(
                "Done",
                f"Build complete. Verification passed.\n\nInstall the generated ZIP, run Pandora, and enable/deploy Pandora output if your mod manager requires it.\n\nZIP:\n{public_path_text(result.zip_path)}\n\nStatus: {status}",
            )
        if result.verification and result.verification.ok and bool(state["open_output_after_build"].get()):
            open_path_in_shell(result.zip_path.parent)

